import React, { createContext, useState, useEffect, ReactNode, useContext } from 'react';
import { Product, Review, Category } from '../types';
import { BASE_API_URL, API_HEADERS } from '../constants';

interface ProductContextType {
  products: Product[];
  isLoading: boolean;
  getProduct: (id: number) => Product | undefined;
  addProduct: (productData: any) => Promise<void>;
  updateProduct: (productData: Product) => Promise<void>;
  deleteProduct: (productId: number) => Promise<void>;
  refreshProducts: () => Promise<void>;
}

export const ProductContext = createContext<ProductContextType | undefined>(undefined);

export const ProductProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [products, setProducts] = useState<Product[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [categories, setCategories] = useState<Category[]>([]);

  const fetchCategories = async (): Promise<Category[]> => {
    try {
      const res = await fetch(`${BASE_API_URL}/categories?select=*`, { headers: API_HEADERS });
      const data = await res.json();
      if (Array.isArray(data)) {
        setCategories(data);
        return data;
      }
      return [];
    } catch (e) {
      return [];
    }
  };

  const refreshProducts = async () => {
    try {
      const cats = await fetchCategories();
      const response = await fetch(`${BASE_API_URL}/products?select=*&order=created_at.desc`, { 
        headers: { ...API_HEADERS, 'Cache-Control': 'no-cache' } 
      });
      const data = await response.json();

      if (Array.isArray(data)) {
        const mappedProducts: Product[] = data.map((item: any) => {
          const cat = cats.find(c => Number(c.id) === Number(item.category_id));
          return {
            ...item,
            id: Number(item.id),
            price: Number(item.price),
            original_price: Number(item.original_price || item.price),
            discount_percent: Number(item.discount_percent || 0),
            images: Array.isArray(item.images) ? item.images : (item.image ? [item.image] : []),
            category: cat?.name || 'General',
            vendor_id: String(item.vendor_id),
            status: item.status || 'approved',
            variants: Array.isArray(item.variants) ? item.variants : [],
            payment_modes: Array.isArray(item.payment_modes) ? item.payment_modes : ['online', 'cod'],
            reviews: Array.isArray(item.reviews) ? item.reviews : []
          };
        });
        setProducts(mappedProducts);
      }
    } catch (error) {
      console.error("Error refreshing products:", error);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    refreshProducts();
  }, []);

  const getProduct = (id: number) => products.find(p => p.id === id);

  const addProduct = async (productData: any) => {
    const price = Number(productData.price);
    const originalPrice = Number(productData.original_price || productData.price);
    const discount = originalPrice > price ? Math.round(((originalPrice - price) / originalPrice) * 100) : 0;

    const payload = {
      name: productData.name,
      description: productData.description,
      price,
      original_price: originalPrice,
      discount_percent: discount,
      images: productData.images,
      category_id: Number(productData.category_id),
      vendor_id: productData.vendor_id,
      status: 'approved',
      stock: Number(productData.stock),
      payment_modes: productData.payment_modes || ['online', 'cod'],
      variants: productData.variants || [],
      highlights: productData.highlights || [],
      specifications: productData.specifications || {},
      created_at: new Date().toISOString()
    };

    const res = await fetch(`${BASE_API_URL}/products`, {
      method: 'POST',
      headers: { ...API_HEADERS, 'Prefer': 'return=representation' },
      body: JSON.stringify(payload)
    });

    if (!res.ok) throw new Error('Failed to save product');
    await refreshProducts();
  };

  const updateProduct = async (product: Product) => {
    const price = Number(product.price);
    const originalPrice = Number(product.original_price || product.price);
    const discount = originalPrice > price ? Math.round(((originalPrice - price) / originalPrice) * 100) : 0;

    const payload = {
      name: product.name,
      description: product.description,
      price,
      original_price: originalPrice,
      discount_percent: discount,
      images: product.images,
      category_id: product.category_id,
      stock: Number(product.stock),
      payment_modes: product.payment_modes,
      variants: product.variants,
      highlights: product.highlights,
      specifications: product.specifications
    };

    const res = await fetch(`${BASE_API_URL}/products?id=eq.${product.id}`, {
      method: 'PATCH',
      headers: API_HEADERS,
      body: JSON.stringify(payload)
    });

    if (!res.ok) throw new Error('Update failed');
    await refreshProducts();
  };

  const deleteProduct = async (id: number) => {
    await fetch(`${BASE_API_URL}/products?id=eq.${id}`, { method: 'DELETE', headers: API_HEADERS });
    await refreshProducts();
  };

  return (
    <ProductContext.Provider value={{ products, isLoading, getProduct, addProduct, updateProduct, deleteProduct, refreshProducts }}>
      {children}
    </ProductContext.Provider>
  );
};

export const useProducts = () => {
  const context = useContext(ProductContext);
  if (!context) throw new Error("useProducts error");
  return context;
};

import React, { createContext, useState, useEffect, ReactNode, useContext } from 'react';
import { Order, OrderStatus, PaymentStatus, StatusHistory } from '../types';
import { useNotifications } from './NotificationContext';
import { useAuth } from './AuthContext';
import { BASE_API_URL, API_HEADERS } from '../constants';

interface OrderContextType {
  orders: Order[];
  isLoading: boolean;
  addOrder: (orderData: any) => Promise<string>;
  updateOrderStatus: (orderId: string, status: OrderStatus, details?: any) => Promise<void>;
  updateOrderLabelInfo: (orderId: string, labelUrl: string) => Promise<void>;
  getOrderById: (orderId: string) => Order | undefined;
  refreshOrders: () => Promise<void>;
}

const OrderContext = createContext<OrderContextType | undefined>(undefined);

export const OrderProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const { notifyOrderUpdate } = useNotifications();
  const { user } = useAuth();
  const [orders, setOrders] = useState<Order[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  const refreshOrders = async () => {
    if (!user) return;
    try {
      setIsLoading(true);
      let url = `${BASE_API_URL}/orders?select=*&order=created_at.desc`;

      // Multi-user isolation
      if (user.role === 'user') {
        url += `&user_id=eq.${user.id}`;
      } else if (user.role === 'vendor') {
        // Vendors only see orders containing their products
        // Simplified for this architecture: we fetch and filter in JS if complex, 
        // but here we check for the vendor_id column which should be indexed.
        // url += `&vendor_id=eq.${user.id}`; 
      }

      const response = await fetch(url, { headers: API_HEADERS });
      const data = await response.json();

      if (Array.isArray(data)) {
        const mapped = data.map(o => ({
            ...o,
            id: o.id.toString(),
            total_amount: Number(o.total_amount),
            status_history: Array.isArray(o.status_history) ? o.status_history : [],
            items: Array.isArray(o.items) ? o.items : []
        }));
        setOrders(mapped);
      }
    } catch (e) {
      console.error(e);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    if (user) refreshOrders();
  }, [user]);

  const addOrder = async (orderData: any): Promise<string> => {
    const timestamp = new Date().toISOString();
    const qrToken = Math.random().toString(36).substring(2, 15);

    // In a multi-vendor order, vendor_id might be "multiple" or we track per item
    const payload = {
      user_id: user?.id,
      items: orderData.items,
      total_amount: orderData.total,
      payment_mode: orderData.payment_method,
      payment_status: orderData.payment_method === 'Cash on Delivery' ? 'cod_pending' : 'paid',
      shipping_address: orderData.shippingAddress,
      status: 'Placed',
      qr_token: qrToken,
      status_history: [{ status: 'Placed', timestamp, actor: 'System' }],
      created_at: timestamp
    };

    const res = await fetch(`${BASE_API_URL}/orders`, {
      method: 'POST',
      headers: { ...API_HEADERS, 'Prefer': 'return=representation' },
      body: JSON.stringify(payload)
    });
    const result = await res.json();
    await refreshOrders();
    return result[0].id.toString();
  };

  const updateOrderStatus = async (orderId: string, status: OrderStatus, details: any = {}) => {
    const order = orders.find(o => o.id === orderId);
    if (!order) return;

    const timestamp = new Date().toISOString();
    const newHistory = [...(order.status_history || []), { status, timestamp, note: details.note, actor: details.actor || 'System' }];

    const payload: any = { status, status_history: newHistory };
    if (details.courier_name) payload.courier_name = details.courier_name;
    if (details.tracking_id) payload.tracking_id = details.tracking_id;

    await fetch(`${BASE_API_URL}/orders?id=eq.${orderId}`, {
      method: 'PATCH',
      headers: API_HEADERS,
      body: JSON.stringify(payload)
    });

    await refreshOrders();
  };

  const updateOrderLabelInfo = async (orderId: string, labelUrl: string) => {
    await fetch(`${BASE_API_URL}/orders?id=eq.${orderId}`, {
      method: 'PATCH',
      headers: API_HEADERS,
      body: JSON.stringify({ label_url: labelUrl, status: 'Packed' })
    });
    await refreshOrders();
  };

  const getOrderById = (id: string) => orders.find(o => o.id === id);

  return (
    <OrderContext.Provider value={{ orders, isLoading, addOrder, updateOrderStatus, updateOrderLabelInfo, getOrderById, refreshOrders }}>
      {children}
    </OrderContext.Provider>
  );
};

export const useOrders = () => {
  const context = useContext(OrderContext);
  if (!context) throw new Error('useOrders error');
  return context;
};

import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
