              )}
          </div>
        </div>

        {/* Similar items */}
        {similarProducts.length > 0 && (
          <div className="pt-10 border-t border-border">
             <h2 className="text-sm font-black text-text-main italic tracking-widest uppercase mb-6">Discovery Queue</h2>
