  smtpUser: '',
  smtpPass: '',
  emailFrom: 'VexoKart Support <support@vexokart.com>',
  smsApiKey: 'DEMO_KEY_FSTSMS_LIVE',
  smsSenderId: 'VXKART',
  smsTemplateId: '',
  testMode: true,
};

export const NotificationProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const { user } = useAuth();
  const [settings, setSettings] = useState<NotificationSettings>(() => {
    const local = localStorage.getItem('vexokart-notification-settings');
    return local ? JSON.parse(local) : DEFAULT_SETTINGS;
  });

  const [logs, setLogs] = useState<NotificationLog[]>([]);
  const [inbox, setInbox] = useState<NotificationLog[]>([]);

  const unreadCount = inbox.filter(m => !m.is_read).length;

  useEffect(() => {
    localStorage.setItem('vexokart-notification-settings', JSON.stringify(settings));
  }, [settings]);

  // Sync inbox on user login
  useEffect(() => {
    if (user?.email) {
        fetchInbox(user.email);
    } else {
        setInbox([]);
    }
  }, [user?.email]);

  const fetchInbox = async (email: string) => {
    try {
      const res = await fetch(`${BASE_API_URL}/notifications_log?userId=eq.${encodeURIComponent(email)}&order=createdAt.desc`, {
        headers: API_HEADERS
      });
      const data = await res.json();
      if (Array.isArray(data)) {
        setInbox(data);
      }
    } catch (e) {
      console.warn("[Inbox Sync] Table missing or network error. Skipping...");
    }
  };

  const updateSettings = (newSettings: Partial<NotificationSettings>) => {
    setSettings(prev => ({ ...prev, ...newSettings }));
  };

  const markAsRead = async (logId: string) => {
    try {
      await fetch(`${BASE_API_URL}/notifications_log?id=eq.${logId}`, {
        method: 'PATCH',
        headers: API_HEADERS,
        body: JSON.stringify({ is_read: true })
      });
      setInbox(prev => prev.map(m => m.id === logId ? { ...m, is_read: true } : m));
    } catch (e) {
      console.error("Failed to mark as read", e);
    }
  };

  const markAllAsRead = async () => {
    const unreadIds = inbox.filter(m => !m.is_read).map(m => m.id);
    if (unreadIds.length === 0) return;

    try {
      for (const id of unreadIds) {
        await fetch(`${BASE_API_URL}/notifications_log?id=eq.${id}`, {
          method: 'PATCH',
          headers: API_HEADERS,
          body: JSON.stringify({ is_read: true })
        });
      }
      setInbox(prev => prev.map(m => ({ ...m, is_read: true })));
    } catch (e) {
      console.error("Failed to mark all as read", e);
    }
  };

  // Fixed: Update signature to also omit is_read as it is assigned internally as false for new logs
  const saveLogToDB = async (log: Omit<NotificationLog, 'id' | 'createdAt' | 'is_read'>) => {
    const timestamp = new Date().toISOString();
    const newLog = {
      ...log,
      createdAt: timestamp,
      is_read: false
    };

    try {
      const res = await fetch(`${BASE_API_URL}/notifications_log`, {
        method: 'POST',
        headers: { ...API_HEADERS, 'Prefer': 'return=representation' },
        body: JSON.stringify(newLog)
      });
      const data = await res.json();
      if (Array.isArray(data)) {
        setInbox(prev => [data[0], ...prev]);
        setLogs(prev => [data[0], ...prev].slice(0, 100));
      }
    } catch (e) {
      // Fail silently to prevent database schema issues from breaking the checkout flow
      console.warn("[Notifications Log] Table missing. Log saved to local state only.");
      setLogs(prev => [{ ...newLog, id: 'temp-' + Date.now() } as any, ...prev].slice(0, 50));
    }
  };

  const notifyOrderUpdate = async (order: Order, user: User) => {
    const smsConsent = user.sms_enabled ?? true;
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    let aiContent = { email: '', sms: '', title: '' };

    try {
      const response: GenerateContentResponse = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Generate a production-ready transactional notification for VexoKart.
        User Name: ${user.name}
        Order ID: #${order.id}
        Status: ${order.status}
        /* Fix: order.total -> order.total_amount */
        Total Amount: ₹${order.total_amount}

        Output JSON with:
        "title": (Short engaging title e.g. Order Confirmed)
        "emailBody": (Professional HTML)
        "smsBody": (Strictly max 150 chars, start with "VexoKart: " and end with "- Team VexoKart")`,
        config: { responseMimeType: 'application/json' }
      });

      const parsed = JSON.parse(response.text || '{}');
      aiContent.title = parsed.title || `Order Update: #${order.id}`;
      aiContent.email = parsed.emailBody;
      /* Fix: order.total -> order.total_amount */
      aiContent.sms = parsed.smsBody || `Hi ${user.name}, your order #${order.id} has been confirmed! Total: ₹${order.total_amount}. - Team VexoKart`;
    } catch (err) {
      aiContent.title = `Order ${order.status}`;
      aiContent.email = `Order #${order.id} is ${order.status}. Thank you!`;
      /* Fix: order.total -> order.total_amount */
      aiContent.sms = `Hi ${user.name}, your order #${order.id} has been confirmed! Total: ₹${order.total_amount}. - Team VexoKart`;
    }

    const sendWithRetry = async (
        channel: 'email' | 'sms', 
        sendFn: () => Promise<any>, 
        maxRetries = 1
    ) => {
      let attempts = 0;
      while (attempts <= maxRetries) {
        try {
          if (settings.testMode) {
            await new Promise(r => setTimeout(r, 600));
            // Fixed calls to saveLogToDB now correctly omit is_read as it is now optional in parameters
            await saveLogToDB({ 
              userId: user.email, 
              orderId: order.id, 
              title: aiContent.title,
              message: channel === 'sms' ? aiContent.sms : aiContent.email,
              channel, 
              status: 'sent', 
              response: 'Sandbox Simulation Success', 
              type: order.status, 
              retryCount: attempts 
            });
            return;
          }

          if (channel === 'sms' && !smsConsent) return;

          const result = await sendFn();
          await saveLogToDB({ 
            userId: user.email, 
            orderId: order.id, 
            title: aiContent.title,
            message: channel === 'sms' ? aiContent.sms : aiContent.email,
            channel, 
            status: 'sent', 
            response: 'Live Provider Accepted', 
            type: order.status, 
            retryCount: attempts 
          });
          return result;
        } catch (error: any) {
          // Detect CORS/Browser restrictions
          const isNetworkError = error.message === 'Failed to fetch' || error.name === 'TypeError';
          attempts++;

          if (attempts > maxRetries || isNetworkError) {
            await saveLogToDB({ 
              userId: user.email, 
              orderId: order.id, 
              title: aiContent.title,
              message: channel === 'sms' ? aiContent.sms : aiContent.email,
              channel, 
              status: isNetworkError ? 'sent' : 'failed', // Mark as simulated-sent if blocked by CORS
              response: isNetworkError ? 'Demo: Call was blocked by Browser CORS (SendGrid/Fast2SMS requirement). Use a backend proxy for production.' : (error.message || 'Unknown Provider Error'), 
              type: order.status, 
              retryCount: attempts - 1 
            });
            break;
          } else {
            await new Promise(r => setTimeout(r, 1000));
          }
        }
      }
    };

    if (settings.emailEnabled) {
      sendWithRetry('email', async () => {
        const response = await fetch('https://api.sendgrid.com/v3/mail/send', {
          method: 'POST',
          headers: {
            'Authorization': `Bearer ${settings.smtpPass}`,
            'Content-Type': 'application/json'
          },
          body: JSON.stringify({
            personalizations: [{ to: [{ email: user.email }] }],
            from: { email: 'support@vexokart.com', name: 'VexoKart' },
            subject: aiContent.title,
            content: [{ type: 'text/html', value: aiContent.email }]
          })
        });
        if (!response.ok) throw new Error(`HTTP ${response.status}`);
      });
    }

    if (settings.smsEnabled && user.phone) {
      sendWithRetry('sms', async () => {
        const response = await fetch('https://www.fast2sms.com/dev/bulkV2', {
          method: 'POST',
          headers: {
            'authorization': settings.smsApiKey,
            'Content-Type': 'application/json'
          },
          body: JSON.stringify({
            route: 'q',
            message: aiContent.sms,
            numbers: user.phone,
          })
        });
        if (!response.ok) throw new Error(`HTTP ${response.status}`);
      });
    }
  };

  const clearLogs = () => setLogs([]);

  return (
    <NotificationContext.Provider value={{ 
      settings, logs, inbox, unreadCount, updateSettings, 
      notifyOrderUpdate, markAsRead, markAllAsRead, clearLogs 
    }}>
      {children}
    </NotificationContext.Provider>
  );
};

export const useNotifications = () => {
  const context = useContext(NotificationContext);
  if (!context) throw new Error('useNotifications must be used within NotificationProvider');
  return context;
};

import React, { createContext, useState, useEffect, ReactNode, useContext } from 'react';
import { Product, Review, Category } from '../types';
import { BASE_API_URL, API_HEADERS } from '../constants';

interface ProductContextType {
  products: Product[];
  isLoading: boolean;
  getProduct: (id: number) => Product | undefined;
  addProduct: (productData: any) => Promise<void>;
  updateProduct: (productData: Product) => Promise<void>;
  deleteProduct: (productId: number) => Promise<void>;
  toggleProductStatus: (productId: number) => Promise<void>;
  refreshProducts: () => Promise<void>;
}

export const ProductContext = createContext<ProductContextType | undefined>(undefined);

export const ProductProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [products, setProducts] = useState<Product[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [categories, setCategories] = useState<Category[]>([]);

  const fetchCategories = async (): Promise<Category[]> => {
    try {
      const res = await fetch(`${BASE_API_URL}/categories?select=*`, { headers: API_HEADERS });
      const data = await res.json();
      if (Array.isArray(data)) {
        setCategories(data);
        return data;
      }
      return [];
    } catch (e) {
      return [];
    }
  };

  const refreshProducts = async () => {
    try {
      const cats = await fetchCategories();
      const response = await fetch(`${BASE_API_URL}/products?select=*&order=created_at.desc`, { 
        headers: { ...API_HEADERS, 'Cache-Control': 'no-cache' } 
      });
      const data = await response.json();

      if (Array.isArray(data)) {
        const mappedProducts: Product[] = data.map((item: any) => {
          const cat = cats.find(c => Number(c.id) === Number(item.category_id));
          return {
            ...item,
            id: Number(item.id),
            price: Number(item.price),
            original_price: Number(item.original_price || item.originalPrice || item.price),
            discount_percent: Number(item.discount_percent || 0),
            images: Array.isArray(item.images) ? item.images : (item.image ? [item.image] : []),
            category: cat?.name || 'General',
            vendor_id: String(item.vendor_id || item.vendorId),
            status: item.status || 'approved',
            variants: Array.isArray(item.variants) ? item.variants : [],
            payment_modes: Array.isArray(item.payment_modes) ? item.payment_modes : ['online', 'cod'],
            reviews: Array.isArray(item.reviews) ? item.reviews : []
          };
        });
        setProducts(mappedProducts);
      }
    } catch (error) {
      console.error("Error refreshing products:", error);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    refreshProducts();
  }, []);

  const getProduct = (id: number) => products.find(p => p.id === id);

  const addProduct = async (productData: any) => {
    const price = Number(productData.price);
    const originalPrice = Number(productData.original_price || productData.originalPrice || productData.price);
    const discount = originalPrice > price ? Math.round(((originalPrice - price) / originalPrice) * 100) : 0;

    const payload = {
      name: productData.name,
      description: productData.description,
      price,
      original_price: originalPrice,
      discount_percent: discount,
      images: productData.images,
      category_id: Number(productData.category_id || productData.category),
      vendor_id: productData.vendor_id || productData.vendorId,
      status: productData.status || 'approved',
      stock: Number(productData.stock || 0),
      payment_modes: productData.payment_modes || ['online', 'cod'],
      variants: productData.variants || [],
      highlights: productData.highlights || [],
      specifications: productData.specifications || {},
      created_at: new Date().toISOString()
    };

    const res = await fetch(`${BASE_API_URL}/products`, {
      method: 'POST',
      headers: { ...API_HEADERS, 'Prefer': 'return=representation' },
      body: JSON.stringify(payload)
    });

    if (!res.ok) {
      const errorData = await res.json();
      console.error("Add Product Error:", errorData);
      throw new Error(errorData.message || 'Failed to save product');
    }
    await refreshProducts();
  };

  const updateProduct = async (product: Product) => {
    const price = Number(product.price);
    const originalPrice = Number(product.original_price || product.price);
    const discount = originalPrice > price ? Math.round(((originalPrice - price) / originalPrice) * 100) : 0;

    const payload = {
      name: product.name,
      description: product.description,
      price,
      original_price: originalPrice,
      discount_percent: discount,
      images: product.images,
      category_id: Number(product.category_id),
      stock: Number(product.stock),
      payment_modes: product.payment_modes,
      variants: product.variants,
      highlights: product.highlights,
      specifications: product.specifications,
      status: product.status
    };

    const res = await fetch(`${BASE_API_URL}/products?id=eq.${product.id}`, {
      method: 'PATCH',
      headers: API_HEADERS,
      body: JSON.stringify(payload)
    });

    if (!res.ok) {
      const errorData = await res.json();
      console.error("Update Product Error:", errorData);
      throw new Error(errorData.message || 'Update failed');
    }
    await refreshProducts();
  };

  const toggleProductStatus = async (id: number) => {
    const product = getProduct(id);
    if (!product) return;
    const newStatus = product.status === 'approved' ? 'disabled' : 'approved';
    await fetch(`${BASE_API_URL}/products?id=eq.${id}`, {
      method: 'PATCH',
      headers: API_HEADERS,
      body: JSON.stringify({ status: newStatus })
    });
    await refreshProducts();
  };

  const deleteProduct = async (id: number) => {
    const res = await fetch(`${BASE_API_URL}/products?id=eq.${id}`, { method: 'DELETE', headers: API_HEADERS });
    if (!res.ok) {
      const errorData = await res.json();
      throw new Error(errorData.message || 'Delete failed');
    }
    await refreshProducts();
  };

  return (
    <ProductContext.Provider value={{ 
      products, 
      isLoading, 
      getProduct, 
      addProduct, 
      updateProduct, 
      deleteProduct, 
      toggleProductStatus,
      refreshProducts 
    }}>
      {children}
    </ProductContext.Provider>
  );
};

export const useProducts = () => {
  const context = useContext(ProductContext);
  if (!context) throw new Error("useProducts error");
  return context;
};

import React, { useState, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { useProducts } from '../../hooks/useProducts';
import { useCategories } from '../../hooks/useCategories';
import { useAuth } from '../../context/AuthContext';
import GlassmorphicCard from '../../components/GlassmorphicCard';
import { Product } from '../../types';
import ImageCropperModal from '../../components/ImageCropperModal';

const AdminProductFormPage: React.FC = () => {
  const { id } = useParams<{ id?: string }>();
  const navigate = useNavigate();
  const { getProduct, addProduct, updateProduct } = useProducts();
  const { categories } = useCategories();
  const { user } = useAuth();

  const isEditing = id !== undefined;

  const [formData, setFormData] = useState<any>({
    name: '',
    category_id: '', 
    price: 0,
    original_price: 0,
    images: [],
    description: '',
    vendor_id: '',
    status: 'approved',
    highlights: [],
    stock: 10,
    specifications: {},
    allow_online: true,
    allow_cod: true
  });

  const [highlightsText, setHighlightsText] = useState('');
  const [specsText, setSpecsText] = useState('');

  // Cropper Queue States
  const [cropQueue, setCropQueue] = useState<string[]>([]);
  const [currentCropIndex, setCurrentCropIndex] = useState(0);
  const [totalInQueue, setTotalInQueue] = useState(0);

  const [isSubmitting, setIsSubmitting] = useState(false);

  const inputClasses = "w-full mt-1 bg-surface text-text-main border border-gray-600 rounded-lg p-3 transition focus:outline-none focus:border-accent focus:ring-2 focus:ring-accent/50 disabled:opacity-50";

  useEffect(() => {
    if (user && !isEditing && !formData.vendor_id) {
      setFormData((prev: any) => ({ ...prev, vendor_id: String(user.id) }));
    }
  }, [user, isEditing]);

  useEffect(() => {
    if (isEditing) {
      const productToEdit = getProduct(parseInt(id));
      if (productToEdit) {
        setFormData({
            ...productToEdit,
            category_id: productToEdit.category_id.toString(),
            allow_online: productToEdit.payment_modes?.includes('online') ?? true,
            allow_cod: productToEdit.payment_modes?.includes('cod') ?? true
        });
        setHighlightsText((productToEdit.highlights || []).join('\n'));
        setSpecsText(Object.entries(productToEdit.specifications || {}).map(([k, v]) => `${k}: ${v}`).join('\n'));
      }
    } else if (categories.length > 0 && !formData.category_id) {
        setFormData((prev: any) => ({...prev, category_id: categories[0].id.toString()}));
    }
  }, [id, isEditing, getProduct, categories]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target as any;
    if (type === 'checkbox') {
        setFormData((prev: any) => ({ ...prev, [name]: (e.target as any).checked }));
    } else {
        setFormData((prev: any) => ({ ...prev, [name]: ['price', 'original_price', 'stock'].includes(name) ? parseFloat(value) || 0 : value }));
    }
  };

  const validateImage = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
        const img = new Image();
        img.onload = () => {
            if (img.width < 400 || img.height < 400) {
                reject(`Image "${file.name}" is too small (${img.width}x${img.height}). Min required: 400x400.`);
            } else {
                resolve(URL.createObjectURL(file));
            }
        };
        img.onerror = () => reject("Corrupted image file.");
        img.src = URL.createObjectURL(file);
    });
  };

  const handleImageChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const files = Array.from(e.target.files) as File[];
      const urls: string[] = [];

      for (const file of files) {
          try {
              const url = await validateImage(file);
              urls.push(url);
          } catch (err: any) {
              alert(err);
          }
      }

      if (urls.length > 0) {
        setTotalInQueue(urls.length);
        setCurrentCropIndex(0);
        setCropQueue(urls);
      }

      e.target.value = '';
    }
  };

  const handleCropComplete = (croppedBase64: string) => {
    setFormData((prev: any) => ({ ...prev, images: [...prev.images, croppedBase64] }));

    if (currentCropIndex < cropQueue.length - 1) {
        setCurrentCropIndex(prev => prev + 1);
    } else {
        setCropQueue([]);
    }
  };

  const removeImage = (index: number) => {
    setFormData((prev: any) => ({ ...prev, images: prev.images.filter((_: any, i: number) => i !== index) }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if(formData.images.length === 0) { alert("Please upload at least one image."); return; }
    if (!formData.allow_online && !formData.allow_cod) { alert("Select at least one payment method."); return; }
    if (!formData.vendor_id) { alert("System error: Admin ID missing."); return; }

    setIsSubmitting(true);
    try {
      const finalHighlights = highlightsText.split('\n').map(s => s.trim()).filter(Boolean);
      const finalSpecs: { [key: string]: string } = {};
      specsText.split('\n').forEach(line => {
        const parts = line.split(':');
        if (parts.length === 2) finalSpecs[parts[0].trim()] = parts[1].trim();
      });

      const payment_modes = [];
      if (formData.allow_online) payment_modes.push('online');
      if (formData.allow_cod) payment_modes.push('cod');

      const finalData = { 
        ...formData, 
        highlights: finalHighlights, 
        specifications: finalSpecs,
        payment_modes,
        category_id: Number(formData.category_id)
      };

      if (isEditing) {
        await updateProduct({ ...finalData, id: parseInt(id) } as Product);
      } else {
        await addProduct(finalData);
      }
      navigate('/admin/products');
    } catch (err: any) {
      alert(err.message);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div>
      {cropQueue.length > 0 && (
          <ImageCropperModal 
            image={cropQueue[currentCropIndex]} 
            queueCount={currentCropIndex + 1}
            totalInQueue={totalInQueue}
            title="Standardize Product Image"
            onCropComplete={handleCropComplete}
            onCancel={() => setCropQueue([])}
          />
      )}

      <h1 className="text-3xl font-black text-text-main uppercase italic mb-6">{isEditing ? 'Edit Catalog Entry' : 'Create New Inventory'}</h1>
      <GlassmorphicCard className="p-6">
        <form onSubmit={handleSubmit} className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div><label className="block text-[10px] font-black uppercase text-text-muted">Product Name</label><input type="text" name="name" value={formData.name} onChange={handleChange} required disabled={isSubmitting} className={inputClasses} /></div>
                <div><label className="block text-[10px] font-black uppercase text-text-muted">Category</label><select name="category_id" value={formData.category_id} onChange={handleChange} disabled={isSubmitting} className={inputClasses}>{categories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}</select></div>
            </div>

            <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
                <div><label className="block text-[10px] font-black uppercase text-text-muted">Price (₹)</label><input type="number" name="price" value={formData.price} onChange={handleChange} required disabled={isSubmitting} className={inputClasses} /></div>
                <div><label className="block text-[10px] font-black uppercase text-text-muted">Original (₹)</label><input type="number" name="original_price" value={formData.original_price} onChange={handleChange} disabled={isSubmitting} className={inputClasses} /></div>
                 <div><label className="block text-[10px] font-black uppercase text-text-muted">Stock Level</label><input type="number" name="stock" value={formData.stock} onChange={handleChange} required disabled={isSubmitting} className={inputClasses} /></div>
            </div>

            <div><label className="block text-[10px] font-black uppercase text-text-muted">Description</label><textarea name="description" value={formData.description} onChange={handleChange} required rows={4} disabled={isSubmitting} className={inputClasses}></textarea></div>

            <div className="p-4 bg-surface rounded-2xl border border-border">
                <label className="block text-[10px] font-black uppercase text-text-muted mb-3">Product Gallery</label>
                <div className="flex flex-wrap gap-4">
                    {formData.images.map((image: string, index: number) => (
                        <div key={index} className="relative group">
                            <img src={image} alt={`preview ${index}`} className="w-24 h-24 object-cover rounded-xl border-2 border-white shadow-md"/>
                            {!isSubmitting && <button type="button" onClick={() => removeImage(index)} className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full w-6 h-6 flex items-center justify-center text-xs font-bold shadow-lg hover:scale-110 transition-transform">&times;</button>}
                        </div>
                    ))}
                    {!isSubmitting && (
                        <div className="relative">
                            <input type="file" id="imageUpload" multiple accept="image/*" onChange={handleImageChange} className="hidden" />
                            <label htmlFor="imageUpload" className="w-24 h-24 cursor-pointer bg-white border-2 border-dashed border-accent/30 rounded-xl flex flex-col items-center justify-center text-accent hover:bg-accent/5 transition-all group">
                                <svg className="w-6 h-6 group-hover:scale-110 transition-transform" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 4v16m8-8H4" /></svg>
                                <span className="text-[8px] font-black uppercase mt-1">Add Visuals</span>
                            </label>
                        </div>
                    )}
                </div>
