export const createImage = (url: string): Promise<HTMLImageElement> =>
  new Promise((resolve, reject) => {
    const image = new Image();
    image.addEventListener('load', () => resolve(image));
    image.addEventListener('error', (error) => reject(error));
    image.setAttribute('crossOrigin', 'anonymous');
    image.src = url;
  });

export function getRadianAngle(degreeValue: number) {
  return (degreeValue * Math.PI) / 180;
}

/**
 * Returns the new bounding area of a rotated rectangle.
 */
export function rotateSize(width: number, height: number, rotation: number) {
  const rotRad = getRadianAngle(rotation);

  return {
    width:
      Math.abs(Math.cos(rotRad) * width) + Math.abs(Math.sin(rotRad) * height),
    height:
      Math.abs(Math.sin(rotRad) * width) + Math.abs(Math.cos(rotRad) * height),
  };
}

/**
 * This function takes an image source and pixel crop coordinates 
 * and returns the cropped image as an optimized base64 string.
 */
export async function getCroppedImg(
  imageSrc: string,
  pixelCrop: { x: number; y: number; width: number; height: number },
  rotation = 0,
  flip = { horizontal: false, vertical: false }
): Promise<string> {
  const image = await createImage(imageSrc);
  const canvas = document.createElement('canvas');
  const ctx = canvas.getContext('2d');

  if (!ctx) {
    throw new Error('No 2d context');
  }

  const rotRad = getRadianAngle(rotation);

  // Calculate bounding box of the rotated image
  const { width: bBoxWidth, height: bBoxHeight } = rotateSize(
    image.width,
    image.height,
    rotation
  );

  // Set canvas size to match the bounding box
  canvas.width = bBoxWidth;
  canvas.height = bBoxHeight;

  // Translate canvas context to a central point and draw image
  ctx.translate(bBoxWidth / 2, bBoxHeight / 2);
  ctx.rotate(rotRad);
  ctx.scale(flip.horizontal ? -1 : 1, flip.vertical ? -1 : 1);
  ctx.translate(-image.width / 2, -image.height / 2);

  // Draw rotated image
  ctx.drawImage(image, 0, 0);

  // Second canvas for the actual crop extraction
  const croppedCanvas = document.createElement('canvas');
  const croppedCtx = croppedCanvas.getContext('2d');

  if (!croppedCtx) {
    throw new Error('No 2d context for crop');
  }

  // Set the size of the final cropped canvas (Limit max dimensions to 800px)
  const maxDim = 800;
  let finalWidth = pixelCrop.width;
  let finalHeight = pixelCrop.height;

  if (finalWidth > maxDim) {
      finalHeight = (maxDim / finalWidth) * finalHeight;
      finalWidth = maxDim;
  }

  croppedCanvas.width = finalWidth;
  croppedCanvas.height = finalHeight;

  // Extract and scale the cropped pixels
  croppedCtx.drawImage(
    canvas,
    pixelCrop.x, pixelCrop.y, pixelCrop.width, pixelCrop.height,
    0, 0, finalWidth, finalHeight
  );

  // Optimization: Compress to JPEG 0.5 (50%) to stay under DB size limits for base64
  return new Promise((resolve) => {
    resolve(croppedCanvas.toDataURL('image/jpeg', 0.5));
  });
}

import React, { createContext, useState, useEffect, ReactNode, useContext } from 'react';
import { Product, Review, Category } from '../types';
import { BASE_API_URL, API_HEADERS } from '../constants';

interface ProductContextType {
  products: Product[];
  isLoading: boolean;
  getProduct: (id: number) => Product | undefined;
  addProduct: (productData: any) => Promise<void>;
  updateProduct: (productData: Product) => Promise<void>;
  deleteProduct: (productId: number) => Promise<void>;
  toggleProductStatus: (productId: number) => Promise<void>;
  refreshProducts: () => Promise<void>;
}

export const ProductContext = createContext<ProductContextType | undefined>(undefined);

export const ProductProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [products, setProducts] = useState<Product[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [categories, setCategories] = useState<Category[]>([]);

  const fetchCategories = async (): Promise<Category[]> => {
    try {
      const res = await fetch(`${BASE_API_URL}/categories?select=*`, { headers: API_HEADERS });
      const data = await res.json();
      if (Array.isArray(data)) {
        setCategories(data);
        return data;
      }
      return [];
    } catch (e) {
      return [];
    }
  };

  const refreshProducts = async () => {
    try {
      const cats = await fetchCategories();
      const response = await fetch(`${BASE_API_URL}/products?select=*&order=created_at.desc`, { 
        headers: { ...API_HEADERS, 'Cache-Control': 'no-cache' } 
      });
      const data = await response.json();

      if (Array.isArray(data)) {
        const mappedProducts: Product[] = data.map((item: any) => {
          const cat = cats.find(c => Number(c.id) === Number(item.category_id));
          const price = Number(item.price);
          const originalPrice = Number(item.original_price || item.originalPrice || item.price);
          return {
            ...item,
            id: Number(item.id),
            price: price,
            original_price: originalPrice,
            discount_percent: originalPrice > price ? Math.round(((originalPrice - price) / originalPrice) * 100) : 0,
            images: Array.isArray(item.images) ? item.images : (item.image ? [item.image] : []),
            category: cat?.name || 'General',
            vendor_id: String(item.vendor_id || item.vendorId),
            status: item.status || 'approved',
            variants: Array.isArray(item.variants) ? item.variants : [],
            payment_modes: Array.isArray(item.payment_modes) ? item.payment_modes : ['online', 'cod'],
            reviews: Array.isArray(item.reviews) ? item.reviews : []
          };
        });
        setProducts(mappedProducts);
      }
    } catch (error) {
      console.error("Error refreshing products:", error);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    refreshProducts();
  }, []);

  const getProduct = (id: number) => products.find(p => p.id === id);

  const addProduct = async (productData: any) => {
    const price = Number(productData.price);
    const originalPrice = Number(productData.original_price || productData.originalPrice || productData.price);

    // Removed 'discount_percent' as it's a derived field and missing from database schema
    const payload = {
      name: productData.name,
      description: productData.description,
      price,
      original_price: originalPrice,
      images: productData.images, 
      image: productData.images?.[0] || '', 
      category_id: Number(productData.category_id || productData.category),
      vendor_id: String(productData.vendor_id || productData.vendorId),
      status: productData.status || 'approved',
      stock: Number(productData.stock || 0),
      payment_modes: productData.payment_modes || ['online', 'cod'],
      variants: productData.variants || [],
      highlights: productData.highlights || [],
      specifications: productData.specifications || {},
      created_at: new Date().toISOString()
    };

    const res = await fetch(`${BASE_API_URL}/products`, {
      method: 'POST',
      headers: { ...API_HEADERS, 'Prefer': 'return=representation' },
      body: JSON.stringify(payload)
    });

    if (!res.ok) {
      const errorData = await res.json();
      console.error("Add Product Error Details:", JSON.stringify(errorData, null, 2));
      const errMsg = errorData.message || errorData.details || 'Internal Database Error';
      const errHint = errorData.hint ? ` (Hint: ${errorData.hint})` : '';
      throw new Error(`${errMsg}${errHint}`);
    }
    await refreshProducts();
  };

  const updateProduct = async (product: Product) => {
    const price = Number(product.price);
    const originalPrice = Number(product.original_price || product.price);

    const payload = {
      name: product.name,
      description: product.description,
      price,
      original_price: originalPrice,
      images: product.images,
      image: product.images?.[0] || '', 
      category_id: Number(product.category_id),
      stock: Number(product.stock),
      payment_modes: product.payment_modes,
      variants: product.variants,
      highlights: product.highlights,
      specifications: product.specifications,
      status: product.status
    };

    const res = await fetch(`${BASE_API_URL}/products?id=eq.${product.id}`, {
      method: 'PATCH',
      headers: API_HEADERS,
      body: JSON.stringify(payload)
    });

    if (!res.ok) {
      const errorData = await res.json();
      console.error("Update Product Error Details:", JSON.stringify(errorData, null, 2));
      const errMsg = errorData.message || errorData.details || 'Update Failed';
      throw new Error(errMsg);
    }
    await refreshProducts();
  };

  const toggleProductStatus = async (id: number) => {
    const product = getProduct(id);
    if (!product) return;
    const newStatus = product.status === 'approved' ? 'disabled' : 'approved';
    await fetch(`${BASE_API_URL}/products?id=eq.${id}`, {
      method: 'PATCH',
      headers: API_HEADERS,
      body: JSON.stringify({ status: newStatus })
    });
    await refreshProducts();
  };

  const deleteProduct = async (id: number) => {
    const res = await fetch(`${BASE_API_URL}/products?id=eq.${id}`, { method: 'DELETE', headers: API_HEADERS });
    if (!res.ok) {
      const errorData = await res.json();
      throw new Error(errorData.message || 'Delete failed');
    }
    await refreshProducts();
  };

  return (
    <ProductContext.Provider value={{ 
      products, 
      isLoading, 
      getProduct, 
      addProduct, 
      updateProduct, 
      deleteProduct, 
      toggleProductStatus,
      refreshProducts 
    }}>
      {children}
    </ProductContext.Provider>
  );
};

export const useProducts = () => {
  const context = useContext(ProductContext);
  if (!context) throw new Error("useProducts error");
  return context;
};

