  useEffect(() => {
    refreshOrders();
    refreshProducts();
  }, []);

  const safeOrders = Array.isArray(orders) ? orders : [];
  const safeProducts = Array.isArray(products) ? products : [];

  // CRITICAL FIX: Filtering strictly by vendor_id column
