import React, { createContext, useState, useEffect, ReactNode, useContext } from 'react';
import { Order, OrderStatus, PaymentStatus, StatusHistory } from '../types';
import { useNotifications } from './NotificationContext';
import { useAuth } from './AuthContext';
import { BASE_API_URL, API_HEADERS, EDGE_FUNCTION_URL, SUPABASE_URL, SUPABASE_KEY } from '../constants';

interface OrderContextType {
  orders: Order[];
  isLoading: boolean;
  addOrder: (orderData: any) => Promise<string>;
  updateOrderStatus: (orderId: string, status: OrderStatus, details?: any) => Promise<void>;
  createPaymentOrder: (amount: number) => Promise<{ id: string; amount: number }>;
  verifyPayment: (paymentData: any) => Promise<boolean>;
  generateShippingLabel: (orderId: string) => Promise<string>;
  getOrderById: (orderId: string) => Order | undefined;
  getOrderByToken: (token: string) => Order | undefined;
  updateOrderByToken: (token: string, status: OrderStatus, note?: string) => Promise<{ success: boolean; message: string }>;
  refreshOrders: () => Promise<void>;
}

const OrderContext = createContext<OrderContextType | undefined>(undefined);

export const OrderProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const { notifyOrderUpdate } = useNotifications();
  const { user } = useAuth();
  const [orders, setOrders] = useState<Order[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  const refreshOrders = async () => {
    if (!user) return;
    try {
      setIsLoading(true);
      let url = `${BASE_API_URL}/orders?select=*&order=created_at.desc`;

      if (user.role === 'user') {
        url += `&user_id=eq.${user.id}`;
      }

      const response = await fetch(url, { 
        headers: { ...API_HEADERS, 'Cache-Control': 'no-cache' } 
      });

      if (!response.ok) throw new Error(`Fetch failed with status ${response.status}`);

      const data = await response.json();

      if (Array.isArray(data)) {
        const mapped = data.map(o => ({
            ...o,
            id: o.id.toString(),
            total: Number(o.total_amount || 0),
            total_amount: Number(o.total_amount || 0),
            shippingAddress: (o.shipping_address && typeof o.shipping_address === 'object') 
                ? o.shipping_address 
                : (user.addresses?.find(a => a.id === String(o.shipping_address)) || {}),
            statusHistory: o.status_history || [],
            qrToken: o.qr_token,
            date: o.created_at,
            userEmail: user.email 
        }));
        setOrders(mapped);
      }
    } catch (e) {
      console.error("[OrderContext] refreshOrders error:", e);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    if (user) refreshOrders();
  }, [user]);

  const addOrder = async (orderData: any): Promise<string> => {
    const timestamp = new Date().toISOString();
    const qrToken = Math.random().toString(36).substring(2, 15);

    const numericTotal = Number(orderData.total);
    const numericUserId = Number(user?.id);
    const numericAddressId = orderData.shippingAddress?.id ? Number(orderData.shippingAddress.id) : null;

    if (isNaN(numericTotal)) throw new Error("Order calculation failed: invalid numeric total.");
    if (!numericAddressId || isNaN(numericAddressId)) throw new Error("Delivery destination missing: invalid address ID.");

    const payload = {
      user_id: numericUserId,
      vendor_id: orderData.items[0]?.vendorId || 'multiple',
      items: orderData.items,
      total_amount: numericTotal, 
      payment_mode: orderData.payment_method,
      payment_status: orderData.payment_method === 'Cash on Delivery' ? 'cod_pending' : 'failed',
      shipping_address: numericAddressId,
      status: 'Placed',
      qr_token: qrToken,
      status_history: [{ status: 'Placed', timestamp, actor: 'User' }],
      created_at: timestamp
    };

    try {
        const res = await fetch(`${BASE_API_URL}/orders`, {
          method: 'POST',
          headers: { ...API_HEADERS, 'Prefer': 'return=representation' },
          body: JSON.stringify(payload)
        });

        if (!res.ok) {
            const errorData = await res.json().catch(() => ({}));
            console.error("[OrderContext] Database Rejection:", JSON.stringify(errorData));
            throw new Error(errorData.message || `Order initialization rejected by server.`);
        }

        const result = await res.json();
        await refreshOrders();
        return result[0].id.toString();
    } catch (err: any) {
        console.error("[OrderContext] addOrder Exception:", err.message);
        throw err;
    }
  };

  /**
   * CRITICAL: Using 'super-handler' Edge Function for live payment orchestration.
   * STRICT: Uses full URL and mandatory security headers.
   */
  const createPaymentOrder = async (amount: number): Promise<{ id: string; amount: number }> => {
    const apiEndpoint = "https://ghzadiplpazekzgjbdxu.supabase.co/functions/v1/super-handler";

    try {
        const response = await fetch(apiEndpoint, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'apikey': SUPABASE_KEY,
            'Authorization': `Bearer ${SUPABASE_KEY}`
          },
          body: JSON.stringify({ 
            amount: Number(amount) 
          })
        });

        if (!response.ok) {
          const errorText = await response.text();
          throw new Error(`Edge Function Rejected Request (${response.status}): ${errorText || 'Server Error'}`);
        }

        const data = await response.json();
        if (!data.id) throw new Error("Gateway Response Error: Order identity missing from response.");

        // Response contains { id, amount, currency, status }
        return { 
          id: data.id, 
          amount: data.amount 
        }; 
    } catch (err: any) {
        console.error("[Razorpay Production Sync] Critical Failure:", err.message);
        // Special handling for 'Failed to fetch' which is common in restricted browser environments
        if (err.message === 'Failed to fetch') {
            throw new Error("SECURE GATEWAY BLOCKED: The connection to the payment server was blocked by your browser or a network restriction. Please ensure you are not using a restricted preview/iframe and try again.");
        }
        throw err;
    }
  };

  const verifyPayment = async (paymentData: any): Promise<boolean> => {
    try {
        const res = await fetch(`${EDGE_FUNCTION_URL}/verify_payment`, {
          method: 'POST',
          headers: { ...API_HEADERS },
          body: JSON.stringify(paymentData)
        });

        if (res.ok) {
            const data = await res.json();
            if (data.success) {
                await fetch(`${BASE_API_URL}/orders?id=eq.${paymentData.orderId}`, {
                    method: 'PATCH',
                    headers: { ...API_HEADERS, 'Prefer': 'return=minimal' },
                    body: JSON.stringify({ payment_status: 'paid' })
                });
                await refreshOrders();
                return true;
            }
        }
        return false;
    } catch (err: any) {
        console.error("[OrderContext] verifyPayment Exception:", err);
        return false;
    }
  };

  const generateShippingLabel = async (orderId: string): Promise<string> => {
    try {
        const res = await fetch(`${EDGE_FUNCTION_URL}/generate_shipping_label`, {
          method: 'POST',
          headers: { ...API_HEADERS },
          body: JSON.stringify({ orderId })
        });

        if (res.ok) {
            const data = await res.json();
            await fetch(`${BASE_API_URL}/orders?id=eq.${orderId}`, {
                method: 'PATCH',
                headers: { ...API_HEADERS, 'Prefer': 'return=minimal' },
                body: JSON.stringify({ label_url: data.label_url, status: 'Packed' })
            });
            await refreshOrders();
            return data.label_url;
        }
        throw new Error("Logistics sync failed");
    } catch (err: any) {
        const mockLabelUrl = `https://api.qrserver.com/v1/create-qr-code/?size=300x300&data=SHIP-${orderId}`;
        await fetch(`${BASE_API_URL}/orders?id=eq.${orderId}`, {
            method: 'PATCH',
            headers: { ...API_HEADERS, 'Prefer': 'return=minimal' },
            body: JSON.stringify({ label_url: mockLabelUrl, status: 'Packed' })
        });
        await refreshOrders();
        return mockLabelUrl;
    }
  };

  const updateOrderStatus = async (orderId: string, status: OrderStatus, details: any = {}) => {
    const order = orders.find(o => o.id === orderId);
    if (!order) return;

    try {
        const timestamp = new Date().toISOString();
        const currentHistory = order.statusHistory || [];
        const newHistory = [...currentHistory, { 
            status, 
            timestamp, 
            note: details.note, 
            actor: details.actor || 'System' 
        }];

        const payload: any = { status, status_history: newHistory };
        if (details.courier_name || details.courierName) payload.courier_name = details.courier_name || details.courierName;
        if (details.tracking_id || details.trackingId) payload.tracking_id = details.tracking_id || details.trackingId;

        await fetch(`${BASE_API_URL}/orders?id=eq.${orderId}`, {
          method: 'PATCH',
          headers: { ...API_HEADERS, 'Prefer': 'return=minimal' },
          body: JSON.stringify(payload)
        });

        fetch(`${EDGE_FUNCTION_URL}/send_notification`, {
            method: 'POST',
            headers: API_HEADERS,
            body: JSON.stringify({ orderId, status })
        }).catch(() => {});

        await refreshOrders();
    } catch (err) {
        console.error("[OrderContext] updateOrderStatus Exception:", err);
    }
  };

  const getOrderById = (id: string) => orders.find(o => o.id === id);
  const getOrderByToken = (token: string) => orders.find(o => o.qrToken === token);

  const updateOrderByToken = async (token: string, status: OrderStatus, note?: string) => {
    const order = getOrderByToken(token);
    if (!order) return { success: false, message: 'Invalid manifest token.' };

    try {
        await updateOrderStatus(order.id, status, { note, actor: 'Courier' });
        return { success: true, message: `Status updated to ${status}.` };
    } catch (e) {
        return { success: false, message: 'Fulfillment sync failed.' };
    }
  };

  return (
    <OrderContext.Provider value={{ 
        orders, isLoading, addOrder, updateOrderStatus, 
        createPaymentOrder, verifyPayment, generateShippingLabel, 
        getOrderById, getOrderByToken, updateOrderByToken, refreshOrders 
    }}>
      {children}
    </OrderContext.Provider>
  );
};

export const useOrders = () => {
  const context = useContext(OrderContext);
  if (!context) throw new Error('OrderContext missing');
  return context;
};

import React, { useState, useEffect, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { useCart } from '../hooks/useCart';
import { useAuth } from '../context/AuthContext';
import { useOrders } from '../context/OrderContext';
import GlassmorphicCard from '../components/GlassmorphicCard';
import { ChevronLeftIcon } from '../components/icons/ChevronLeftIcon';
import { Address, OrderItem } from '../types';

/**
 * CRITICAL: Production LIVE Razorpay Configuration
 * Settlement identity: VexoKart Live Settlement Hub
 */
const RAZORPAY_LIVE_KEY_ID = 'rzp_live_RxmIholkGEOYaL'; 

const CheckoutPage: React.FC = () => {
  const { cartItems, cartTotal, clearCart } = useCart();
  const { user } = useAuth();
  const { addOrder, createPaymentOrder, verifyPayment } = useOrders();
  const navigate = useNavigate();

  const canPayOnline = useMemo(() => cartItems.every(item => item.payment_modes?.includes('online') ?? true), [cartItems]);
  const canPayCOD = useMemo(() => cartItems.every(item => item.payment_modes?.includes('cod') ?? true), [cartItems]);

  const [paymentMethod, setPaymentMethod] = useState<'card' | 'cod'>(canPayOnline ? 'card' : 'cod');
  const [isProcessing, setIsProcessing] = useState(false);
  const [selectedAddress, setSelectedAddress] = useState<Address | null>(null);

  useEffect(() => {
    if (user?.addresses && user.addresses.length > 0) {
      setSelectedAddress(user.addresses[0]);
    }
  }, [user]);

  /**
   * PRODUCTION SECURITY: ENVIRONMENT VALIDATION
   * Live payments MUST NOT run in restricted iframes, simulation previews, or Bolt/StackBlitz sandboxes.
   */
  const checkExecutionEnvironment = () => {
    // 1. Check if inside an iframe
    const isIframe = window.self !== window.top;

    // 2. Check for common preview/restricted hostnames
    const hostname = window.location.hostname;
    const isRestrictedHost = hostname.includes('stackblitz') || 
                             hostname.includes('webcontainer') ||
                             hostname.includes('bolt') ||
                             hostname.includes('preview');

    return !(isIframe || isRestrictedHost);
  };

  const handlePlaceOrder = async () => {
    if (!selectedAddress || !user) {
      alert("Please select a valid delivery destination.");
      return;
    }

    // STRICT: Block live transactions in restricted environments
    if (paymentMethod === 'card' && !checkExecutionEnvironment()) {
        alert("LIVE PRODUCTION SECURITY: Live payments can only be completed in a real browser environment. Please open VexoKart in a new tab or a full browser window to settle payment.");
        return;
    }

    if (typeof cartTotal !== 'number' || isNaN(cartTotal) || cartTotal <= 0) {
      alert("System Alert: Order total integrity check failed. Please refresh your bag.");
      return;
    }

    setIsProcessing(true);

    try {
      const orderItems: OrderItem[] = cartItems.map(item => ({
          id: item.id,
          name: item.name,
          price: item.price,
          quantity: item.quantity,
          image: item.images[0],
          vendorId: item.vendor_id,
          color: item.selectedColor,
          size: item.selectedSize
      }));

      const orderPayload = {
          items: orderItems,
          total: cartTotal, 
          shippingAddress: selectedAddress, 
          payment_method: paymentMethod === 'cod' ? 'Cash on Delivery' : 'Online Payment'
      };

      // 1. DATA LAYER: Initialize Order Record in Database
      const newOrderId = await addOrder(orderPayload);

      if (paymentMethod === 'cod') {
        alert("Order Success! Please keep cash ready for delivery.");
        clearCart();
        navigate('/orders');
        return;
      }

      // 2. SETTLEMENT LAYER: Create Live Razorpay Order via Supabase Edge Function
      const rzpResponse = await createPaymentOrder(cartTotal);

      // 3. UI LAYER: Launch Official Razorpay Secure Checkout Popup
      if (!(window as any).Razorpay) {
        throw new Error("Razorpay Gateway Error: SDK not detected. Please disable ad-blockers and reload the page.");
      }

      const options = {
        key: RAZORPAY_LIVE_KEY_ID,
        amount: rzpResponse.amount, // Exactly as returned by the backend (usually Paise)
        currency: 'INR',
        name: 'VexoKart Secure Settlement',
        description: `Reference #${newOrderId}`,
        image: 'https://ghzadiplpazekzgjbdxu.supabase.co/storage/v1/object/public/assets/logo-icon.png',
        order_id: rzpResponse.id, // Mandatory live Order ID
        handler: async (paymentResponse: any) => {
          setIsProcessing(true);
          try {
              // 4. VERIFICATION LAYER: Production Digital Signature Verification
              const isVerified = await verifyPayment({
                orderId: newOrderId,
                razorpay_order_id: paymentResponse.razorpay_order_id,
                razorpay_payment_id: paymentResponse.razorpay_payment_id,
                razorpay_signature: paymentResponse.razorpay_signature
              });

              if (isVerified) {
                alert("Settlement Successful! Your order is being processed for dispatch.");
                clearCart();
                navigate('/orders');
              } else {
                alert("Security Protocol Alert: Digital verification failed. This transaction is pending manual audit.");
                setIsProcessing(false);
              }
          } catch (e) {
              console.error("[Settlement Verification] Critical Error:", e);
              alert("A system error occurred during verification. Your payment is safe and will be audited manually.");
              setIsProcessing(false);
          }
        },
        prefill: {
          name: user.name,
          email: user.email,
          contact: selectedAddress.phone,
        },
        modal: {
          ondismiss: () => {
            console.log("Settlement flow closed by user.");
            setIsProcessing(false);
          }
        },
        theme: { color: '#FF8A00' },
      };

      const rzp = new (window as any).Razorpay(options);

      rzp.on('payment.failed', (failResponse: any) => {
        console.error("Gateway Rejection:", failResponse.error);
        alert(`Settlement Rejected: ${failResponse.error.description}`);
        setIsProcessing(false);
      });

      // Opens in a secure popup window
      rzp.open();

    } catch (err: any) {
      console.error("[Checkout Critical Exception]", err.message);
      alert(err.message || "An unexpected network error halted the checkout process. Please try again.");
      setIsProcessing(false);
    }
  };

  const addresses = (user?.addresses && Array.isArray(user.addresses)) ? user.addresses : [];

  return (
    <div className="bg-surface min-h-screen">
      <div className="sticky top-0 z-10 p-4 bg-white/80 backdrop-blur-md flex items-center border-b border-border shadow-sm">
        <button onClick={() => navigate('/cart')} className="p-2 -ml-2 mr-2">
          <ChevronLeftIcon className="h-6 w-6 text-text-main" />
        </button>
        <h1 className="text-xl font-black text-text-main italic tracking-tight uppercase">Checkout</h1>
      </div>

      <div className="p-4 space-y-6 pb-24 max-w-2xl mx-auto">
        <GlassmorphicCard className="p-6">
          <h2 className="text-[10px] font-black uppercase tracking-widest text-text-muted mb-4">Destination Identity</h2>
          {addresses.length > 0 ? (
            <div className="space-y-3">
              {addresses.map(address => (
                <div 
                  key={address.id} 
                  onClick={() => setSelectedAddress(address)} 
                  className={`p-4 rounded-xl border-2 transition-all cursor-pointer ${selectedAddress?.id === address.id ? 'border-accent bg-accent/5' : 'border-border bg-white hover:border-accent/30'}`}
                >
                  <div className="flex justify-between items-start">
                    <p className="font-bold text-text-main">{address.fullName}</p>
                    {selectedAddress?.id === address.id && (
                        <div className="w-4 h-4 rounded-full bg-accent flex items-center justify-center">
                            <svg className="w-2.5 h-2.5 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" /></svg>
                        </div>
                    )}
                  </div>
                  <p className="text-xs text-text-secondary mt-1">{address.street}, {address.city}, {address.state} {address.zip}</p>
                  <p className="text-[10px] font-bold text-accent mt-2 uppercase tracking-widest">{address.phone}</p>
