            .filter(item => {
                // Fix: Property 'vendorId' does not exist on type 'OrderItem'. Use 'vendor_id' instead.
                const itemVid = String(item.vendor_id || '');
                return itemVid === vid;
            })
            .reduce((sum, item) => sum + (Number(item.price) * Number(item.quantity)), 0);
