import React, { useState, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { useCategories } from '../../context/CategoryContext';
import GlassmorphicCard from '../../components/GlassmorphicCard';
import { SUPABASE_URL, SUPABASE_KEY } from '../../constants';

const AdminCategoryFormPage: React.FC = () => {
  const { id } = useParams<{ id?: string }>();
  const navigate = useNavigate();
  const { getCategory, addCategory, updateCategory } = useCategories();

  const isEditing = id !== undefined;
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [selectedFile, setSelectedFile] = useState<File | null>(null);

  const [formData, setFormData] = useState({
    name: '',
    image: '',
  });

  const inputClasses = "w-full mt-1 bg-surface text-text-main border border-gray-600 rounded-lg p-3 transition focus:outline-none focus:border-accent focus:ring-2 focus:ring-accent/50 disabled:opacity-50";

  useEffect(() => {
    if (isEditing) {
      const categoryToEdit = getCategory(parseInt(id));
      if (categoryToEdit) {
        setFormData({ name: categoryToEdit.name, image: categoryToEdit.image || '' });
      }
    }
  }, [id, isEditing, getCategory]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      setSelectedFile(file);

      // For local preview
      const reader = new FileReader();
      reader.onloadend = () => {
        setFormData(prev => ({ ...prev, image: reader.result as string }));
      };
      reader.readAsDataURL(file);
    }
  };

  /**
   * Resilient Image Upload
   * Attempts to upload to Supabase Storage. 
   * If the bucket is missing or upload fails, falls back to Base64 to ensure the category can still be saved.
   */
  const uploadImage = async (file: File): Promise<string> => {
    const fileName = `categories/${Date.now()}-${file.name.replace(/[^a-zA-Z0-9.]/g, '_')}`;
    // Using 'assets' as it's a more standard default bucket name than 'category-images'
    const bucket = 'assets'; 
    const uploadUrl = `${SUPABASE_URL}/storage/v1/object/${bucket}/${fileName}`;

    try {
      const response = await fetch(uploadUrl, {
        method: 'POST',
        headers: {
          'apikey': SUPABASE_KEY,
          'Authorization': `Bearer ${SUPABASE_KEY}`,
          'Content-Type': file.type
        },
        body: file
      });

      if (response.ok) {
        // Return the public URL if successful
        return `${SUPABASE_URL}/storage/v1/object/public/${bucket}/${fileName}`;
      } else {
        const errorData = await response.json().catch(() => ({}));
        console.warn(`Storage upload to '${bucket}' failed (${response.status}: ${errorData.message || 'Unknown error'}). Falling back to Base64.`);
      }
    } catch (err) {
      console.error("Network error during storage upload, falling back to Base64:", err);
    }

    // FALLBACK: Return as Base64 string if Storage is unavailable or fails
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onloadend = () => resolve(reader.result as string);
      reader.onerror = () => reject(new Error("Failed to read file for fallback."));
      reader.readAsDataURL(file);
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!formData.image && !selectedFile) {
      alert("Please upload an image for the category.");
      return;
    }

    setIsSubmitting(true);
    try {
      let finalImageUrl = formData.image;

      // If a new file was selected, attempt upload
      if (selectedFile) {
        finalImageUrl = await uploadImage(selectedFile);
      }

      const submissionData = {
        name: formData.name,
        image: finalImageUrl
      };

      if (isEditing) {
        await updateCategory({ ...submissionData, id: parseInt(id) });
        alert("Category updated successfully!");
      } else {
        await addCategory(submissionData);
        alert("Category created successfully!");
      }
      navigate('/admin/categories');
    } catch (err: any) {
      console.error("Category Submit Error:", err);
      alert(err.message || "An error occurred while saving the category.");
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div>
      <h1 className="text-3xl font-black text-text-main italic tracking-tight uppercase mb-6">
        {isEditing ? 'Edit Category' : 'Add New Category'}
      </h1>
      <GlassmorphicCard className="p-8 max-w-2xl mx-auto">
        <form onSubmit={handleSubmit} className="space-y-6">
            <div>
                <label className="block text-[10px] font-black uppercase text-text-muted mb-1" htmlFor="name">Category Name</label>
                <input 
                    type="text" 
                    id="name"
                    name="name" 
                    value={formData.name} 
                    onChange={handleChange} 
                    required 
                    disabled={isSubmitting}
                    placeholder="e.g., Electronics, Fashion"
                    className={inputClasses} 
                />
            </div>

            <div>
                <label className="block text-[10px] font-black uppercase text-text-muted mb-1">Visual Representation</label>
                <div className="mt-2">
                    <input 
                        type="file" 
                        id="imageUpload" 
                        accept="image/*" 
                        onChange={handleImageChange} 
                        className="hidden" 
                        disabled={isSubmitting}
                    />
                    <label 
                        htmlFor="imageUpload" 
                        className={`cursor-pointer bg-surface text-text-main font-bold py-3 px-6 rounded-xl border border-gray-600 hover:bg-gray-700 transition-all inline-block text-xs uppercase tracking-widest ${isSubmitting ? 'opacity-50 cursor-not-allowed' : ''}`}
                    >
                        {formData.image ? 'Change Image' : 'Select Image File'}
                    </label>
                </div>
                {formData.image && (
                    <div className="mt-6 flex flex-col items-center p-4 bg-background/50 border border-dashed border-gray-600 rounded-2xl">
                        <p className="text-[9px] font-black uppercase text-text-muted mb-3">Live Preview</p>
                        <div className="w-40 h-40 rounded-full overflow-hidden border-4 border-white shadow-2xl">
                            <img 
                              src={formData.image} 
                              alt="Preview" 
                              className="w-full h-full object-cover"
                              onError={(e) => (e.currentTarget.src = 'https://placehold.co/400x400/F8F9FA/A0A0A0?text=Preview+Error')}
                            />
                        </div>
                    </div>
                )}
            </div>

            <div className="flex justify-end gap-4 pt-6 border-t border-border">
                <button 
                    type="button" 
                    onClick={() => navigate('/admin/categories')} 
                    className="px-8 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest text-text-secondary hover:bg-surface transition-all"
                    disabled={isSubmitting}
                >
                    Cancel
                </button>
                <button 
                    type="submit" 
                    disabled={isSubmitting}
                    className="bg-accent text-white px-10 py-3 rounded-xl font-black uppercase tracking-widest text-xs shadow-xl shadow-accent/30 hover:-translate-y-1 active:translate-y-0 transition-all disabled:opacity-50"
                >
                    {isSubmitting ? 'Processing...' : (isEditing ? 'Update Category' : 'Create Category')}
                </button>
            </div>
        </form>
      </GlassmorphicCard>
    </div>
  );
};

export default AdminCategoryFormPage;

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useCart } from '../hooks/useCart';
import { useAuth } from '../context/AuthContext';
import { useOrders } from '../context/OrderContext';
import { useVendors } from '../context/VendorContext';
import GlassmorphicCard from '../components/GlassmorphicCard';
import { ChevronLeftIcon } from '../components/icons/ChevronLeftIcon';
import { Address, OrderItem } from '../types';

/* 🔐 Razorpay Live Key */
const RAZORPAY_LIVE_KEY_ID = 'rzp_live_RxmIholkGEOYaL';

/* 🇮🇳 GST Rate */
const GST_RATE = 0.18;

const CheckoutPage: React.FC = () => {
  const { cartItems, cartTotal, clearCart } = useCart();
  const { user } = useAuth();
  const { addOrder } = useOrders();
  const { vendors, getVendorById, refreshVendors } = useVendors();
  const navigate = useNavigate();

  const [paymentMethod, setPaymentMethod] = useState<'card' | 'cod'>('card');
  const [isProcessing, setIsProcessing] = useState(false);
  const [selectedAddress, setSelectedAddress] = useState<Address | null>(null);

  /* ✅ Precise Calculations */
  const gstAmount = Number((cartTotal * GST_RATE).toFixed(2));
  const finalPayable = Number((cartTotal + gstAmount).toFixed(2));

  useEffect(() => {
    if (user?.addresses?.length) {
      setSelectedAddress(user.addresses[0]);
    }
    // Ensure vendors are loaded for proper "Sold By" resolution
    if (vendors.length === 0) {
      refreshVendors();
    }
  }, [user, vendors.length, refreshVendors]);

  const handlePlaceOrder = async () => {
    if (!user || !selectedAddress) {
      alert('Please select delivery address');
      return;
    }

    if (finalPayable <= 0) {
      alert('Invalid order amount');
      return;
    }

    setIsProcessing(true);

    const orderItems: OrderItem[] = cartItems.map(item => {
      const vendor = vendors.find(v => String(v.id) === String(item.vendor_id));
      return {
        id: item.id,
        name: item.name,
        price: item.price,
        quantity: item.quantity,
        image: item.images[0],
        vendor_id: String(item.vendor_id),
        vendor_name: vendor?.store_name || (item.vendor_id === 'vexokart_direct' ? 'VexoKart Direct' : 'Unknown Seller'),
        color: item.selectedColor,
        size: item.selectedSize,
      };
    });

    try {
      /* 🟢 CASH ON DELIVERY FLOW */
      if (paymentMethod === 'cod') {
        const orderIdString = await addOrder({
          items: orderItems,
          subtotal: cartTotal,
          gst_amount: gstAmount,
          total: finalPayable,
          shippingAddress: selectedAddress,
          payment_method: 'Cash on Delivery',
        });

        clearCart();
        // Redirect to Order Success strictly
        navigate('/order-success', {
          state: { 
            orderId: String(orderIdString), 
            address: selectedAddress 
          },
          replace: true
        });
        return;
      }

      /* 🟢 ONLINE PAYMENT FLOW */
      if (!(window as any).Razorpay) {
        alert('Payment gateway not loaded. Please check your connection.');
        setIsProcessing(false);
        return;
      }

      const razorpayAmountPaise = Math.round(finalPayable * 100);

      const options = {
        key: RAZORPAY_LIVE_KEY_ID,
        amount: razorpayAmountPaise,
        currency: 'INR',
        name: 'VexoKart',
        description: 'Secure Checkout Payment',
        image: 'https://ghzadiplpazekzgjbdxu.supabase.co/storage/v1/object/public/assets/logo.png', // Optional branding
        handler: async (response: any) => {
          // Success Callback from Razorpay
          const orderIdString = await addOrder({
            items: orderItems,
            subtotal: cartTotal,
            gst_amount: gstAmount,
            total: finalPayable,
            shippingAddress: selectedAddress,
            payment_method: 'Online Payment',
            payment_id: response.razorpay_payment_id
          });

          clearCart();
          // Deterministic navigation to Success Page
          navigate('/order-success', {
            state: { 
              orderId: String(orderIdString), 
              address: selectedAddress 
            },
            replace: true
          });
        },
        prefill: {
          name: user.name,
          email: user.email,
          contact: selectedAddress.phone,
        },
        modal: {
          ondismiss: () => setIsProcessing(false),
          escape: false,
          backdropclose: false
        },
        theme: { color: '#FF8A00' },
      };

      const rzp = new (window as any).Razorpay(options);
      rzp.on('payment.failed', (err: any) => {
        alert(err.error?.description || 'Payment failed. Please try again.');
        setIsProcessing(false);
      });

      rzp.open();

    } catch (err) {
      console.error('[Checkout Critical Error]', err);
      alert('Order placement encountered a problem. Please contact support.');
      setIsProcessing(false);
    }
  };

  return (
    <div className="bg-surface min-h-screen">
      {/* Header */}
      <div className="sticky top-0 z-10 p-4 bg-white flex items-center border-b">
        <button onClick={() => navigate('/cart')} className="p-2 -ml-2 mr-2">
          <ChevronLeftIcon className="h-6 w-6" />
        </button>
        <h1 className="text-xl font-black uppercase italic">Checkout</h1>
      </div>

      <div className="p-4 pb-32 max-w-2xl mx-auto space-y-6">
        {/* Address */}
        <GlassmorphicCard className="p-6 bg-white">
          <h2 className="text-[10px] font-black uppercase mb-4 text-text-muted">
            Delivery Destination
          </h2>
          {user?.addresses?.length ? (
             user.addresses.map(address => (
                <div
                  key={address.id}
                  onClick={() => setSelectedAddress(address)}
                  className={`p-4 rounded-xl border-2 cursor-pointer mb-3 transition-all ${
                    selectedAddress?.id === address.id
                      ? 'border-accent bg-accent/5'
                      : 'border-border hover:border-accent/30'
                  }`}
                >
                  <div className="flex justify-between items-start">
                      <div>
                        <p className="font-black text-xs uppercase">{address.fullName}</p>
                        <p className="text-[10px] mt-1 text-text-secondary leading-relaxed">
                            {address.street}<br/>
                            {address.city}, {address.state} — {address.zip}
                        </p>
                      </div>
                      {selectedAddress?.id === address.id && (
                          <div className="w-5 h-5 bg-accent rounded-full flex items-center justify-center">
                              <svg className="w-3 h-3 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={4} d="M5 13l4 4L19 7" /></svg>
                          </div>
                      )}
                  </div>
                  <p className="text-[10px] font-black text-accent mt-2">
                    {address.phone}
                  </p>
                </div>
              ))
          ) : (
            <button onClick={() => navigate('/addresses/new')} className="w-full py-4 border-2 border-dashed border-border rounded-xl text-xs font-bold text-text-muted uppercase">Add Shipping Address</button>
          )}
        </GlassmorphicCard>

        {/* Payment */}
        <GlassmorphicCard className="p-6 bg-white">
          <h2 className="text-[10px] font-black uppercase mb-4 text-text-muted">
            Select Payment Method
          </h2>

          <div className="space-y-3">
            <div
              onClick={() => setPaymentMethod('card')}
              className={`p-4 rounded-xl border-2 cursor-pointer flex items-center justify-between transition-all ${
                paymentMethod === 'card'
                  ? 'border-accent bg-accent/5'
                  : 'border-border hover:border-accent/20'
              }`}
            >
              <span className="font-bold text-sm">Online Payment (UPI / Cards)</span>
              <svg className="w-5 h-5 text-accent" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 10h18M7 15h1m4 0h1m-7 4h12a3 3 0 003-3V8a3 3 0 00-3-3H6a3 3 0 00-3 3v8a3 3 0 003 3z" /></svg>
            </div>

            <div
              onClick={() => setPaymentMethod('cod')}
              className={`p-4 rounded-xl border-2 cursor-pointer flex items-center justify-between transition-all ${
                paymentMethod === 'cod'
                  ? 'border-accent bg-accent/5'
                  : 'border-border hover:border-accent/20'
              }`}
            >
              <span className="font-bold text-sm">Cash on Delivery</span>
              <svg className="w-5 h-5 text-accent" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 9V7a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2m2 4h10a2 2 0 002-2v-6a2 2 0 00-2-2H9a2 2 0 00-2 2v6a2 2 0 002 2zm7-5a2 2 0 11-4 0 2 2 0 014 0z" /></svg>
            </div>
          </div>
        </GlassmorphicCard>

        {/* Summary */}
        <GlassmorphicCard className="p-6 bg-white">
          <h2 className="text-[10px] font-black uppercase mb-4 text-text-muted border-b pb-2">
            Pricing Summary
          </h2>
          <div className="space-y-3 text-sm">
            <div className="flex justify-between text-text-secondary">
              <span>Bag Subtotal</span>
              <span className="font-bold text-text-main">₹{cartTotal.toLocaleString()}</span>
            </div>
            <div className="flex justify-between text-text-secondary">
              <span>GST (18%)</span>
              <span className="font-bold text-text-main">₹{gstAmount.toLocaleString()}</span>
            </div>
            <div className="flex justify-between text-text-secondary">
              <span>Shipping Fee</span>
              <span className="font-bold text-green-600 uppercase text-[10px]">Free</span>
            </div>
            <div className="pt-3 border-t border-dashed flex justify-between items-end">
              <span className="text-text-main font-black uppercase tracking-widest text-xs">Total Payable</span>
              <span className="text-2xl font-black text-accent italic tracking-tighter">₹{finalPayable.toLocaleString()}</span>
            </div>
          </div>
        </GlassmorphicCard>
      </div>

      {/* Pay Button */}
      <div className="fixed bottom-0 left-0 right-0 p-4 bg-white/90 backdrop-blur-md border-t border-border z-10 shadow-[0_-4px_20px_rgba(0,0,0,0.05)]">
        <button
          onClick={handlePlaceOrder}
          disabled={isProcessing || !selectedAddress}
          className="w-full bg-accent text-white py-4 rounded-2xl font-black uppercase tracking-widest text-[11px] shadow-2xl shadow-accent/30 active:scale-[0.98] transition-all disabled:opacity-50"
        >
          {isProcessing
            ? 'Establishing Secure Session...'
            : paymentMethod === 'cod'
            ? `Confirm Order — ₹${finalPayable}`
            : `Pay Secured ₹${finalPayable} (Incl. GST)`}
        </button>
      </div>
    </div>
  );
};

export default CheckoutPage;

import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { useOrders } from '../context/OrderContext';
import GlassmorphicCard from '../components/GlassmorphicCard';
import { ChevronLeftIcon } from '../components/icons/ChevronLeftIcon';
import InvoiceModal from '../components/InvoiceModal';
import { Order, OrderStatus } from '../types';

const getStatusColor = (status: OrderStatus) => {
    switch(status) {
        case 'Placed': return 'text-gray-400 bg-gray-50 border-gray-100';
        case 'Confirmed': return 'text-cyan-600 bg-cyan-50 border-cyan-100';
        case 'Packed': return 'text-indigo-600 bg-indigo-50 border-indigo-100';
        case 'Shipped': return 'text-blue-600 bg-blue-50 border-blue-100';
        case 'Out for Delivery': return 'text-orange-600 bg-orange-50 border-orange-100';
        case 'Delivered': return 'text-green-600 bg-green-50 border-green-100';
        case 'Cancelled': return 'text-red-600 bg-red-50 border-red-100';
        default: return 'text-gray-400 bg-gray-50 border-gray-100';
    }
}

const MyOrdersPage: React.FC = () => {
  const { orders } = useOrders();
  const navigate = useNavigate();
  const [selectedInvoice, setSelectedInvoice] = useState<Order | null>(null);

  return (
    <div className="bg-surface min-h-screen pb-20">
      {selectedInvoice && <InvoiceModal order={selectedInvoice} onClose={() => setSelectedInvoice(null)} />}

      <div className="sticky top-0 z-20 p-4 bg-white/80 backdrop-blur-md flex items-center border-b border-border shadow-sm">
        <button onClick={() => navigate('/profile')} className="p-2 -ml-2 mr-2 bg-surface rounded-full border border-border">
            <ChevronLeftIcon className="h-5 w-5 text-text-main" />
        </button>
        <h1 className="text-xl font-black text-text-main italic tracking-tight uppercase">My Orders</h1>
      </div>

      <div className="p-4 max-w-2xl mx-auto space-y-4">
        {orders.length === 0 ? (
          <div className="text-center py-32 bg-white rounded-3xl border border-dashed border-border p-10">
            <div className="w-20 h-20 bg-surface rounded-full flex items-center justify-center mx-auto mb-6">
                 <svg className="w-10 h-10 text-text-muted/40" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M16 11V7a4 4 0 00-8 0v4M5 9h14l1 12H4L5 9z" /></svg>
            </div>
            <p className="text-text-main font-bold">No orders found</p>
            <p className="text-text-muted text-xs mt-1">Start shopping to see your history here.</p>
            <button onClick={() => navigate('/products')} className="mt-8 bg-accent text-white font-black uppercase text-[10px] tracking-widest py-4 px-8 rounded-2xl shadow-xl shadow-accent/20">
              Discover Products
            </button>
          </div>
        ) : (
          orders.map(order => {
            const isCOD = order.payment_mode === 'Cash on Delivery';
            const paymentStatusText = isCOD ? 'Payment Pending (COD)' : 'Paid';
            const hasInvoice = order.invoice_generated !== false && order.status !== 'Cancelled';

            return (
                <GlassmorphicCard key={order.id} className="p-0 overflow-hidden border-none shadow-premium bg-white">
                  <div className="p-5 flex justify-between items-start border-b border-gray-50">
                    <div>
                      <p className="text-[10px] font-black uppercase text-text-muted tracking-widest">Order Reference</p>
                      <p className="font-mono font-black text-text-main">#{order.id}</p>
                      <p className="text-[9px] text-text-muted font-bold mt-0.5 uppercase tracking-tighter">{new Date(order.created_at).toLocaleDateString([], { day: 'numeric', month: 'short', year: 'numeric' })}</p>
                    </div>
                    <div className="text-right">
                        <span className={`px-2 py-1 rounded-md text-[9px] font-black uppercase tracking-widest border ${getStatusColor(order.status)}`}>
                            {order.status}
                        </span>
                    </div>
                  </div>

                  <Link to={`/order/${order.id}`} className="p-5 block hover:bg-surface transition-colors">
                      <div className="space-y-4">
                          {order.items.slice(0, 1).map(item => (
                              <div key={item.id} className="flex items-center gap-4">
                                  <img src={item.image} alt={item.name} className="w-14 h-14 rounded-xl object-cover border border-border bg-surface" />
                                  <div className="flex-grow min-w-0">
                                      <p className="text-xs font-black text-text-main truncate uppercase italic">{item.name}</p>
                                      <p className="text-[9px] font-black text-accent uppercase tracking-tighter mt-0.5">Sold by: {item.vendor_name || 'VexoKart Direct'}</p>
                                      <div className="flex items-center gap-2 mt-1">
                                          <p className="text-[10px] font-bold text-text-secondary uppercase">Qty: {item.quantity}</p>
                                          {order.items.length > 1 && <p className="text-[9px] text-text-muted font-black uppercase">+ {order.items.length - 1} More</p>}
                                      </div>
                                  </div>
                                  <div className="text-right">
                                       <p className="text-sm font-black text-accent italic">₹{order.total.toLocaleString()}</p>
                                  </div>
                              </div>
                          ))}
                      </div>
                  </Link>

                  <div className="p-5 bg-gray-50/50 flex flex-wrap gap-4 items-center justify-between">
                      <div className="flex gap-4">
                          <div className="space-y-1">
                             <p className="text-[8px] font-black uppercase text-text-muted tracking-widest">Payment Mode</p>
                             <p className="text-[10px] font-bold text-text-main uppercase">{order.payment_mode}</p>
                          </div>
                          <div className="space-y-1">
                             <p className="text-[8px] font-black uppercase text-text-muted tracking-widest">Status</p>
                             <p className={`text-[10px] font-black uppercase ${isCOD ? 'text-orange-500' : 'text-green-600'}`}>{paymentStatusText}</p>
                          </div>
                      </div>

                      {hasInvoice && (
                        <button 
                          onClick={(e) => { e.preventDefault(); e.stopPropagation(); setSelectedInvoice(order); }}
                          className="bg-white border border-border text-text-main px-4 py-2 rounded-xl text-[9px] font-black uppercase tracking-widest shadow-sm hover:border-accent transition-all flex items-center gap-2"
                        >
