import React, {
  createContext,
  useState,
  useEffect,
  ReactNode,
  useContext,
} from "react";
import { Order, OrderStatus, Address, PaymentStatus } from "../types.ts";
import { useAuth } from "./AuthContext.tsx";
import { useNotifications } from "./NotificationContext.tsx";
import { BASE_API_URL, API_HEADERS } from "../constants.ts";

interface OrderContextType {
  orders: any[]; // Using any temporarily for joined structure
  isLoading: boolean;
  addOrder: (orderData: any) => Promise<string>;
  updateOrderStatus: (
    orderId: string,
    status: OrderStatus,
    details?: any
  ) => Promise<void>;
  generateShippingLabel: (orderId: string) => Promise<void>;
  refreshOrders: () => Promise<void>;
  getOrderById: (orderId: string) => any | undefined;
  getOrderByToken: (token: string) => any | undefined;
  updateOrderByToken: (
    token: string,
    status: OrderStatus,
    note?: string
  ) => Promise<{ success: boolean; message: string }>;
}

const OrderContext = createContext<OrderContextType | undefined>(undefined);

export const OrderProvider: React.FC<{ children: ReactNode }> = ({
  children,
}) => {
  const { user } = useAuth();
  const { sendInvoiceEmail } = useNotifications();
  const [orders, setOrders] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  /* =========================
     FETCH ORDERS (WITH JOIN)
  ========================== */
  const refreshOrders = async () => {
    if (!user) return;

    try {
      setIsLoading(true);

      // Join with vendors table to get store_name for invoices and orders
      let url = `${BASE_API_URL}/orders?select=*,vendor:vendors(store_name)&order=created_at.desc`;

      if (user.role === "user") {
        url += `&user_id=eq.${user.id}`;
      } else if (user.role === "vendor") {
        // Vendors only see orders where their ID is recorded
        // Note: fetchCurrentVendor should have been called previously to get the vendor profile
      }

      const res = await fetch(url, {
        headers: { ...API_HEADERS, "Cache-Control": "no-cache" },
      });

      if (!res.ok) throw new Error("Failed to fetch orders");

      const data = await res.json();

      if (Array.isArray(data)) {
        setOrders(
          data.map((o: any) => ({
            ...o,
            id: o.id.toString(),
            total: Number(o.total_amount || 0),
            statusHistory: o.status_history || [],
            qrToken: o.qr_token,
            date: o.created_at,
            invoice_generated: o.invoice_generated ?? true,
            // Fallback for store_name from joined vendor object
            seller_name: o.vendor?.store_name || "VexoKart Direct",
            shippingAddress: o.shippingaddress || o.address || null,
          }))
        );
      }
    } catch (e) {
      console.error("[OrderContext] Order fetch failed", e);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    if (user) refreshOrders();
    else setOrders([]);
  }, [user]);

  /* =========================
     CREATE ORDER
  ========================== */
  const addOrder = async (orderData: any): Promise<string> => {
    if (!user) throw new Error("User not logged in");

    const timestamp = new Date().toISOString();
    const qrToken = Math.random().toString(36).substring(2, 15);

    const addressSnapshot: Address = {
      id: orderData.shippingAddress.id || Date.now().toString(),
      fullName: orderData.shippingAddress.fullName,
      street: orderData.shippingAddress.street,
      city: orderData.shippingAddress.city,
      state: orderData.shippingAddress.state,
      zip: orderData.shippingAddress.zip,
      phone: orderData.shippingAddress.phone,
    };

    // Determine vendor_id for the order record (numeric/bigint)
    const rawVendorId = orderData.items[0]?.vendor_id;
    const numericVendorId = isNaN(Number(rawVendorId)) ? null : Number(rawVendorId);

    const payload = {
      user_id: Number(user.id),
      vendor_id: numericVendorId, // Top-level column for JOIN and filtering
      items: orderData.items,
      total_amount: Number(orderData.total),
      payment_mode: orderData.payment_method,
      payment_status: orderData.payment_method === "Cash on Delivery" ? "cod_pending" : "paid",
      address: addressSnapshot,
      shippingaddress: addressSnapshot,
      status: "Placed" as OrderStatus,
      qr_token: qrToken,
      invoice_generated: true,
      status_history: [{
          status: "Placed" as OrderStatus,
          timestamp,
          actor: "User" as const,
          note: "Order placed by customer",
      }],
      created_at: timestamp,
    };

    try {
      const res = await fetch(`${BASE_API_URL}/orders`, {
        method: "POST",
        headers: { ...API_HEADERS, Prefer: "return=representation" },
        body: JSON.stringify(payload),
      });

      if (!res.ok) throw new Error("Order creation failed");

      const result = await res.json();
      const createdOrder = result[0];

      await refreshOrders();
      return createdOrder.id.toString();
    } catch (err) {
      console.error("Order error", err);
      throw err;
    }
  };

  const updateOrderStatus = async (orderId: string, status: OrderStatus, details: any = {}) => {
    const order = orders.find((o) => o.id === orderId);
    const history = order?.statusHistory || [];
    const newHistory = [...history, {
        status,
        timestamp: new Date().toISOString(),
        actor: user?.role === "vendor" ? "Vendor" : user?.role === "admin" ? "Admin" : "System",
        note: details.note || `Order marked as ${status}`,
    }];

    try {
      await fetch(`${BASE_API_URL}/orders?id=eq.${orderId}`, {
        method: "PATCH",
        headers: { ...API_HEADERS },
        body: JSON.stringify({ status, status_history: newHistory, ...details }),
      });
      await refreshOrders();
    } catch (err) { console.error(err); }
  };

  const generateShippingLabel = async (orderId: string) => {
    const labelUrl = `https://ghzadiplpazekzgjbdxu.supabase.co/storage/v1/object/public/labels/${orderId}.pdf`;
    await updateOrderStatus(orderId, "Packed", { label_url: labelUrl });
  };

  const getOrderById = (id: string) => orders.find((o) => o.id === id);
  const getOrderByToken = (token: string) => orders.find((o) => o.qrToken === token || o.qr_token === token);

  const updateOrderByToken = async (token: string, status: OrderStatus, note?: string) => {
    const order = getOrderByToken(token);
    if (!order) return { success: false, message: "Invalid token" };
    await updateOrderStatus(order.id, status, { note });
    return { success: true, message: "Status updated" };
  };

  return (
    <OrderContext.Provider
      value={{
        orders,
        isLoading,
        addOrder,
        updateOrderStatus,
        generateShippingLabel,
        refreshOrders,
        getOrderById,
        getOrderByToken,
        updateOrderByToken,
      }}
    >
      {children}
    </OrderContext.Provider>
  );
};

export const useOrders = () => {
  const context = useContext(OrderContext);
  if (!context) throw new Error("OrderContext missing");
  return context;
};

import React, { useState, useEffect, useMemo } from 'react';
import { Order, OrderStatus, OrderItem } from '../../types';
import GlassmorphicCard from '../../components/GlassmorphicCard';
import { useAuth } from '../../context/AuthContext';
import { useVendors } from '../../context/VendorContext';
import { useOrders } from '../../context/OrderContext';
import ShippingDetailsModal from '../../components/admin/ShippingDetailsModal';
import ShippingLabelModal from '../../components/vendor/ShippingLabelModal';

interface VendorAugmentedOrder extends Order {
    vendorItems: OrderItem[];
    vendorSubtotal: number;
}

const VendorOrdersPage: React.FC = () => {
    const { user } = useAuth();
    const { currentVendor, fetchCurrentVendor } = useVendors();
    const { orders, isLoading, updateOrderStatus, generateShippingLabel, refreshOrders } = useOrders();

    const [statusFilter, setStatusFilter] = useState<string>('all');
    const [selectedOrder, setSelectedOrder] = useState<Order | null>(null);
    const [isShippingModalOpen, setShippingModalOpen] = useState(false);
    const [labelOrder, setLabelOrder] = useState<Order | null>(null);
    const [isGeneratingLabel, setIsGeneratingLabel] = useState<string | null>(null);

    useEffect(() => {
        refreshOrders();
        if (user?.id && !currentVendor) {
            fetchCurrentVendor(user.id.toString());
        }
    }, [user, currentVendor, refreshOrders, fetchCurrentVendor]);

    const vendorOrders = useMemo(() => {
        if (!currentVendor) return [];

        return orders.filter(order => {
            // Strict filtering by top-level numeric vendor_id
            const matchesVendorId = Number(order.vendor_id) === Number(currentVendor.id);

            // Legacy/Multi-vendor fallback: check items if vendor_id column is missing or null
            const hasVendorItems = Array.isArray(order.items) && order.items.some(item => 
                Number(item.vendor_id) === Number(currentVendor.id)
            );

            return matchesVendorId || hasVendorItems;
        }).map(order => {
            const matchedItems = order.items.filter(item => 
                Number(item.vendor_id) === Number(currentVendor.id)
            );
            const vendorSubtotal = matchedItems.reduce((sum, item) => sum + (item.price * item.quantity), 0);

            return {
                ...order,
                vendorItems: matchedItems,
                vendorSubtotal: vendorSubtotal
            } as VendorAugmentedOrder;
        }).filter((o): o is VendorAugmentedOrder => {
            if (statusFilter === 'all') return true;
            if (statusFilter === 'pending') return ['Placed', 'Confirmed'].includes(o.status);
            return o.status === statusFilter;
        });
    }, [orders, currentVendor, statusFilter]);

    const handlePackAndLabel = async (orderId: string) => {
        setIsGeneratingLabel(orderId);
        try {
            await generateShippingLabel(orderId);
            alert('Label generated successfully.');
        } catch (err: any) {
            alert(err.message || 'Failed to generate label.');
        } finally {
            setIsGeneratingLabel(null);
        }
    };

    const handleStatusChange = (order: Order, status: OrderStatus) => {
        if (status === 'Shipped') {
            setSelectedOrder(order);
            setShippingModalOpen(true);
        } else {
            updateOrderStatus(order.id, status);
        }
    };

    const handleShippingSubmit = (courierName: string, trackingId: string) => {
        if (selectedOrder) {
            updateOrderStatus(selectedOrder.id, 'Shipped', { courier_name: courierName, tracking_id: trackingId });
        }
        setShippingModalOpen(false);
        setSelectedOrder(null);
    };

    if (isLoading && vendorOrders.length === 0) {
        return (
            <div className="flex flex-col items-center justify-center p-20">
                <div className="w-10 h-10 border-4 border-accent border-t-transparent rounded-full animate-spin"></div>
                <p className="mt-4 text-text-muted font-black uppercase tracking-widest text-[10px]">Loading orders...</p>
            </div>
        );
    }

    return (
        <div className="space-y-6">
            {isShippingModalOpen && (
                <ShippingDetailsModal
                    onClose={() => setShippingModalOpen(false)}
                    onSubmit={handleShippingSubmit}
                />
            )}

            {labelOrder && currentVendor && (
                <ShippingLabelModal
                  order={labelOrder}
                  vendor={currentVendor}
                  onClose={() => setLabelOrder(null)}
                  onGenerated={() => {}}
                />
            )}

            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                <div>
                  <h1 className="text-3xl font-black text-text-main italic tracking-tight uppercase">Vendor Orders</h1>
                  <p className="text-text-muted mt-1 text-sm">Fulfill orders and generate labels.</p>
                </div>

                <div className="flex bg-surface p-1 rounded-xl border border-border">
                    {['all', 'pending', 'Packed', 'Shipped', 'Delivered'].map(f => (
                        <button
                            key={f}
                            onClick={() => setStatusFilter(f)}
                            className={`px-4 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${statusFilter === f ? 'bg-accent text-white shadow-lg' : 'text-text-muted hover:text-text-secondary'}`}
                        >
                            {f}
                        </button>
                    ))}
                </div>
            </div>

            <GlassmorphicCard>
                <div className="overflow-x-auto">
                    <table className="w-full text-left text-sm">
                        <thead>
                            <tr className="border-b border-white/5 text-text-muted text-[10px] uppercase font-black tracking-widest">
                                <th className="p-6">Order ID</th>
                                <th className="p-6">Customer</th>
                                <th className="p-6">Revenue</th>
                                <th className="p-6">Status</th>
                                <th className="p-6 text-right">Actions</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-white/5">
                            {vendorOrders.map(order => (
                                <tr key={order.id} className="hover:bg-white/[0.02] transition-colors">
                                    <td className="p-6">
                                        <p className="text-text-main font-mono font-bold">#{order.id}</p>
                                        <p className="text-[10px] text-text-muted font-bold mt-1 uppercase">{new Date(order.created_at).toLocaleDateString()}</p>
                                    </td>
                                    <td className="p-6">
                                        <p className="text-text-main font-bold">{order.shippingAddress?.fullName || 'Customer'}</p>
                                        <p className="text-[10px] text-text-muted mt-1 uppercase">{order.shippingAddress?.city}, {order.shippingAddress?.state}</p>
                                    </td>
                                    <td className="p-6">
                                        <span className="text-accent font-black text-sm">₹{order.vendorSubtotal.toLocaleString()}</span>
                                    </td>
                                    <td className="p-6">
                                        <span className={`text-[10px] font-black uppercase ${
                                            order.status === 'Delivered' ? 'text-green-500' : 
                                            order.status === 'Cancelled' ? 'text-red-500' : 
                                            'text-blue-400'
                                        }`}>
                                            {order.status}
                                        </span>
                                    </td>
                                    <td className="p-6 text-right space-x-2 whitespace-nowrap">
                                        {order.status === 'Placed' && (
                                            <button onClick={() => handleStatusChange(order, 'Confirmed')} className="bg-accent text-white px-3 py-1.5 rounded-lg text-[10px] font-black uppercase shadow-lg shadow-accent/20">Confirm</button>
                                        )}
                                        {order.status === 'Confirmed' && !order.label_url && (
                                            <button 
                                                onClick={() => handlePackAndLabel(order.id)} 
                                                disabled={isGeneratingLabel === order.id}
                                                className="bg-indigo-50 text-white px-3 py-1.5 rounded-lg text-[10px] font-black uppercase shadow-lg shadow-indigo-500/20 disabled:opacity-50"
                                            >
                                                {isGeneratingLabel === order.id ? 'Generating...' : 'Pack & Label'}
                                            </button>
                                        )}
                                        {order.label_url && (
                                            <button 
                                                onClick={() => setLabelOrder(order)} 
                                                className="bg-surface border border-border text-text-main px-3 py-1.5 rounded-lg text-[10px] font-black uppercase hover:bg-white transition-all shadow-sm flex items-center gap-2"
                                            >
                                                View Label
                                            </button>
                                        )}
                                        {order.status === 'Packed' && (
                                            <button onClick={() => handleStatusChange(order, 'Shipped')} className="bg-blue-500 text-white px-3 py-1.5 rounded-lg text-[10px] font-black uppercase shadow-lg shadow-blue-500/20">Mark Shipped</button>
                                        )}
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                    {vendorOrders.length === 0 && !isLoading && (
                        <div className="p-20 text-center text-text-muted italic">
                            No orders found for your storefront.
                        </div>
                    )}
                </div>
            </GlassmorphicCard>
        </div>
    );
};

