import React, { createContext, useState, useContext, ReactNode, useEffect } from 'react';
import { GoogleGenAI, GenerateContentResponse } from '@google/genai';
import { NotificationLog, NotificationSettings, Order, User } from '../types';
import { BASE_API_URL, API_HEADERS, EDGE_FUNCTION_URL } from '../constants';

interface NotificationContextType {
  settings: NotificationSettings;
  logs: NotificationLog[];
  inbox: NotificationLog[];
  unreadCount: number;
  updateSettings: (settings: Partial<NotificationSettings>) => void;
  notifyOrderUpdate: (order: Order, user: User) => Promise<void>;
  notifyLogin: (user: User) => Promise<void>;
  sendInvoiceEmail: (order: Order, user: User) => Promise<boolean>;
  markAsRead: (logId: string) => Promise<void>;
  markAllAsRead: () => Promise<void>;
  clearLogs: () => void;
  fetchInbox: (email: string) => Promise<void>;
}

const NotificationContext = createContext<NotificationContextType | undefined>(undefined);

const DEFAULT_SETTINGS: NotificationSettings = {
  emailEnabled: true,
  smsEnabled: true,
  smtpHost: 'api.sendgrid.com',
  smtpUser: '',
  smtpPass: '',
  /* ✅ FIXED VERIFIED SENDER EMAIL & NAME */
  emailFrom: 'BICT Computer Education – VexoKart <bictcomputereducation1@gmail.com>',
  smsApiKey: process.env.FAST2SMS_API_KEY || 'DEMO_KEY_FSTSMS_LIVE',
  smsSenderId: 'VXKART',
  smsTemplateId: '',
  testMode: false,
};

export const NotificationProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [settings, setSettings] = useState<NotificationSettings>(() => {
    const local = localStorage.getItem('vexokart-notification-settings');
    const saved = local ? JSON.parse(local) : DEFAULT_SETTINGS;
    // Always sync the latest API key from environment if available
    return { ...saved, smsApiKey: process.env.FAST2SMS_API_KEY || saved.smsApiKey };
  });

  const [logs, setLogs] = useState<NotificationLog[]>([]);
  const [inbox, setInbox] = useState<NotificationLog[]>([]);

  const unreadCount = inbox.filter(m => !m.is_read).length;

  useEffect(() => {
    localStorage.setItem('vexokart-notification-settings', JSON.stringify(settings));
  }, [settings]);

  const fetchInbox = async (email: string) => {
    try {
      const res = await fetch(`${BASE_API_URL}/notifications_log?userId=eq.${encodeURIComponent(email)}&order=createdAt.desc`, {
        headers: API_HEADERS
      });
      if (!res.ok) return;
      const data = await res.json();
      if (Array.isArray(data)) {
        setInbox(data);
      }
    } catch (e) {
      console.warn("[Inbox Sync] Network issue. Skipping inbox refresh...");
    }
  };

  const updateSettings = (newSettings: Partial<NotificationSettings>) => {
    setSettings(prev => ({ ...prev, ...newSettings }));
  };

  const markAsRead = async (logId: string) => {
    try {
      await fetch(`${BASE_API_URL}/notifications_log?id=eq.${logId}`, {
        method: 'PATCH',
        headers: { ...API_HEADERS, 'Prefer': 'return=minimal' },
        body: JSON.stringify({ is_read: true })
      });
      setInbox(prev => prev.map(m => m.id === logId ? { ...m, is_read: true } : m));
    } catch (e) {
      console.error("Failed to mark as read", e);
    }
  };

  const markAllAsRead = async () => {
    const unreadIds = inbox.filter(m => !m.is_read).map(m => m.id);
    if (unreadIds.length === 0) return;

    try {
      for (const id of unreadIds) {
        await fetch(`${BASE_API_URL}/notifications_log?id=eq.${id}`, {
          method: 'PATCH',
          headers: { ...API_HEADERS, 'Prefer': 'return=minimal' },
          body: JSON.stringify({ is_read: true })
        });
      }
      setInbox(prev => prev.map(m => ({ ...m, is_read: true })));
    } catch (e) {
      console.error("Failed to mark all as read", e);
    }
  };

  const saveLogToDB = async (log: Omit<NotificationLog, 'id' | 'createdAt' | 'is_read'>) => {
    const timestamp = new Date().toISOString();
    const newLog = {
      ...log,
      createdAt: timestamp,
      is_read: false
    };

    try {
      const res = await fetch(`${BASE_API_URL}/notifications_log`, {
        method: 'POST',
        headers: { ...API_HEADERS, 'Prefer': 'return=representation' },
        body: JSON.stringify(newLog)
      });
      const data = await res.json().catch(() => []);
      if (Array.isArray(data) && data.length > 0) {
        setInbox(prev => [data[0], ...prev]);
        setLogs(prev => [data[0], ...prev].slice(0, 100));
      } else {
        setLogs(prev => [{ ...newLog, id: 'temp-' + Date.now() } as any, ...prev].slice(0, 100));
      }
    } catch (e) {
      console.warn("[Notifications Log] DB sync skipped. Storing in local session.");
      setLogs(prev => [{ ...newLog, id: 'temp-' + Date.now() } as any, ...prev].slice(0, 100));
    }
  };

  const sendQuickSMS = async (number: string, message: string) => {
    if (!settings.smsEnabled || !number) return;

    try {
        const apiKey = process.env.FAST2SMS_API_KEY || settings.smsApiKey;
        const response = await fetch('https://www.fast2sms.com/dev/bulkV2', {
          method: 'POST',
          headers: {
            'authorization': apiKey,
            'Content-Type': 'application/json'
          },
          body: JSON.stringify({
            route: 'q',
            message: message,
            numbers: number,
          })
        });
        const result = await response.json();
        return result;
    } catch (err) {
        console.error("Fast2SMS API Error:", err);
        throw err;
    }
  };

  const notifyLogin = async (user: User) => {
    const message = `VexoKart: Login successful for ${user.email}. If this wasn't you, secure your account immediately. - Team VexoKart`;

    try {
      if (settings.testMode) {
        await saveLogToDB({ userId: user.email, orderId: 'N/A', title: 'Login Alert', message, channel: 'sms', status: 'sent', response: 'Sandbox Simulation Success', type: 'Login' });
        return;
      }

      await sendQuickSMS(user.phone, message);
      await saveLogToDB({ userId: user.email, orderId: 'N/A', title: 'Login Alert', message, channel: 'sms', status: 'sent', response: 'Live SMS Delivered', type: 'Login' });
    } catch (e: any) {
      await saveLogToDB({ userId: user.email, orderId: 'N/A', title: 'Login Alert', message, channel: 'sms', status: 'failed', response: e.message, type: 'Login' });
    }
  };

  const sendInvoiceEmail = async (order: Order, userData: User): Promise<boolean> => {
    try {
        const baseSubtotal = order.items.reduce((sum, item) => sum + (item.price * item.quantity), 0);
        const gstAmount = Number((baseSubtotal * 0.18).toFixed(2));
        const finalTotal = Number((baseSubtotal + gstAmount).toFixed(2));

        const isCOD = order.payment_mode === 'Cash on Delivery';
        const paymentStatusText = isCOD ? 'Payment Pending (COD)' : 'Paid';

        const payload = {
            orderId: order.id,
            user: { name: userData.name, email: userData.email, phone: userData.phone },
            orderDate: order.created_at,
            items: order.items.map(item => ({ ...item, lineTotal: item.price * item.quantity, vendor_name: item.vendor_name || 'VexoKart Direct' })),
            subtotal: baseSubtotal,
            gst: gstAmount,
            total: finalTotal,
            paymentMode: order.payment_mode,
            paymentStatus: paymentStatusText,
            shippingAddress: order.shippingAddress || order.shipping_address,
            seller: { name: "VexoKart Authorized Marketplace", email: "bictcomputereducation1@gmail.com", footer: "This is a system generated invoice." },
            emailConfig: { subject: `Your VexoKart Invoice – Order #${order.id}`, fromEmail: "bictcomputereducation1@gmail.com", fromName: "BICT Computer Education – VexoKart", message: `Your order #${order.id} has been confirmed. PDF Invoice attached.` }
        };

        if (settings.testMode) {
            await new Promise(r => setTimeout(r, 1000));
            await saveLogToDB({ userId: userData.email, orderId: order.id, title: `Invoice Generated: #${order.id}`, message: `Simulation: PDF dispatched via bictcomputereducation1@gmail.com`, channel: 'email', status: 'sent', response: 'Simulation Success', type: 'Invoice' });
            return true;
        }

        const response = await fetch(`${EDGE_FUNCTION_URL}/send-invoice`, {
            method: 'POST',
            headers: { ...API_HEADERS, 'Authorization': `Bearer ${process.env.API_KEY || ''}` },
            body: JSON.stringify(payload)
        });

        if (!response.ok) throw new Error(`Gateway Error: ${response.status}`);
        await saveLogToDB({ userId: userData.email, orderId: order.id, title: `Invoice Dispatched – #${order.id}`, message: `PDF Invoice sent from bictcomputereducation1@gmail.com.`, channel: 'email', status: 'sent', response: 'Live Edge Function Success', type: 'Invoice' });
        return true;
    } catch (err: any) {
        await saveLogToDB({ userId: userData.email, orderId: order.id, title: `Invoice Failed – #${order.id}`, message: `Invoice delivery failed: ${err.message}`, channel: 'in-app', status: 'failed', response: err.message, type: 'Invoice' });
        return false;
    }
  };

  const notifyOrderUpdate = async (order: Order, user: User) => {
    const smsConsent = user.sms_enabled ?? true;
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    let aiContent = { email: '', sms: '', title: '' };

    try {
      const response: GenerateContentResponse = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Generate transactional notifications. Name: ${user.name}, ID: #${order.id}, Status: ${order.status}, Total: ₹${order.total_amount || order.total}. Output JSON with: "title", "emailBody", "smsBody" (max 140 chars, start with "VexoKart: " and end with "- Team VexoKart")`,
        config: { responseMimeType: 'application/json' }
      });
      const parsed = JSON.parse(response.text || '{}');
      aiContent.title = parsed.title || `Order Update: #${order.id}`;
      aiContent.email = parsed.emailBody;
      aiContent.sms = parsed.smsBody || `VexoKart: Order #${order.id} is ${order.status}. Total: ₹${order.total_amount || order.total}. - Team VexoKart`;
    } catch (err) {
      aiContent.title = `Order ${order.status}`;
      aiContent.email = `Order #${order.id} is now ${order.status}.`;
      aiContent.sms = `VexoKart: Hi ${user.name}, your order #${order.id} is ${order.status}. - Team VexoKart`;
    }

    const sendWithRetry = async (channel: 'email' | 'sms', sendFn: () => Promise<any>) => {
        try {
          if (settings.testMode) {
            await saveLogToDB({ userId: user.email, orderId: order.id, title: aiContent.title, message: channel === 'sms' ? aiContent.sms : aiContent.email, channel, status: 'sent', response: 'Simulation Success', type: order.status });
            return;
          }
          if (channel === 'sms' && (!smsConsent || !user.phone)) return;
          await sendFn();
          await saveLogToDB({ userId: user.email, orderId: order.id, title: aiContent.title, message: channel === 'sms' ? aiContent.sms : aiContent.email, channel, status: 'sent', response: 'Live Accepted', type: order.status });
        } catch (error: any) {
            await saveLogToDB({ userId: user.email, orderId: order.id, title: aiContent.title, message: channel === 'sms' ? aiContent.sms : aiContent.email, channel, status: 'failed', response: error.message, type: order.status });
        }
    };

    if (settings.emailEnabled) {
      await sendWithRetry('email', async () => {
        const response = await fetch('https://api.sendgrid.com/v3/mail/send', {
          method: 'POST',
          headers: { 'Authorization': `Bearer ${settings.smtpPass}`, 'Content-Type': 'application/json' },
          body: JSON.stringify({ personalizations: [{ to: [{ email: user.email }] }], from: { email: 'bictcomputereducation1@gmail.com', name: 'VexoKart Support' }, subject: aiContent.title, content: [{ type: 'text/html', value: aiContent.email }] })
        });
        if (!response.ok) throw new Error(`HTTP ${response.status}`);
      });
    }

    if (settings.smsEnabled && user.phone) {
      await sendWithRetry('sms', async () => sendQuickSMS(user.phone, aiContent.sms));
    }
  };

  return (
    <NotificationContext.Provider value={{ 
      settings, logs, inbox, unreadCount, updateSettings, 
      notifyOrderUpdate, notifyLogin, sendInvoiceEmail, markAsRead, markAllAsRead, clearLogs, fetchInbox
    }}>
      {children}
    </NotificationContext.Provider>
  );
};

export const useNotifications = () => {
  const context = useContext(NotificationContext);
  if (!context) throw new Error('useNotifications must be used within NotificationProvider');
  return context;
};

import React, { createContext, useState, useEffect, ReactNode, useContext } from 'react';
import { User, Address } from '../types.ts';
import { VendorContext } from './VendorContext.tsx';
import { useNotifications } from './NotificationContext.tsx';
import { BASE_API_URL, API_HEADERS } from '../constants.ts';

interface AuthContextType {
  user: User | null;
  users: User[];
  isLoading: boolean;
  isAuthenticated: boolean;
  login: (email: string, pass: string) => Promise<void>;
  signup: (name: string, email: string, phone: string, pass: string) => Promise<void>;
  signupAsVendor: (name: string, email: string, pass: string, storeName: string, code: string) => Promise<void>;
  logout: () => void;
  addUser: (userData: { name: string; email: string; phone: string; pass: string; role: User['role']; storeName?: string }) => Promise<void>;
  addAddress: (address: Omit<Address, 'id'>) => Promise<void>;
  updateAddress: (address: Address) => Promise<void>;
  deleteAddress: (addressId: string) => Promise<void>;
  deleteUser: (email: string) => Promise<void>;
  addToWishlist: (productId: number) => Promise<void>;
  removeFromWishlist: (productId: number) => Promise<void>;
  isInWishlist: (productId: number) => boolean;
  updateUserSession: (userData: User) => void;
  fetchUsers: () => Promise<void>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

const sanitizeUser = (u: any): User => ({
  ...u,
  id: u.id ? Number(u.id) : 0,
  addresses: Array.isArray(u.addresses) ? u.addresses : [],
  wishlist: Array.isArray(u.wishlist) ? u.wishlist : [],
  recentlyViewed: Array.isArray(u.recentlyViewed) ? u.recentlyViewed : []
});

export const AuthProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  const vendorContext = useContext(VendorContext);
  const { notifyLogin, fetchInbox } = useNotifications();

  const fetchUsers = async () => {
    try {
      const response = await fetch(`${BASE_API_URL}/users?select=*`, { 
        headers: { ...API_HEADERS, 'Cache-Control': 'no-cache' } 
      });
      if (!response.ok) return;
      const data = await response.json();
      if (Array.isArray(data)) {
        setAllUsers(data.map(sanitizeUser));
      }
    } catch (error) {
      console.error("Error fetching users:", error);
    }
  };

  useEffect(() => {
    const init = async () => {
      setIsLoading(true);
      await fetchUsers();

      const sessionUser = localStorage.getItem('vexokart-user');
      if (sessionUser) {
        try {
          const parsed = JSON.parse(sessionUser);
          const res = await fetch(`${BASE_API_URL}/users?email=ilike.${encodeURIComponent(parsed.email)}&select=*`, { headers: API_HEADERS });
          if (res.ok) {
              const userData = await res.json();
              if (Array.isArray(userData) && userData.length > 0) {
                const foundUser = sanitizeUser(userData[0]);
                setUser(foundUser);
                fetchInbox(foundUser.email);
              }
          }
        } catch (e) {
          console.error("Session restoration failed:", e);
        }
      }
      setIsLoading(false);
    };
    init();
  }, []);

  const updateUserSession = (userData: User) => {
    const safeUser = sanitizeUser(userData);
    setUser(safeUser);
    localStorage.setItem('vexokart-user', JSON.stringify(safeUser));
  };

  const login = async (email: string, pass: string) => {
    try {
      const query = `email=ilike.${encodeURIComponent(email)}&password=eq.${encodeURIComponent(pass)}&select=*`;
      const res = await fetch(`${BASE_API_URL}/users?${query}`, { headers: API_HEADERS });

      if (!res.ok) throw new Error("Auth service currently unavailable.");

      const data = await res.json();
      if (Array.isArray(data) && data.length > 0) {
        const loggedUser = sanitizeUser(data[0]);
        updateUserSession(loggedUser);

        // Trigger Notifications
        notifyLogin(loggedUser);
        fetchInbox(loggedUser.email);

        return;
      }

      const checkRes = await fetch(`${BASE_API_URL}/users?email=ilike.${encodeURIComponent(email)}&select=email`, { headers: API_HEADERS });
      const checkData = await checkRes.json().catch(() => []);

      if (Array.isArray(checkData) && checkData.length === 0) {
          throw new Error('User not found. Please register first.');
      }

      throw new Error('Invalid credentials.');
    } catch (err: any) {
      console.error("Login Error:", err);
      throw new Error(err.message || 'Network error. Please check your internet.');
    }
  };

  const signup = async (name: string, email: string, phone: string, pass: string) => {
    try {
        const checkRes = await fetch(`${BASE_API_URL}/users?email=ilike.${encodeURIComponent(email)}&select=email`, { headers: API_HEADERS });
        const existing = await checkRes.json().catch(() => []);
        if (Array.isArray(existing) && existing.length > 0) throw new Error('Email already registered');

        const newUser = {
          name, 
          email: email.toLowerCase(), 
          phone, 
          password: pass, 
          role: 'user',
          addresses: [], 
          wishlist: [], 
          recentlyViewed: [], 
          created_at: new Date().toISOString()
        };

        const res = await fetch(`${BASE_API_URL}/users`, {
          method: 'POST',
          headers: { ...API_HEADERS, 'Prefer': 'return=minimal' },
          body: JSON.stringify(newUser)
        });

        if (!res.ok) throw new Error('Account creation rejected. Try again later.');

        await fetchUsers();
    } catch (err: any) {
        console.error("Signup Error:", err);
        throw new Error(err.message || "Connection failed.");
    }
  };

  const signupAsVendor = async (name: string, email: string, pass: string, storeName: string, code: string) => {
     throw new Error("Direct vendor signup is managed via admin panel.");
  };

  const logout = () => {
    localStorage.removeItem('vexokart-user');
    setUser(null);
  };

  const addUser = async (userData: { name: string; email: string; phone: string; pass: string; role: User['role']; storeName?: string }) => {
    try {
        const newUser = {
          name: userData.name,
          email: userData.email.toLowerCase(),
          phone: userData.phone,
          password: userData.pass,
          role: userData.role,
          addresses: [],
          wishlist: [],
          recentlyViewed: [],
          created_at: new Date().toISOString()
        };

        const res = await fetch(`${BASE_API_URL}/users`, {
          method: 'POST',
          headers: { ...API_HEADERS, 'Prefer': 'return=representation' },
          body: JSON.stringify(newUser)
        });

        if (!res.ok) throw new Error('Identity creation failed');

        const createdUsers = await res.json();
        const createdUser = sanitizeUser(createdUsers[0]);

        if (userData.role === 'vendor' && vendorContext) {
            await vendorContext.addVendorRecord({
                user_id: createdUser.id.toString(),
                store_name: userData.storeName || `${userData.name}'s Store`,
                owner_name: userData.name,
                email: userData.email.toLowerCase(),
                phone: userData.phone,
                profile_image: `https://ui-avatars.com/api/?name=${encodeURIComponent(userData.storeName || userData.name)}&background=FF8A00&color=fff`,
                status: 'pending'
            });
            await vendorContext.refreshVendors();
        }

        await fetchUsers();
    } catch (err: any) {
        console.error("AddUser Error:", err);
        throw err;
    }
  };

  const addAddress = async (address: Omit<Address, 'id'>) => {
    if (!user) return;
    try {
        const newAddress = { ...address, id: Date.now().toString() };
        const currentAddresses = Array.isArray(user.addresses) ? user.addresses : [];
        const updatedAddresses = [...currentAddresses, newAddress];

        await fetch(`${BASE_API_URL}/users?id=eq.${user.id}`, {
          method: 'PATCH',
          headers: { ...API_HEADERS, 'Prefer': 'return=minimal' },
          body: JSON.stringify({ addresses: updatedAddresses })
        });
        setUser({ ...user, addresses: updatedAddresses });
    } catch (e) {
        console.error("Address update failed:", e);
    }
  };

  const updateAddress = async (address: Address) => {
    if (!user) return;
    try {
        const currentAddresses = Array.isArray(user.addresses) ? user.addresses : [];
        const updatedAddresses = currentAddresses.map(a => a.id === address.id ? address : a);

        await fetch(`${BASE_API_URL}/users?id=eq.${user.id}`, {
          method: 'PATCH',
          headers: { ...API_HEADERS, 'Prefer': 'return=minimal' },
          body: JSON.stringify({ addresses: updatedAddresses })
        });
        setUser({ ...user, addresses: updatedAddresses });
    } catch (e) {
        console.error("Address update failed:", e);
    }
  };

  const deleteAddress = async (addressId: string) => {
    if (!user) return;
    try {
        const currentAddresses = Array.isArray(user.addresses) ? user.addresses : [];
        const updatedAddresses = currentAddresses.filter(a => a.id !== addressId);

        await fetch(`${BASE_API_URL}/users?id=eq.${user.id}`, {
          method: 'PATCH',
          headers: { ...API_HEADERS, 'Prefer': 'return=minimal' },
          body: JSON.stringify({ addresses: updatedAddresses })
        });
        setUser({ ...user, addresses: updatedAddresses });
    } catch (e) {
        console.error("Address deletion failed:", e);
    }
  };

  const deleteUser = async (email: string) => {
    if (email === 'admin@vexokart.com') return;
    try {
        await fetch(`${BASE_API_URL}/users?email=eq.${encodeURIComponent(email)}`, { 
            method: 'DELETE', 
            headers: { ...API_HEADERS, 'Prefer': 'return=minimal' } 
        });
        await fetchUsers();
    } catch (e) {
        console.error("User deletion failed:", e);
    }
  };

  const addToWishlist = async (productId: number) => {
    if (!user) return;
    const currentWishlist = Array.isArray(user.wishlist) ? user.wishlist : [];
    if (currentWishlist.includes(productId)) return;

    try {
        const updated = [...currentWishlist, productId];
        await fetch(`${BASE_API_URL}/users?id=eq.${user.id}`, {
          method: 'PATCH',
          headers: { ...API_HEADERS, 'Prefer': 'return=minimal' },
          body: JSON.stringify({ wishlist: updated })
        });
        setUser({ ...user, wishlist: updated });
    } catch (e) {
        console.error("Wishlist sync failed:", e);
    }
  };

  const removeFromWishlist = async (productId: number) => {
    if (!user) return;
    try {
        const currentWishlist = Array.isArray(user.wishlist) ? user.wishlist : [];
        const updated = currentWishlist.filter(id => id !== productId);

        await fetch(`${BASE_API_URL}/users?id=eq.${user.id}`, {
          method: 'PATCH',
          headers: { ...API_HEADERS, 'Prefer': 'return=minimal' },
          body: JSON.stringify({ wishlist: updated })
        });
        setUser({ ...user, wishlist: updated });
    } catch (e) {
        console.error("Wishlist sync failed:", e);
    }
  };

  const isInWishlist = (productId: number) => {
    if (!user) return false;
    const currentWishlist = Array.isArray(user.wishlist) ? user.wishlist : [];
    return currentWishlist.includes(productId);
  };

  return (
    <AuthContext.Provider value={{ 
      user, users: allUsers, isLoading, isAuthenticated: !!user, 
      login, signup, signupAsVendor, logout, addUser, addAddress, updateAddress, 
      deleteAddress, deleteUser, addToWishlist, removeFromWishlist, 
      isInWishlist, updateUserSession, fetchUsers 
    }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) throw new Error('useAuth must be used within an AuthProvider');
  return context;
};

import React, {
  createContext,
  useState,
  useEffect,
  ReactNode,
  useContext,
} from "react";
import { Order, OrderStatus, Address, PaymentStatus } from "../types.ts";
import { useAuth } from "./AuthContext.tsx";
import { useNotifications } from "./NotificationContext.tsx";
import { BASE_API_URL, API_HEADERS } from "../constants.ts";

interface OrderContextType {
  orders: any[]; // Using any temporarily for joined structure
  isLoading: boolean;
  addOrder: (orderData: any) => Promise<string>;
  updateOrderStatus: (
    orderId: string,
    status: OrderStatus,
    details?: any
  ) => Promise<void>;
  generateShippingLabel: (orderId: string) => Promise<void>;
  refreshOrders: () => Promise<void>;
  getOrderById: (orderId: string) => any | undefined;
  getOrderByToken: (token: string) => any | undefined;
  updateOrderByToken: (
    token: string,
    status: OrderStatus,
    note?: string
  ) => Promise<{ success: boolean; message: string }>;
}

const OrderContext = createContext<OrderContextType | undefined>(undefined);

export const OrderProvider: React.FC<{ children: ReactNode }> = ({
  children,
}) => {
  const { user } = useAuth();
  const { sendInvoiceEmail, notifyOrderUpdate } = useNotifications();
  const [orders, setOrders] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  /* =========================
     FETCH ORDERS (WITH JOIN)
  ========================== */
  const refreshOrders = async () => {
    if (!user) return;

    try {
      setIsLoading(true);

      // Join with vendors table to get store_name for invoices and orders
      let url = `${BASE_API_URL}/orders?select=*,vendor:vendors(store_name)&order=created_at.desc`;

      if (user.role === "user") {
        url += `&user_id=eq.${user.id}`;
      }

      const res = await fetch(url, {
        headers: { ...API_HEADERS, "Cache-Control": "no-cache" },
      });

      if (!res.ok) throw new Error("Failed to fetch orders");

      const data = await res.json();

      if (Array.isArray(data)) {
        setOrders(
          data.map((o: any) => ({
            ...o,
            id: o.id.toString(),
            total: Number(o.total_amount || 0),
            statusHistory: o.status_history || [],
            qrToken: o.qr_token,
            date: o.created_at,
            invoice_generated: o.invoice_generated ?? true,
            // Fallback for store_name from joined vendor object
            seller_name: o.vendor?.store_name || "VexoKart Direct",
            shippingAddress: o.shippingaddress || o.address || null,
          }))
        );
      }
    } catch (e) {
      console.error("[OrderContext] Order fetch failed", e);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    if (user) refreshOrders();
    else setOrders([]);
  }, [user]);

  /* =========================
     CREATE ORDER
  ========================== */
  const addOrder = async (orderData: any): Promise<string> => {
    if (!user) throw new Error("Authentication required to place order.");

    const timestamp = new Date().toISOString();
    const qrToken = Math.random().toString(36).substring(2, 15);

    const addressSnapshot: Address = {
      id: orderData.shippingAddress?.id || Date.now().toString(),
      fullName: orderData.shippingAddress?.fullName || 'Customer',
      street: orderData.shippingAddress?.street || '',
      city: orderData.shippingAddress?.city || '',
      state: orderData.shippingAddress?.state || '',
      zip: orderData.shippingAddress?.zip || '',
      phone: orderData.shippingAddress?.phone || '',
    };

    // Determine vendor_id for the order record (numeric/bigint)
    const rawVendorId = orderData.items[0]?.vendor_id;
    let numericVendorId = null;
    if (rawVendorId && !isNaN(Number(rawVendorId))) {
      numericVendorId = Number(rawVendorId);
    }

    const payload = {
      user_id: Number(user.id),
      vendor_id: numericVendorId,
      items: orderData.items,
      total_amount: Number(orderData.total),
      payment_mode: orderData.payment_method,
      payment_status: orderData.payment_method === "Cash on Delivery" ? "cod_pending" : "paid",
      payment_id: orderData.payment_id || null, 
      address: addressSnapshot,
      shippingaddress: addressSnapshot,
      status: "Placed" as OrderStatus,
      qr_token: qrToken,
      invoice_generated: true,
      status_history: [{
          status: "Placed" as OrderStatus,
          timestamp,
          actor: "User" as const,
          note: "Order placed successfully",
      }],
      created_at: timestamp,
    };

    try {
      const res = await fetch(`${BASE_API_URL}/orders`, {
        method: "POST",
        headers: { 
          ...API_HEADERS, 
          "Prefer": "return=representation" 
        },
        body: JSON.stringify(payload),
      });

      if (!res.ok) {
        const errorBody = await res.json().catch(() => ({}));
        const errorMessage = errorBody.message || errorBody.details || `Server responded with ${res.status}`;
        throw new Error(`Order System Error: ${errorMessage}`);
      }

      const result = await res.json();
      const createdOrder = result[0];

      // Background refresh and triggers
      refreshOrders();
      try {
        const orderForNotify = { ...createdOrder, id: createdOrder.id.toString(), total: Number(createdOrder.total_amount), shippingAddress: createdOrder.shippingaddress };
        sendInvoiceEmail(orderForNotify, user);
        notifyOrderUpdate(orderForNotify, user); // Trigger SMS Alert
      } catch (triggerErr) {
        console.warn("Automation triggers delayed:", triggerErr);
      }

      return createdOrder.id.toString();
    } catch (err: any) {
      console.error("[CRITICAL] Order Placement Failed:", err);
      throw err;
    }
  };

  const updateOrderStatus = async (orderId: string, status: OrderStatus, details: any = {}) => {
    const order = orders.find((o) => o.id === orderId);
    if (!order) return;

    const history = order?.statusHistory || [];
    const newHistory = [...history, {
        status,
        timestamp: new Date().toISOString(),
        actor: user?.role === "vendor" ? "Vendor" : user?.role === "admin" ? "Admin" : "System",
        note: details.note || `Order status transitioned to ${status}`,
    }];

    try {
      const res = await fetch(`${BASE_API_URL}/orders?id=eq.${orderId}`, {
        method: "PATCH",
        headers: { ...API_HEADERS },
        body: JSON.stringify({ 
          status, 
          status_history: newHistory,
          ...(details.courier_name && { courier_name: details.courier_name }),
          ...(details.tracking_id && { tracking_id: details.tracking_id }),
          ...(details.label_url && { label_url: details.label_url })
        }),
      });

      if (!res.ok) throw new Error("Status update failed");
      await refreshOrders();

      // Notify on specific changes (like cancellation)
      if (status === 'Cancelled' && user) {
          notifyOrderUpdate(order, user);
      }
    } catch (err) { 
      console.error("Status Update Error:", err); 
    }
  };

  const generateShippingLabel = async (orderId: string) => {
    const labelUrl = `https://ghzadiplpazekzgjbdxu.supabase.co/storage/v1/object/public/labels/${orderId}.pdf`;
    await updateOrderStatus(orderId, "Packed", { label_url: labelUrl });
  };

  const getOrderById = (id: string) => orders.find((o) => o.id === id);
  const getOrderByToken = (token: string) => orders.find((o) => o.qrToken === token || o.qr_token === token);

  const updateOrderByToken = async (token: string, status: OrderStatus, note?: string) => {
    const order = getOrderByToken(token);
    if (!order) return { success: false, message: "Invalid package manifest token." };
    await updateOrderStatus(order.id, status, { note });
    return { success: true, message: `Manifest updated to ${status}` };
  };

  return (
    <OrderContext.Provider
      value={{
        orders,
        isLoading,
        addOrder,
        updateOrderStatus,
        generateShippingLabel,
        refreshOrders,
        getOrderById,
        getOrderByToken,
        updateOrderByToken,
      }}
    >
      {children}
    </OrderContext.Provider>
  );
};

export const useOrders = () => {
  const context = useContext(OrderContext);
  if (!context) throw new Error("OrderContext provider missing.");
  return context;
};

import React, { createContext, useState, useContext, ReactNode, useEffect } from 'react';
