            // Fallback for store_name from joined vendor object
            seller_name: o.vendor?.store_name || "VexoKart Direct",
            shippingAddress: o.shippingaddress || o.address || null,
          }))
        );
      }
    } catch (e) {
      console.error("[OrderContext] Order fetch failed", e);
    } finally {
      setIsLoading(false);
    }
  };

