const OrderContext = createContext<OrderContextType | undefined>(undefined);

export const OrderProvider: React.FC<{ children: ReactNode }> = ({
  children,
}) => {
  const { user, users } = useAuth();
  const { sendInvoiceEmail, notifyOrderUpdate, createAppNotification, fetchInbox } = useNotifications();
  const [orders, setOrders] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  const refreshOrders = async () => {
    if (!user) return;

    try {
      setIsLoading(true);
      let url = `${BASE_API_URL}/orders?select=*,vendor:vendors(store_name,store_address,phone)&order=created_at.desc`;

      if (user.role === "user") {
        url += `&user_id=eq.${user.id}`;
      }

      const res = await fetch(url, {
        headers: { ...API_HEADERS, "Cache-Control": "no-cache" },
      });

      if (!res.ok) throw new Error("Failed to fetch orders");

      const data = await res.json();

      if (Array.isArray(data)) {
        setOrders(
          data.map((o: any) => ({
            ...o,
            id: o.id.toString(),
            total: Number(o.total_amount || 0),
            statusHistory: o.status_history || [],
            qrToken: o.qr_token,
            date: o.created_at,
            seller_name: o.vendor?.store_name || "VexoKart Direct",
            shippingAddress: o.shipping_address || o.shippingaddress || o.address || null,
          }))
        );
      }
    } catch (e) {
      console.error("[OrderContext] Order fetch failed", e);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    if (user) {
        refreshOrders();
        fetchInbox(user);
    } else {
        setOrders([]);
    }
  }, [user]);

  const addOrder = async (orderData: any): Promise<string> => {
    if (!user) throw new Error("Authentication required to place order.");

    const timestamp = new Date().toISOString();
    const qrToken = Math.random().toString(36).substring(2, 15);

    const addressSnapshot: Address = {
      id: orderData.shippingAddress?.id || Date.now().toString(),
      fullName: orderData.shippingAddress?.fullName || 'Customer',
      street: orderData.shippingAddress?.street || '',
      city: orderData.shippingAddress?.city || '',
      state: orderData.shippingAddress?.state || '',
      zip: orderData.shippingAddress?.zip || '',
      phone: orderData.shippingAddress?.phone || '',
    };

    const rawVendorId = orderData.items[0]?.vendor_id;
    let numericVendorId = null;
    if (rawVendorId && !isNaN(Number(rawVendorId))) {
      numericVendorId = Number(rawVendorId);
    }

    const payload = {
      user_id: Number(user.id),
      vendor_id: numericVendorId,
      items: orderData.items,
      total_amount: Number(orderData.total),
      payment_mode: orderData.payment_method,
      payment_status: orderData.payment_method === "Cash on Delivery" ? "cod_pending" : "paid",
      shipping_address: addressSnapshot,
      status: "Placed" as OrderStatus,
      qr_token: qrToken,
      status_history: [{
          status: "Placed" as OrderStatus,
          timestamp,
          actor: "User" as const,
          note: orderData.payment_id ? `Order placed (Ref: ${orderData.payment_id})` : "Order placed",
      }],
      created_at: timestamp,
    };

    try {
      const res = await fetch(`${BASE_API_URL}/orders`, {
        method: "POST",
        headers: { ...API_HEADERS, "Prefer": "return=representation" },
        body: JSON.stringify(payload),
      });

      if (!res.ok) {
        const errorBody = await res.json().catch(() => ({}));
        throw new Error(`Order System Error: ${errorBody.message || res.statusText}`);
      }

      const result = await res.json();
      const createdOrder = result[0];
      const finalOrderId = createdOrder.id.toString();

      // ✅ CREATE NOTIFICATIONS
      // 1. For User
      await createAppNotification({
        user_id: user.id,
        role: 'user',
        title: 'Order Placed',
        message: `Your order #${finalOrderId} has been placed successfully.`,
        type: 'order_placed'
      });
      // 2. For Vendor
      if (numericVendorId) {
          await createAppNotification({
            vendor_id: numericVendorId,
            role: 'vendor',
            title: 'New Order Received',
            message: `You received a new order #${finalOrderId}. Check dashboard for details.`,
            type: 'vendor_order_new'
          });
      }
      // 3. For Admin
      await createAppNotification({
        role: 'admin',
        title: 'Platform Order Received',
        message: `New order #${finalOrderId} received from ${user.name}.`,
        type: 'admin_order_new'
      });

      // Notify payment success if not COD
      if (orderData.payment_method !== "Cash on Delivery") {
           await createAppNotification({
                user_id: user.id,
                role: 'user',
                title: 'Payment Successful',
                message: `Payment confirmed for Order #${finalOrderId}. Transaction ID: ${orderData.payment_id || 'N/A'}`,
                type: 'payment_success'
            });
            await createAppNotification({
                role: 'admin',
                title: 'Payment Received',
                message: `Payment of ₹${orderData.total} received for Order #${finalOrderId}.`,
                type: 'admin_payment'
            });
      }

      refreshOrders();
      fetchInbox(user);

      (async () => {
          try {
              const orderForNotify = { ...createdOrder, id: finalOrderId, total: Number(createdOrder.total_amount), shippingAddress: createdOrder.shipping_address };
              await Promise.allSettled([sendInvoiceEmail(orderForNotify, user)]);
          } catch (e) {}
      })();

      return finalOrderId;
    } catch (err: any) {
      console.error("[CRITICAL] Order Placement Failed:", err);
      throw err;
    }
  };

  const createShipment = async (orderId: string, vendor: any) => {
    const order = orders.find(o => o.id === orderId);
    if (!order) throw new Error("Order manifest not found.");

    try {
      const response = await fetch(`${EDGE_FUNCTION_URL}/create-shipment`, {
        method: 'POST',
        headers: { ...API_HEADERS, 'Authorization': `Bearer ${process.env.API_KEY || ''}` },
        body: JSON.stringify({ order_id: orderId, order_data: order, vendor_data: vendor })
      });

      if (!response.ok) throw new Error("Shiprocket gateway unreachable.");

      const logisticsData = await response.json();
      await updateOrderStatus(orderId, 'Packed', {
        note: `Shiprocket manifest created. AWB: ${logisticsData.awb_code}`,
        ...logisticsData
      });

    } catch (err: any) {
      throw err;
    }
  };

  const updateOrderStatus = async (orderId: string, status: OrderStatus, details: any = {}) => {
    const order = orders.find((o) => o.id === orderId);
    if (!order) return;

    const history = order?.statusHistory || [];
    const newHistory = [...history, {
        status,
        timestamp: new Date().toISOString(),
        actor: user?.role === "vendor" ? "Vendor" : user?.role === "admin" ? "Admin" : "System",
        note: details.note || `Order status transitioned to ${status}`,
    }];

    const trackingCode = details.awb_code || details.tracking_id;

    const updatePayload: any = { 
      status, 
      status_history: newHistory,
      ...(details.shipment_id && { shipment_id: details.shipment_id }),
      ...(trackingCode && { awb_code: trackingCode }),
      ...(details.courier_name && { courier_name: details.courier_name })
    };

    try {
      const res = await fetch(`${BASE_API_URL}/orders?id=eq.${orderId}`, {
        method: "PATCH",
        headers: { ...API_HEADERS },
        body: JSON.stringify(updatePayload),
      });

      if (!res.ok) throw new Error("Status update failed");

      // ✅ STATUS CHANGE NOTIFICATIONS
      if (status === 'Shipped') {
          await createAppNotification({
            user_id: order.user_id,
            role: 'user',
            title: 'Order Shipped',
            message: `Your order #${orderId} has been handed over to ${details.courier_name || 'courier'}.`,
            type: 'order_shipped'
          });
          if (order.vendor_id) {
              await createAppNotification({
                vendor_id: order.vendor_id,
                role: 'vendor',
                title: 'Order Shipped Successfully',
                message: `Manifest for #${orderId} is now marked as Shipped.`,
                type: 'vendor_shipped'
              });
          }
      } else if (status === 'Delivered') {
          await createAppNotification({
            user_id: order.user_id,
            role: 'user',
            title: 'Order Delivered',
            message: `Package #${orderId} has been successfully delivered. Hope you like it!`,
            type: 'order_delivered'
          });
      }

      await refreshOrders();
      if (user) fetchInbox(user);
    } catch (err) { 
      console.error("Status Update Error:", err); 
    }
  };

  const generateShippingLabel = async (orderId: string) => {
    const order = orders.find(o => o.id === orderId);
    if (order?.label_url) window.open(order.label_url, '_blank');
  };

  const getOrderById = (id: string) => orders.find((o) => o.id === id);
  const getOrderByToken = (token: string) => orders.find((o) => o.qrToken === token || o.qr_token === token);

  const updateOrderByToken = async (token: string, status: OrderStatus, note?: string) => {
    const order = getOrderByToken(token);
    if (!order) return { success: false, message: "Invalid package manifest token." };
    await updateOrderStatus(order.id, status, { note });
    return { success: true, message: `Manifest updated to ${status}` };
  };

  return (
    <OrderContext.Provider
      value={{
        orders,
        isLoading,
        addOrder,
        updateOrderStatus,
        createShipment,
        generateShippingLabel,
        refreshOrders,
        getOrderById,
        getOrderByToken,
        updateOrderByToken,
      }}
    >
      {children}
    </OrderContext.Provider>
  );
};

export const useOrders = () => {
  const context = useContext(OrderContext);
  if (!context) throw new Error("OrderContext provider missing.");
  return context;
};

import React, { useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useNotifications } from '../context/NotificationContext';
import { useAuth } from '../context/AuthContext';
import Header from '../components/Header';
import { ChevronLeftIcon } from '../components/icons/ChevronLeftIcon';
import GlassmorphicCard from '../components/GlassmorphicCard';

const NotificationsPage: React.FC = () => {
    const navigate = useNavigate();
    const { user } = useAuth();
    const { inbox, markAsRead, markAllAsRead, fetchInbox } = useNotifications();

    useEffect(() => {
        if (user) fetchInbox(user);
    }, [user]);

    const getRelativeTime = (timestamp: string) => {
        const now = new Date();
        const past = new Date(timestamp);
        const diffMs = now.getTime() - past.getTime();
        const diffMins = Math.floor(diffMs / 60000);
        const diffHours = Math.floor(diffMins / 60);
        const diffDays = Math.floor(diffHours / 24);

        if (diffMins < 1) return 'Just now';
        if (diffMins < 60) return `${diffMins}m ago`;
        if (diffHours < 24) return `${diffHours}h ago`;
        if (diffDays < 7) return `${diffDays}d ago`;
        return past.toLocaleDateString();
    };

    return (
        <div className="bg-surface min-h-screen">
            <div className="sticky top-0 z-10 p-4 bg-white/80 backdrop-blur-md flex items-center justify-between border-b border-border shadow-sm">
                <div className="flex items-center">
                    <button onClick={() => navigate(-1)} className="p-2 -ml-2 mr-2">
                        <ChevronLeftIcon className="h-6 w-6 text-text-main" />
                    </button>
                    <h1 className="text-xl font-black text-text-main italic tracking-tight uppercase">Inbox</h1>
                </div>
                {inbox.some(m => !m.is_read) && (
                    <button 
                        onClick={markAllAsRead}
                        className="text-[10px] font-black uppercase text-accent tracking-widest hover:bg-accent/5 px-3 py-1 rounded-lg"
                    >
                        Mark All Read
                    </button>
                )}
            </div>

            <div className="p-4 space-y-3 max-w-2xl mx-auto">
                {inbox.length === 0 ? (
                    <div className="py-32 text-center bg-white rounded-3xl border border-dashed border-border p-10">
                        <div className="w-24 h-24 bg-surface rounded-full flex items-center justify-center mx-auto mb-6 shadow-inner">
                            <svg className="w-12 h-12 text-text-muted/30" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="1.5" d="M15 17h5l-1.405-1.405A2.032 2.032 0 0118 14.158V11a6.002 6.002 0 00-4-5.659V5a2 2 0 10-4 0v.341C7.67 6.165 6 8.388 6 11v3.159c0 .538-.214 1.055-.595 1.436L4 17h5m6 0v1a3 3 0 11-6 0v-1m6 0H9" />
                            </svg>
                        </div>
                        <h3 className="text-xl font-black text-text-main uppercase italic">Inbox Empty</h3>
                        <p className="text-text-muted text-xs font-bold uppercase mt-2 tracking-widest">No notifications to show at this moment.</p>
                    </div>
                ) : (
                    inbox.map((msg) => (
                        <GlassmorphicCard 
                            key={msg.id} 
                            className={`p-5 transition-all relative cursor-pointer border-none shadow-premium ${!msg.is_read ? 'bg-white scale-100' : 'bg-white/60 opacity-70 grayscale-[0.5]'}`}
                            onClick={() => !msg.is_read && markAsRead(msg.id)}
                        >
                            {!msg.is_read && (
                                <div className="absolute top-6 left-2 w-2 h-2 bg-accent rounded-full shadow-[0_0_10px_rgba(255,138,0,0.5)]"></div>
                            )}
                            <div className="pl-4">
                                <div className="flex justify-between items-start mb-1">
                                    <h4 className={`text-sm tracking-tight leading-tight uppercase italic ${!msg.is_read ? 'font-black text-text-main' : 'font-bold text-text-secondary'}`}>
                                        {msg.title}
                                    </h4>
                                    <span className="text-[8px] font-black text-text-muted uppercase tracking-widest bg-surface px-1.5 py-0.5 rounded">
                                        {getRelativeTime(msg.created_at)}
                                    </span>
                                </div>
                                <p className={`text-xs leading-relaxed mt-1 ${!msg.is_read ? 'text-text-secondary font-medium' : 'text-text-muted'}`}>
                                    {msg.message}
                                </p>
                                <div className="mt-4 flex items-center gap-2">
                                     <div className={`w-6 h-6 rounded-lg flex items-center justify-center border ${msg.is_read ? 'bg-gray-100 border-gray-200' : 'bg-accent/5 border-accent/10'}`}>
                                        <svg className={`w-3.5 h-3.5 ${msg.is_read ? 'text-text-muted' : 'text-accent'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                                        </svg>
                                     </div>
                                     <span className="text-[9px] font-black uppercase text-text-muted tracking-tighter">System Alert</span>
                                </div>
                            </div>
                        </GlassmorphicCard>
                    ))
                )}
            </div>

            <div className="p-10 text-center pb-24">
                <p className="text-[8px] text-text-muted font-bold uppercase tracking-[0.4em] italic opacity-40">End of Notification Manifest</p>
            </div>
        </div>
    );
};

export default NotificationsPage;

