            });
            await createAppNotification({
                role: 'admin',
                title: 'Payment Received',
                message: `Payment of ₹${orderData.total} received for Order #${finalOrderId}.`,
                type: 'admin_payment'
            });
      }

      refreshOrders();
      await fetchInbox(user);

      (async () => {
          try {
              const orderForNotify = { ...createdOrder, id: finalOrderId, total: Number(createdOrder.total_amount), shippingAddress: createdOrder.shipping_address };
              await Promise.allSettled([sendInvoiceEmail(orderForNotify, user)]);
          } catch (e) {}
      })();

      return finalOrderId;
    } catch (err: any) {
      console.error("[CRITICAL] Order Placement Failed:", err);
      throw err;
    }
  };

  const createShipment = async (orderId: string, vendor: any) => {
    const order = orders.find(o => o.id === orderId);
    if (!order) throw new Error("Order manifest not found.");

    try {
      const response = await fetch(`${EDGE_FUNCTION_URL}/create-shipment`, {
        method: 'POST',
        headers: { ...API_HEADERS, 'Authorization': `Bearer ${process.env.API_KEY || ''}` },
        body: JSON.stringify({ order_id: orderId, order_data: order, vendor_data: vendor })
      });

      if (!response.ok) {
          const errData = await response.json().catch(() => ({}));
          throw new Error(errData.message || "Shiprocket gateway unreachable.");
      }

      const logisticsData = await response.json();
      await updateOrderStatus(orderId, 'Packed', {
        note: `Shiprocket manifest created. AWB: ${logisticsData.awb_code}`,
        ...logisticsData
      });

    } catch (err: any) {
      throw err;
    }
  };

  const updateOrderStatus = async (orderId: string, status: OrderStatus, details: any = {}) => {
    const order = orders.find((o) => o.id === orderId);
    if (!order) return;

    const history = order?.statusHistory || [];
    const newHistory = [...history, {
        status,
        timestamp: new Date().toISOString(),
        actor: user?.role === "vendor" ? "Vendor" : user?.role === "admin" ? "Admin" : "System",
        note: details.note || `Order status transitioned to ${status}`,
    }];

    const trackingCode = details.awb_code || details.tracking_id;

    const updatePayload: any = { 
      status, 
      status_history: newHistory,
      ...(details.shipment_id && { shipment_id: details.shipment_id }),
      ...(trackingCode && { awb_code: trackingCode }),
      ...(details.courier_name && { courier_name: details.courier_name })
    };

    try {
      const res = await fetch(`${BASE_API_URL}/orders?id=eq.${orderId}`, {
        method: "PATCH",
        headers: { ...API_HEADERS },
        body: JSON.stringify(updatePayload),
      });

      if (!res.ok) throw new Error("Status update failed");

      if (status === 'Shipped') {
          await createAppNotification({
            user_id: order.user_id,
            role: 'user',
            title: 'Order Shipped',
            message: `Your order #${orderId} has been handed over to courier.`,
            type: 'order_shipped'
          });
      } else if (status === 'Delivered') {
          await createAppNotification({
            user_id: order.user_id,
            role: 'user',
            title: 'Order Delivered',
            message: `Package #${orderId} has been successfully delivered.`,
            type: 'order_delivered'
          });
      }

      await refreshOrders();
      if (user) fetchInbox(user);
    } catch (err) { 
      console.error("Status Update Error:", err); 
    }
  };

  const generateShippingLabel = async (orderId: string) => {
    const order = orders.find(o => o.id === orderId);
    if (order?.label_url) window.open(order.label_url, '_blank');
  };

  const getOrderById = (id: string) => orders.find((o) => o.id === id);
  const getOrderByToken = (token: string) => orders.find((o) => o.qrToken === token || o.qr_token === token);

  const updateOrderByToken = async (token: string, status: OrderStatus, note?: string) => {
    const order = getOrderByToken(token);
    if (!order) return { success: false, message: "Invalid package manifest token." };
    await updateOrderStatus(order.id, status, { note });
    return { success: true, message: `Manifest updated to ${status}` };
  };

  return (
    <OrderContext.Provider
      value={{
        orders,
        isLoading,
        addOrder,
        updateOrderStatus,
        createShipment,
        generateShippingLabel,
        refreshOrders,
        getOrderById,
        getOrderByToken,
        updateOrderByToken,
      }}
    >
      {children}
    </OrderContext.Provider>
  );
};

export const useOrders = () => {
  const context = useContext(OrderContext);
  if (!context) throw new Error("OrderContext provider missing.");
  return context;
};

import React, { createContext, useState, useEffect, ReactNode, useContext } from 'react';
import { Vendor } from '../types';
import { BASE_API_URL, API_HEADERS } from '../constants';

interface VendorContextType {
  vendors: Vendor[];
  currentVendor: Vendor | null;
  isVendorLoading: boolean;
  vendorError: string | null;
  addVendorRecord: (vendorData: Omit<Vendor, 'id' | 'created_at'>) => Promise<void>;
  updateVendorStatus: (vendorId: number, status: Vendor['status'], reason?: string) => Promise<void>;
  updateVendorProfile: (vendorId: number, updates: Partial<Vendor>) => Promise<void>;
  getVendorByUserId: (userId: string) => Vendor | undefined;
  getVendorById: (vendorId: string) => Vendor | undefined;
  getVendorByEmailDirect: (email: string) => Promise<Vendor | null>;
  fetchCurrentVendor: (userId: string, force?: boolean) => Promise<void>;
  refreshVendors: () => Promise<void>;
}

export const VendorContext = createContext<VendorContextType | undefined>(undefined);

// EXPLICIT COLUMNS: omits 'store_address' which is confirmed missing in the database schema.
const VENDOR_COLUMNS = 'id,user_id,store_name,profile_image,status,email,phone,owner_name,created_at,rejection_reason';

export const VendorProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [vendors, setVendors] = useState<Vendor[]>([]);
  const [currentVendor, setCurrentVendor] = useState<Vendor | null>(() => {
    const cached = sessionStorage.getItem('vxk_vendor_cache');
    return cached ? JSON.parse(cached) : null;
  });
  const [isVendorLoading, setIsVendorLoading] = useState(false);
  const [vendorError, setVendorError] = useState<string | null>(null);

  const fetchVendors = async () => {
    try {
      const res = await fetch(`${BASE_API_URL}/vendors?select=${VENDOR_COLUMNS}&order=created_at.desc`, { 
        headers: { ...API_HEADERS, 'Cache-Control': 'no-cache' } 
      });
      const data = await res.json();
      if (Array.isArray(data)) {
        setVendors(data);
      }
    } catch (error) {
      console.error("Error fetching vendors list:", error);
    }
  };

  const fetchCurrentVendor = async (userId: string, force = false) => {
    if (!userId) return;

    if (currentVendor && currentVendor.user_id === userId && !force) {
      backgroundSync(userId);
      return;
    }

    setIsVendorLoading(true);
    setVendorError(null);

    try {
      const res = await fetch(`${BASE_API_URL}/vendors?user_id=eq.${userId}&select=${VENDOR_COLUMNS}`, {
        headers: { ...API_HEADERS, 'Cache-Control': 'no-cache' }
      });

      if (!res.ok) throw new Error(`Server connection failed`);

      const data = await res.json();
      if (Array.isArray(data) && data.length > 0) {
        const profile = data[0];
        setCurrentVendor(profile);
        sessionStorage.setItem('vxk_vendor_cache', JSON.stringify(profile));
      } else {
        setVendorError("Authorized profile not found.");
      }
    } catch (error: any) {
      setVendorError(error.message || "Connection failed.");
    } finally {
      setIsVendorLoading(false);
    }
  };

  const backgroundSync = async (userId: string) => {
    try {
      const res = await fetch(`${BASE_API_URL}/vendors?user_id=eq.${userId}&select=${VENDOR_COLUMNS}`, {
        headers: { ...API_HEADERS, 'Cache-Control': 'no-cache' }
      });
      const data = await res.json();
      if (Array.isArray(data) && data.length > 0) {
        setCurrentVendor(data[0]);
        sessionStorage.setItem('vxk_vendor_cache', JSON.stringify(data[0]));
      }
    } catch (e) { /* Silent fail for background sync */ }
  };

  useEffect(() => {
    fetchVendors();
  }, []);

  const updateVendorProfile = async (id: number, updates: Partial<Vendor>) => {
    // SECURITY: Ensure we don't send store_address to the database if it doesn't exist
    const { store_address, ...dbUpdates } = updates as any;

    const res = await fetch(`${BASE_API_URL}/vendors?id=eq.${id}`, {
      method: 'PATCH',
      headers: { ...API_HEADERS, 'Prefer': 'return=representation' },
      body: JSON.stringify(dbUpdates)
    });

    if (!res.ok) {
        const err = await res.json().catch(() => ({}));
        throw new Error(err.message || 'Update failed');
    }

    if (currentVendor && currentVendor.id === id) {
        const updated = { ...currentVendor, ...updates };
        setCurrentVendor(updated);
        sessionStorage.setItem('vxk_vendor_cache', JSON.stringify(updated));
    }
    await fetchVendors();
  };

  const addVendorRecord = async (data: Omit<Vendor, 'id' | 'created_at'>) => {
    const { store_address, ...dbData } = data as any;
    const res = await fetch(`${BASE_API_URL}/vendors`, {
      method: 'POST',
      headers: API_HEADERS,
      body: JSON.stringify({ ...dbData, created_at: new Date().toISOString() })
    });
    if (!res.ok) throw new Error('Record creation failed');
    await fetchVendors();
  };

  const updateVendorStatus = async (id: number, status: Vendor['status'], reason?: string) => {
    await fetch(`${BASE_API_URL}/vendors?id=eq.${id}`, {
      method: 'PATCH',
      headers: API_HEADERS,
      body: JSON.stringify({ status, rejection_reason: reason })
    });
    await fetchVendors();
  };

  const getVendorByEmailDirect = async (email: string): Promise<Vendor | null> => {
    try {
      const res = await fetch(`${BASE_API_URL}/vendors?select=${VENDOR_COLUMNS}&email=ilike.${encodeURIComponent(email)}&status=eq.approved`, {
        headers: API_HEADERS
      });
      const data = await res.json();
      return (Array.isArray(data) && data.length > 0) ? data[0] : null;
    } catch (e) { return null; }
  };

  const getVendorByUserId = (uid: string) => vendors.find(v => v.user_id === uid);
  const getVendorById = (id: string) => vendors.find(v => v.id.toString() === id);

  return (
    <VendorContext.Provider value={{ 
      vendors, currentVendor, isVendorLoading, vendorError,
      addVendorRecord, updateVendorStatus, updateVendorProfile,
      getVendorByUserId, getVendorById, getVendorByEmailDirect,
      fetchCurrentVendor, refreshVendors: fetchVendors 
    }}>
      {children}
    </VendorContext.Provider>
  );
};

export const useVendors = () => {
  const context = useContext(VendorContext);
  if (!context) throw new Error('useVendors missing');
  return context;
};

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import { useVendors } from '../../context/VendorContext';
import GlassmorphicCard from '../../components/GlassmorphicCard';

const VendorProfilePage: React.FC = () => {
    const { user } = useAuth();
    const { currentVendor, updateVendorProfile } = useVendors();
    const navigate = useNavigate();

    const [storeName, setStoreName] = useState('');
    const [storeLogo, setStoreLogo] = useState('');
    const [logoPreview, setLogoPreview] = useState('');
    const [storeAddress, setStoreAddress] = useState('');
    const [storePhone, setStorePhone] = useState('');
    const [isUpdating, setIsUpdating] = useState(false);

    const inputClasses = "w-full mt-1 bg-surface text-text-main border border-gray-600 rounded-lg p-3 transition focus:outline-none focus:border-accent focus:ring-2 focus:ring-accent/50 disabled:opacity-50";

    useEffect(() => {
        if (currentVendor) {
            setStoreName(currentVendor.store_name || '');
            setStoreLogo(currentVendor.profile_image || '');
            setLogoPreview(currentVendor.profile_image || '');
            setStoreAddress(currentVendor.store_address || '');
            setStorePhone(currentVendor.phone || '');
        }
    }, [currentVendor]);

    /**
     * Resizes the image to prevent massive base64 payloads
     */
    const resizeLogo = (file: File, size = 400): Promise<string> => {
        return new Promise((resolve) => {
            const reader = new FileReader();
            reader.onload = (e) => {
                const img = new Image();
                img.onload = () => {
                    const canvas = document.createElement('canvas');
                    let width = img.width;
                    let height = img.height;

                    if (width > height) {
                        if (width > size) {
                            height *= size / width;
                            width = size;
                        }
                    } else {
                        if (height > size) {
                            width *= size / height;
                            height = size;
                        }
                    }

                    canvas.width = width;
                    canvas.height = height;
                    const ctx = canvas.getContext('2d');
                    ctx?.drawImage(img, 0, 0, width, height);
                    resolve(canvas.toDataURL('image/jpeg', 0.8));
                };
                img.src = e.target?.result as string;
            };
            reader.readAsDataURL(file);
        });
    };

    const handleImageChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            const file = e.target.files[0];
            setIsUpdating(true);
            try {
                const compressed = await resizeLogo(file);
                setStoreLogo(compressed);
                setLogoPreview(compressed);
            } catch (err) {
                console.error("Logo processing error:", err);
            } finally {
                setIsUpdating(false);
            }
        }
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!currentVendor) return;

        setIsUpdating(true);
        try {
            // Note: 'store_address' is intentionally excluded from the update profile call 
            // because the column does not exist in the database table.
            await updateVendorProfile(currentVendor.id, { 
                store_name: storeName, 
                profile_image: storeLogo,
                phone: storePhone,
                owner_name: currentVendor.owner_name
            });
            alert('Store profile updated successfully!');
            navigate('/vendor');
        } catch (err: any) {
            console.error('[VendorProfile] Update Error:', err);
            alert(`Failed to update profile: ${err.message || 'Unknown server error'}`);
        } finally {
            setIsUpdating(false);
        }
    };

    if (!currentVendor) {
        return (
            <div className="flex flex-col items-center justify-center p-20">
                <div className="w-8 h-8 border-4 border-accent border-t-transparent rounded-full animate-spin"></div>
                <p className="mt-4 text-text-muted font-bold text-xs uppercase tracking-widest">Loading Store Profile...</p>
            </div>
        );
    }

    return (
        <div className="space-y-6">
            <div className="flex justify-between items-center">
                <div>
                    <h1 className="text-3xl font-black text-text-main italic tracking-tight uppercase">Store Profile</h1>
                    <p className="text-text-muted mt-1">Configure your public storefront and dispatch settings.</p>
                </div>
            </div>

            <GlassmorphicCard className="p-8 max-w-3xl mx-auto">
                 <form onSubmit={handleSubmit} className="space-y-8">
                    <div className="flex flex-col items-center gap-6 pb-8 border-b border-border">
                        <div className="relative group">
                            <img src={logoPreview || `https://ui-avatars.com/api/?name=${encodeURIComponent(storeName || 'V')}&background=FF8A00&color=fff`} alt="Logo Preview" className="w-32 h-32 rounded-3xl object-cover bg-background border-4 border-white shadow-2xl transition-transform group-hover:scale-105" />
                            <input type="file" id="logoUpload" accept="image/*" onChange={handleImageChange} className="hidden" disabled={isUpdating} />
                            <label htmlFor="logoUpload" className="absolute -bottom-2 -right-2 p-3 bg-accent text-white rounded-2xl shadow-xl cursor-pointer hover:bg-orange-600 transition-colors">
                                <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
                            </label>
                        </div>
                        <div className="text-center">
                            <p className="text-lg font-black text-text-main tracking-tight italic uppercase">{storeName || 'My Store'}</p>
                            <p className="text-xs text-text-muted font-bold uppercase tracking-widest mt-1">Vendor ID: {currentVendor.id}</p>
                        </div>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                         <div className="col-span-full">
                            <label className="text-[10px] font-black uppercase text-text-muted mb-1 block">Display Store Name</label>
                            <input 
                                type="text" 
                                value={storeName} 
                                onChange={(e) => setStoreName(e.target.value)} 
                                required 
                                disabled={isUpdating}
                                className={inputClasses} 
                            />
                        </div>

                        <div>
                            <label className="text-[10px] font-black uppercase text-text-muted mb-1 block">Dispatch Phone Contact</label>
                            <input 
                                type="tel" 
                                value={storePhone} 
                                onChange={(e) => setStorePhone(e.target.value)} 
                                required 
                                disabled={isUpdating}
                                placeholder="+91 XXXX XXX XXX"
                                className={inputClasses} 
                            />
                        </div>

                        <div>
                            <label className="text-[10px] font-black uppercase text-text-muted mb-1 block">Business Email</label>
                            <input 
                                type="email" 
                                value={currentVendor.email} 
                                readOnly
                                className={`${inputClasses} bg-gray-100 cursor-not-allowed`} 
                            />
                        </div>

                        <div className="col-span-full">
                            <label className="text-[10px] font-black uppercase text-text-muted mb-1 block">Warehouse / Pickup Address (Current session only)</label>
                            <textarea 
                                value={storeAddress} 
                                onChange={(e) => setStoreAddress(e.target.value)} 
                                required 
                                disabled={isUpdating}
                                rows={3}
                                placeholder="Full pickup address for couriers..."
                                className={`${inputClasses} resize-none`} 
                            />
                            <p className="text-[8px] text-text-muted italic mt-1">* Note: Pickup address is used for manifest generation and isn't stored in basic profile.</p>
                        </div>
                    </div>

                    <div className="flex justify-end gap-4 pt-6 border-t border-border">
                        <button type="button" onClick={() => navigate('/vendor')} disabled={isUpdating} className="px-8 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest text-text-secondary hover:bg-surface transition-all">Cancel</button>
                        <button type="submit" disabled={isUpdating} className="bg-accent text-white px-10 py-3 rounded-2xl font-black uppercase tracking-widest text-xs shadow-xl shadow-accent/30 hover:-translate-y-1 active:translate-y-0 transition-all disabled:opacity-50">
                            {isUpdating ? 'Synchronizing...' : 'Save Profile Settings'}
                        </button>
                    </div>
                 </form>
            </GlassmorphicCard>
        </div>
    );
};

