import React, {
  createContext,
  useState,
  useEffect,
  ReactNode,
  useContext,
} from "react";
import { jsPDF } from "jspdf";
import { Order, OrderStatus, Address, PaymentStatus, Vendor } from "../types.ts";
import { useAuth } from "./AuthContext.tsx";
import { useNotifications } from "./NotificationContext.tsx";
import { BASE_API_URL, API_HEADERS, EDGE_FUNCTION_URL, SUPABASE_URL, SUPABASE_KEY } from "../constants.ts";

interface OrderContextType {
  orders: any[];
  isLoading: boolean;
  addOrder: (orderData: any) => Promise<string>;
  updateOrderStatus: (
    orderId: string,
    status: OrderStatus,
    details?: any
  ) => Promise<void>;
  createShipment: (orderId: string, vendorData: any) => Promise<void>;
  generateAndUploadLabel: (orderId: string, vendor: Vendor) => Promise<string>;
  generateShippingLabel: (orderId: string) => Promise<void>;
  refreshOrders: () => Promise<void>;
  getOrderById: (orderId: string) => any | undefined;
  getOrderByToken: (token: string) => any | undefined;
  updateOrderByToken: (
    token: string,
    status: OrderStatus,
    note?: string
  ) => Promise<{ success: boolean; message: string }>;
}

const OrderContext = createContext<OrderContextType | undefined>(undefined);

export const OrderProvider: React.FC<{ children: ReactNode }> = ({
  children,
}) => {
  const { user } = useAuth();
  const { sendInvoiceEmail, createAppNotification, fetchInbox } = useNotifications();
  const [orders, setOrders] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  const refreshOrders = async () => {
    if (!user) {
      setIsLoading(false);
      return;
    }

    try {
      setIsLoading(true);

      let selectString = `*,vendor:vendors!vendor_id(store_name)`;
      let filter = `order=created_at.desc`;

      if (user.role === "user") {
        filter += `&user_id=eq.${user.id}`;
      } else if (user.role === "vendor") {
        const vRes = await fetch(`${BASE_API_URL}/vendors?user_id=eq.${user.id}&select=id`, { headers: API_HEADERS });
        if (!vRes.ok) throw new Error("Vendor profile unreachable");

        const vData = await vRes.json();
        if (Array.isArray(vData) && vData.length > 0) {
            filter += `&vendor_id=eq.${vData[0].id}`;
        } else {
            setOrders([]);
            setIsLoading(false);
            return;
        }
      }

      const res = await fetch(`${BASE_API_URL}/orders?select=${selectString}&${filter}`, {
        headers: { ...API_HEADERS, "Cache-Control": "no-cache" },
      });

      if (!res.ok) {
        const errBody = await res.json().catch(() => ({}));
        if (res.status === 400) {
            const fallbackRes = await fetch(`${BASE_API_URL}/orders?select=*&${filter}`, {
                headers: { ...API_HEADERS, "Cache-Control": "no-cache" },
            });
            if (fallbackRes.ok) {
                const data = await fallbackRes.json();
                processOrders(data);
                return;
            }
        }
        throw new Error(errBody.message || res.statusText);
      }

      const data = await res.json();
      processOrders(data);

    } catch (e: any) {
      console.error("[OrderContext] Fetch sequence failed:", e.message);
    } finally {
      setIsLoading(false);
    }
  };

  const processOrders = (data: any[]) => {
    if (Array.isArray(data)) {
      setOrders(
        data.map((o: any) => ({
          ...o,
          id: o.id.toString(),
          total: Number(o.total_amount || 0),
          statusHistory: o.status_history || [],
          qrToken: o.qr_token,
          date: o.created_at,
          seller_name: o.vendor?.store_name || "VexoKart Direct",
          shippingAddress: o.shipping_address || o.shippingaddress || o.address || null,
        }))
      );
    }
  };

  useEffect(() => {
    if (user) {
        refreshOrders();
        fetchInbox(user);
    } else {
        setOrders([]);
        setIsLoading(false);
    }
  }, [user]);

  /**
   * FIXED: Shipping Label Generation & Storage Upload
   */
  const generateAndUploadLabel = async (orderId: string, vendor: Vendor): Promise<string> => {
    const order = orders.find(o => o.id === orderId);
    if (!order) throw new Error("Order not found in state.");

    console.log(`[Logistics] Initiating Label Generation for #${orderId}`);

    try {
      // 1. Prepare PDF
      const doc = new jsPDF({
        orientation: "portrait",
        unit: "mm",
        format: "a4"
      });

      const address = order.shippingAddress;
      const isCOD = order.payment_mode === 'Cash on Delivery';

      // Design
      doc.setFont("helvetica", "bold");
      doc.setFontSize(22);
      doc.text("VexoKart Logistics", 20, 25);

      doc.setFontSize(10);
      doc.setTextColor(100);
      doc.text(`Digital Consignment #${orderId}`, 20, 32);

      // Label Box
      doc.setDrawColor(0);
      doc.setLineWidth(0.5);
      doc.rect(15, 40, 180, 120);

      // Header Row
      doc.setFontSize(14);
      doc.setTextColor(0);
      doc.text(isCOD ? "CASH ON DELIVERY (COD)" : "PREPAID - ONLINE PAYMENT", 20, 50);
      doc.line(15, 55, 195, 55);

      // Addresses
      doc.setFontSize(10);
      doc.text("SHIP FROM:", 20, 65);
      doc.setFont("helvetica", "normal");
      doc.text(vendor.store_name, 20, 70);
      doc.text("Authorized Marketplace Node", 20, 75);
      doc.text(`Contact: ${vendor.phone || 'N/A'}`, 20, 80);

      doc.setFont("helvetica", "bold");
      doc.text("DELIVER TO:", 110, 65);
      doc.setFont("helvetica", "normal");
      doc.text(address.fullName, 110, 70);
      doc.text(address.street, 110, 75, { maxWidth: 75 });
      doc.text(`${address.city}, ${address.state}`, 110, 85);
      doc.text(`PIN: ${address.zip}`, 110, 90);
      doc.text(`PH: ${address.phone}`, 110, 95);

      doc.line(15, 105, 195, 105);

      // QR Code Integration
      const qrData = JSON.stringify({ id: orderId, total: order.total });
      const qrUrl = `https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=${encodeURIComponent(qrData)}`;

      try {
        const qrImgRes = await fetch(qrUrl);
        const qrBlob = await qrImgRes.blob();
        const reader = new FileReader();
        const qrBase64 = await new Promise<string>((resolve) => {
          reader.onloadend = () => resolve(reader.result as string);
          reader.readAsDataURL(qrBlob);
        });
        doc.addImage(qrBase64, 'PNG', 20, 110, 30, 30);
      } catch (e) {
        doc.text("[QR Placeholder]", 20, 125);
      }

      // Summary
      doc.setFont("helvetica", "bold");
      doc.text(`Order Total: Rs. ${order.total.toLocaleString()}`, 110, 120);
      doc.setFontSize(8);
      doc.text("Generated by VexoKart Automated Fulfillment System", 110, 128);

      // 2. Convert to Blob
      const pdfBlob = doc.output('blob');
      const filePath = `labels/${orderId}.pdf`;

      // 3. Upload to Supabase Storage
      const uploadUrl = `${SUPABASE_URL}/storage/v1/object/labels/${filePath}`;
      const uploadRes = await fetch(uploadUrl, {
        method: 'POST',
        headers: {
          'apikey': SUPABASE_KEY,
          'Authorization': `Bearer ${SUPABASE_KEY}`,
          'Content-Type': 'application/pdf',
          'x-upsert': 'true'
        },
        body: pdfBlob
      });

      if (!uploadRes.ok) {
        const err = await uploadRes.json();
        console.error("[Storage Error]", err);
        throw new Error(`Storage Upload Failed: ${err.message || uploadRes.statusText}`);
      }

      // 4. Construct Public URL
      const publicUrl = `${SUPABASE_URL}/storage/v1/object/public/labels/${filePath}`;

      // 5. Update Database
      await updateOrderStatus(orderId, 'Packed', {
        label_url: publicUrl,
        note: "Shipping label generated and stored."
      });

      return publicUrl;
    } catch (err: any) {
      console.error("[Label System] Fatal Error:", err.message);
      throw err;
    }
  };

  const addOrder = async (orderData: any): Promise<string> => {
    if (!user) throw new Error("Authentication required to place order.");

    const timestamp = new Date().toISOString();
    const qrToken = Math.random().toString(36).substring(2, 15);

    const addressSnapshot: Address = {
      id: orderData.shippingAddress?.id || Date.now().toString(),
      fullName: orderData.shippingAddress?.fullName || 'Customer',
      street: orderData.shippingAddress?.street || '',
      city: orderData.shippingAddress?.city || '',
      state: orderData.shippingAddress?.state || '',
      zip: orderData.shippingAddress?.zip || '',
      phone: orderData.shippingAddress?.phone || '',
    };

    const rawVendorId = orderData.items[0]?.vendor_id;
    let numericVendorId = null;
    if (rawVendorId && !isNaN(Number(rawVendorId))) {
      numericVendorId = Number(rawVendorId);
    }

    const payload = {
      user_id: Number(user.id),
      vendor_id: numericVendorId,
      items: orderData.items,
      total_amount: Number(orderData.total),
      payment_mode: orderData.payment_method,
      payment_status: orderData.payment_method === "Cash on Delivery" ? "cod_pending" : "paid",
      shipping_address: addressSnapshot,
      status: "Placed" as OrderStatus,
      qr_token: qrToken,
      status_history: [{
          status: "Placed" as OrderStatus,
          timestamp,
          actor: "User" as const,
          note: orderData.payment_id ? `Order placed (Ref: ${orderData.payment_id})` : "Order placed",
      }],
      created_at: timestamp,
    };

    try {
      const res = await fetch(`${BASE_API_URL}/orders`, {
        method: "POST",
        headers: { ...API_HEADERS, "Prefer": "return=representation" },
        body: JSON.stringify(payload),
      });

      if (!res.ok) {
        const errorBody = await res.json().catch(() => ({}));
        throw new Error(`Order System Error: ${errorBody.message || res.statusText}`);
      }

      const result = await res.json();
      const createdOrder = result[0];
      const finalOrderId = createdOrder.id.toString();

      await createAppNotification({
        user_id: user.id,
        role: 'user',
        title: 'Order Placed',
        message: `Your order #${finalOrderId} has been placed successfully.`,
        type: 'order_placed'
      });

      if (numericVendorId) {
          await createAppNotification({
            vendor_id: numericVendorId,
            role: 'vendor',
            title: 'New Order Received',
            message: `You received a new order #${finalOrderId}. Check dashboard for details.`,
            type: 'vendor_order_new'
          });
      }

      await createAppNotification({
        role: 'admin',
        title: 'Platform Order Received',
        message: `New order #${finalOrderId} received from ${user.name}.`,
        type: 'admin_order_new'
      });

      if (orderData.payment_method !== "Cash on Delivery") {
           await createAppNotification({
                user_id: user.id,
                role: 'user',
                title: 'Payment Successful',
                message: `Payment confirmed for Order #${finalOrderId}.`,
                type: 'payment_success'
            });
            await createAppNotification({
                role: 'admin',
                title: 'Payment Received',
                message: `Payment of ₹${orderData.total} received for Order #${finalOrderId}.`,
                type: 'admin_payment'
            });
      }

      refreshOrders();
      await fetchInbox(user);

      (async () => {
          try {
              const orderForNotify = { ...createdOrder, id: finalOrderId, total: Number(createdOrder.total_amount), shippingAddress: createdOrder.shipping_address };
              await Promise.allSettled([sendInvoiceEmail(orderForNotify, user)]);
          } catch (e) {}
      })();

      return finalOrderId;
    } catch (err: any) {
      console.error("[CRITICAL] Order Placement Failed:", err);
      throw err;
    }
  };

  const createShipment = async (orderId: string, vendor: any) => {
    const order = orders.find(o => o.id === orderId);
    if (!order) throw new Error("Order manifest not found.");

    try {
      const response = await fetch(`${EDGE_FUNCTION_URL}/create-shipment`, {
        method: 'POST',
        headers: { ...API_HEADERS, 'Authorization': `Bearer ${process.env.API_KEY || ''}` },
        body: JSON.stringify({ order_id: orderId, order_data: order, vendor_data: vendor })
      });

      if (!response.ok) {
          const errData = await response.json().catch(() => ({}));
          throw new Error(errData.message || "Shiprocket gateway unreachable.");
      }

      const logisticsData = await response.json();
      await updateOrderStatus(orderId, 'Packed', {
        note: `Shiprocket manifest created. AWB: ${logisticsData.awb_code}`,
        ...logisticsData
      });

    } catch (err: any) {
      throw err;
    }
  };

  const updateOrderStatus = async (orderId: string, status: OrderStatus, details: any = {}) => {
    const order = orders.find((o) => o.id === orderId);
    if (!order) return;

    const history = order?.statusHistory || [];
    const newHistory = [...history, {
        status,
        timestamp: new Date().toISOString(),
        actor: user?.role === "vendor" ? "Vendor" : user?.role === "admin" ? "Admin" : "System",
        note: details.note || `Order status transitioned to ${status}`,
    }];

    const trackingCode = details.awb_code || details.tracking_id;

    const updatePayload: any = { 
      status, 
      status_history: newHistory,
      ...(details.shipment_id && { shipment_id: details.shipment_id }),
      ...(trackingCode && { awb_code: trackingCode }),
      ...(details.courier_name && { courier_name: details.courier_name }),
      ...(details.label_url && { label_url: details.label_url })
    };

    try {
      const res = await fetch(`${BASE_API_URL}/orders?id=eq.${orderId}`, {
        method: "PATCH",
        headers: { ...API_HEADERS },
        body: JSON.stringify(updatePayload),
      });

      if (!res.ok) throw new Error("Status update failed");

      if (status === 'Shipped') {
          await createAppNotification({
            user_id: order.user_id,
            role: 'user',
            title: 'Order Shipped',
            message: `Your order #${orderId} has been handed over to courier.`,
            type: 'order_shipped'
          });
      } else if (status === 'Delivered') {
          await createAppNotification({
            user_id: order.user_id,
            role: 'user',
            title: 'Order Delivered',
            message: `Package #${orderId} has been successfully delivered.`,
            type: 'order_delivered'
          });
      }

      await refreshOrders();
      if (user) fetchInbox(user);
    } catch (err) { 
      console.error("Status Update Error:", err); 
    }
  };

  const generateShippingLabel = async (orderId: string) => {
    const order = orders.find(o => o.id === orderId);
    if (order?.label_url) window.open(order.label_url, '_blank');
  };

  const getOrderById = (id: string) => orders.find((o) => o.id === id);
  const getOrderByToken = (token: string) => orders.find((o) => o.qrToken === token || o.qr_token === token);

  const updateOrderByToken = async (token: string, status: OrderStatus, note?: string) => {
    const order = getOrderByToken(token);
    if (!order) return { success: false, message: "Invalid package manifest token." };
    await updateOrderStatus(order.id, status, { note });
    return { success: true, message: `Manifest updated to ${status}` };
  };

  return (
    <OrderContext.Provider
      value={{
        orders,
        isLoading,
        addOrder,
        updateOrderStatus,
        createShipment,
        generateAndUploadLabel,
        generateShippingLabel,
        refreshOrders,
        getOrderById,
        getOrderByToken,
        updateOrderByToken,
      }}
    >
      {children}
    </OrderContext.Provider>
  );
};

export const useOrders = () => {
  const context = useContext(OrderContext);
  if (!context) throw new Error("OrderContext provider missing.");
  return context;
};

import React, { useState, useEffect, useMemo } from 'react';
import { Order, OrderStatus, OrderItem } from '../../types';
import GlassmorphicCard from '../../components/GlassmorphicCard';
import { useAuth } from '../../context/AuthContext';
import { useVendors } from '../../context/VendorContext';
import { useOrders } from '../../context/OrderContext';
import ShippingDetailsModal from '../../components/admin/ShippingDetailsModal';

interface VendorAugmentedOrder extends Order {
    vendorItems: OrderItem[];
    vendorSubtotal: number;
}

const VendorOrdersPage: React.FC = () => {
    const { user } = useAuth();
    const { currentVendor, fetchCurrentVendor } = useVendors();
    const { orders, isLoading, updateOrderStatus, generateAndUploadLabel, refreshOrders } = useOrders();

    const [statusFilter, setStatusFilter] = useState<string>('all');
    const [selectedOrder, setSelectedOrder] = useState<Order | null>(null);
    const [isShippingModalOpen, setShippingModalOpen] = useState(false);
    const [isProcessingLabel, setIsProcessingLabel] = useState<string | null>(null);

    useEffect(() => {
        refreshOrders();
        if (user?.id && !currentVendor) {
            fetchCurrentVendor(user.id.toString());
        }
    }, [user, currentVendor]);

    const vendorOrders = useMemo(() => {
        if (!currentVendor) return [];

        return orders.filter(order => {
            const matchesVendorId = Number(order.vendor_id) === Number(currentVendor.id);
            const hasVendorItems = Array.isArray(order.items) && order.items.some(item => 
                Number(item.vendor_id) === Number(currentVendor.id)
            );
            return matchesVendorId || hasVendorItems;
        }).map(order => {
            const matchedItems = order.items.filter(item => 
                Number(item.vendor_id) === Number(currentVendor.id)
            );
            const vendorSubtotal = matchedItems.reduce((sum, item) => sum + (item.price * item.quantity), 0);

            return {
                ...order,
                vendorItems: matchedItems,
                vendorSubtotal: vendorSubtotal
            } as VendorAugmentedOrder;
        }).filter((o): o is VendorAugmentedOrder => {
            if (statusFilter === 'all') return true;
            if (statusFilter === 'pending') return ['Placed', 'Confirmed'].includes(o.status);
            return o.status === statusFilter;
        });
    }, [orders, currentVendor, statusFilter]);

    const handleConfirmAndGenerateLabel = async (orderId: string) => {
        if (!currentVendor) return;
        setIsProcessingLabel(orderId);
        try {
            const url = await generateAndUploadLabel(orderId, currentVendor);
            alert("Digital Label Generated & Stored Successfully!");
        } catch (err: any) {
            alert(`Logistics Error: ${err.message}`);
        } finally {
            setIsProcessingLabel(null);
        }
    };

    const handleStatusChange = (order: Order, status: OrderStatus) => {
        if (status === 'Shipped') {
            setSelectedOrder(order);
            setShippingModalOpen(true);
        } else {
            updateOrderStatus(order.id, status);
        }
    };

    const handleShippingSubmit = (courierName: string, trackingId: string) => {
        if (selectedOrder) {
            updateOrderStatus(selectedOrder.id, 'Shipped', { courier_name: courierName, tracking_id: trackingId });
        }
        setShippingModalOpen(false);
        setSelectedOrder(null);
    };

    if (isLoading && vendorOrders.length === 0) {
        return (
            <div className="flex flex-col items-center justify-center p-20">
                <div className="w-10 h-10 border-4 border-accent border-t-transparent rounded-full animate-spin"></div>
                <p className="mt-4 text-text-muted font-black uppercase tracking-widest text-[10px]">Loading orders...</p>
            </div>
        );
    }

    return (
        <div className="space-y-6">
            {isShippingModalOpen && (
                <ShippingDetailsModal
                    onClose={() => setShippingModalOpen(false)}
                    onSubmit={handleShippingSubmit}
                />
            )}

            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                <div>
                  <h1 className="text-3xl font-black text-text-main italic tracking-tight uppercase">Vendor Orders</h1>
                  <p className="text-text-muted mt-1 text-sm">Automated fulfillment workflow.</p>
                </div>

                <div className="flex bg-surface p-1 rounded-xl border border-border">
                    {['all', 'pending', 'Packed', 'Shipped', 'Delivered'].map(f => (
                        <button
                            key={f}
                            onClick={() => setStatusFilter(f)}
                            className={`px-4 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${statusFilter === f ? 'bg-accent text-white shadow-lg' : 'text-text-muted hover:text-text-secondary'}`}
                        >
                            {f}
                        </button>
                    ))}
                </div>
            </div>

            <GlassmorphicCard>
                <div className="overflow-x-auto">
                    <table className="w-full text-left text-sm">
                        <thead>
                            <tr className="border-b border-white/5 text-text-muted text-[10px] uppercase font-black tracking-widest">
                                <th className="p-6">Order Info</th>
                                <th className="p-6">Logistics</th>
                                <th className="p-6">Revenue</th>
                                <th className="p-6">Status</th>
                                <th className="p-6 text-right">Fulfillment</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-white/5">
                            {vendorOrders.map(order => (
                                <tr key={order.id} className="hover:bg-white/[0.02] transition-colors">
                                    <td className="p-6">
                                        <p className="text-text-main font-mono font-bold">#{order.id}</p>
                                        <p className="text-[10px] text-text-muted font-bold mt-1 uppercase">{order.shipping_address?.fullName || 'Customer'}</p>
                                    </td>
                                    <td className="p-6">
                                        {order.label_url ? (
                                            <div>
                                                <span className="px-2 py-0.5 bg-green-50 text-green-600 rounded text-[8px] font-black uppercase border border-green-100">Label Active</span>
                                                <p className="text-[9px] text-text-muted font-bold uppercase mt-1">{order.courier_name || 'Pickup Scheduled'}</p>
                                            </div>
                                        ) : (
                                            <span className="text-[9px] text-text-muted italic uppercase font-bold">Pending Label</span>
                                        )}
                                    </td>
                                    <td className="p-6">
                                        <span className="text-text-main font-black text-sm">₹{order.vendorSubtotal.toLocaleString()}</span>
                                    </td>
                                    <td className="p-6">
                                        <span className={`text-[10px] font-black uppercase px-2 py-1 rounded-md border ${
                                            order.status === 'Delivered' ? 'text-green-500 border-green-500/20 bg-green-500/5' : 
                                            order.status === 'Cancelled' ? 'text-red-500 border-red-500/20 bg-red-500/5' : 
                                            'text-blue-400 border-blue-400/20 bg-blue-400/5'
                                        }`}>
                                            {order.status}
                                        </span>
                                    </td>
                                    <td className="p-6 text-right space-x-2 whitespace-nowrap">
                                        {order.status === 'Placed' && (
                                            <button onClick={() => handleStatusChange(order, 'Confirmed')} className="bg-accent text-white px-4 py-2 rounded-xl text-[10px] font-black uppercase shadow-lg shadow-accent/20 transition-all hover:scale-105 active:scale-95">Confirm Order</button>
                                        )}
                                        {order.status === 'Confirmed' && !order.label_url && (
                                            <button 
                                                onClick={() => handleConfirmAndGenerateLabel(order.id)} 
                                                disabled={isProcessingLabel === order.id}
                                                className="bg-indigo-600 text-white px-4 py-2 rounded-xl text-[10px] font-black uppercase shadow-lg shadow-indigo-600/20 disabled:opacity-50 transition-all hover:scale-105"
                                            >
                                                {isProcessingLabel === order.id ? 'Storing Label...' : 'Generate Label'}
                                            </button>
                                        )}
                                        {order.label_url && (
                                            <a 
                                                href={order.label_url}
                                                target="_blank"
                                                rel="noopener noreferrer"
                                                className="bg-surface border border-border text-text-main px-4 py-2 rounded-xl text-[10px] font-black uppercase hover:bg-white transition-all shadow-sm inline-flex items-center gap-2"
                                            >
                                                <svg className="w-3.5 h-3.5 text-accent" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 10v6m0 0l-3-3m3 3l3-3m2 8H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" /></svg>
                                                Download Label
                                            </a>
                                        )}
                                        {order.status === 'Packed' && (
                                            <button onClick={() => handleStatusChange(order, 'Shipped')} className="bg-blue-600 text-white px-4 py-2 rounded-xl text-[10px] font-black uppercase shadow-lg shadow-blue-600/20 transition-all hover:scale-105">Mark Shipped</button>
                                        )}
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                    {vendorOrders.length === 0 && !isLoading && (
                        <div className="p-20 text-center text-text-muted italic">
                            No storefront records found.
                        </div>
                    )}
                </div>
            </GlassmorphicCard>
        </div>
    );
};

export default VendorOrdersPage;

import React, { createContext, useState, useEffect, ReactNode, useContext } from 'react';
import { Vendor } from '../types';
import { BASE_API_URL, API_HEADERS } from '../constants';

interface VendorContextType {
  vendors: Vendor[];
  currentVendor: Vendor | null;
  isVendorLoading: boolean;
  vendorError: string | null;
  addVendorRecord: (vendorData: Omit<Vendor, 'id' | 'created_at'>) => Promise<void>;
  updateVendorStatus: (vendorId: number, status: Vendor['status'], reason?: string) => Promise<void>;
  updateVendorProfile: (vendorId: number, updates: Partial<Vendor>) => Promise<void>;
  getVendorByUserId: (userId: string) => Vendor | undefined;
  getVendorById: (vendorId: string) => Vendor | undefined;
  getVendorByEmailDirect: (email: string) => Promise<Vendor | null>;
  fetchCurrentVendor: (userId: string, force?: boolean) => Promise<void>;
  refreshVendors: () => Promise<void>;
}

export const VendorContext = createContext<VendorContextType | undefined>(undefined);

const VENDOR_COLUMNS = 'id,user_id,store_name,profile_image,status,email,phone,owner_name,created_at,rejection_reason';

export const VendorProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [vendors, setVendors] = useState<Vendor[]>([]);
  const [currentVendor, setCurrentVendor] = useState<Vendor | null>(() => {
    const cached = sessionStorage.getItem('vxk_vendor_cache');
    return cached ? JSON.parse(cached) : null;
  });
  const [isVendorLoading, setIsVendorLoading] = useState(false);
  const [vendorError, setVendorError] = useState<string | null>(null);

  const fetchVendors = async () => {
    try {
      const res = await fetch(`${BASE_API_URL}/vendors?select=${VENDOR_COLUMNS}&order=created_at.desc`, { 
        headers: { ...API_HEADERS, 'Cache-Control': 'no-cache' } 
      });
      if (!res.ok) throw new Error("Failed to fetch vendors list");
      const data = await res.json();
      if (Array.isArray(data)) setVendors(data);
    } catch (error) {
      console.error("[VendorSync] List Error:", error);
    }
  };

  const fetchCurrentVendor = async (userId: string, force = false) => {
    if (!userId) return;

    // Use cache unless forced
    if (currentVendor && String(currentVendor.user_id) === String(userId) && !force) {
      return;
    }

    setIsVendorLoading(true);
    setVendorError(null);

    try {
      // CRITICAL FIX: Fetch profile using user_id bigint filter
      const res = await fetch(`${BASE_API_URL}/vendors?user_id=eq.${userId}&select=${VENDOR_COLUMNS}`, {
        headers: { ...API_HEADERS, 'Cache-Control': 'no-cache' }
      });

      if (!res.ok) {
        const err = await res.json().catch(() => ({}));
        throw new Error(err.message || "Connection to vendor service failed.");
      }

      const data = await res.json();
      if (Array.isArray(data) && data.length > 0) {
        const profile = data[0];
        setCurrentVendor(profile);
        sessionStorage.setItem('vxk_vendor_cache', JSON.stringify(profile));
      } else {
        setCurrentVendor(null);
        setVendorError("Vendor profile not found. Access denied.");
        sessionStorage.removeItem('vxk_vendor_cache');
      }
    } catch (error: any) {
      console.error("[VendorSync] Profile Fetch Error:", error);
      setVendorError(error.message || "Failed to sync vendor profile.");
    } finally {
      setIsVendorLoading(false);
    }
  };

  useEffect(() => {
    fetchVendors();
  }, []);

  const updateVendorProfile = async (id: number, updates: Partial<Vendor>) => {
    const { id: _, created_at: __, user_id: ___, store_address, ...dbUpdates } = updates as any;

    try {
      const res = await fetch(`${BASE_API_URL}/vendors?id=eq.${id}`, {
        method: 'PATCH',
        headers: { ...API_HEADERS, 'Prefer': 'return=representation' },
        body: JSON.stringify(dbUpdates)
      });

      if (!res.ok) {
        const err = await res.json().catch(() => ({}));
        throw new Error(err.message || 'Update failed');
      }

      if (currentVendor && currentVendor.id === id) {
        const updated = { ...currentVendor, ...updates };
        setCurrentVendor(updated);
        sessionStorage.setItem('vxk_vendor_cache', JSON.stringify(updated));
      }
      await fetchVendors();
    } catch (err: any) {
      console.error("[VendorSync] Update Error:", err);
      throw err;
    }
  };

  const addVendorRecord = async (data: Omit<Vendor, 'id' | 'created_at'>) => {
    try {
      const res = await fetch(`${BASE_API_URL}/vendors`, {
        method: 'POST',
        headers: { ...API_HEADERS, 'Prefer': 'return=minimal' },
        body: JSON.stringify({ ...data, created_at: new Date().toISOString() })
      });
      if (!res.ok) throw new Error('Record creation failed');
      await fetchVendors();
    } catch (err) {
      console.error("[VendorSync] Create Error:", err);
      throw err;
    }
  };

  const updateVendorStatus = async (id: number, status: Vendor['status'], reason?: string) => {
    try {
      await fetch(`${BASE_API_URL}/vendors?id=eq.${id}`, {
        method: 'PATCH',
        headers: API_HEADERS,
        body: JSON.stringify({ status, rejection_reason: reason })
      });
      await fetchVendors();
    } catch (err) {
      console.error("[VendorSync] Status Error:", err);
    }
  };

  const getVendorByEmailDirect = async (email: string): Promise<Vendor | null> => {
    try {
      const res = await fetch(`${BASE_API_URL}/vendors?select=${VENDOR_COLUMNS}&email=ilike.${encodeURIComponent(email)}&status=eq.approved`, {
        headers: API_HEADERS
      });
      const data = await res.json();
      return (Array.isArray(data) && data.length > 0) ? data[0] : null;
    } catch (e) { return null; }
  };

  const getVendorByUserId = (uid: string) => vendors.find(v => String(v.user_id) === String(uid));
  const getVendorById = (id: string) => vendors.find(v => String(v.id) === String(id));

  return (
    <VendorContext.Provider value={{ 
      vendors, currentVendor, isVendorLoading, vendorError,
      addVendorRecord, updateVendorStatus, updateVendorProfile,
      getVendorByUserId, getVendorById, getVendorByEmailDirect,
      fetchCurrentVendor, refreshVendors: fetchVendors 
    }}>
      {children}
    </VendorContext.Provider>
  );
};

export const useVendors = () => {
  const context = useContext(VendorContext);
  if (!context) throw new Error('useVendors missing');
  return context;
};

