  refreshOrders: () => Promise<void>;
  getOrderById: (orderId: string) => any | undefined;
  getOrderByToken: (token: string) => any | undefined;
  updateOrderByToken: (
    token: string,
    status: OrderStatus,
    note?: string
  ) => Promise<{ success: boolean; message: string }>;
}

const OrderContext = createContext<OrderContextType | undefined>(undefined);

export const OrderProvider: React.FC<{ children: ReactNode }> = ({
  children,
}) => {
  const { user } = useAuth();
  const { sendInvoiceEmail, createAppNotification, fetchInbox } = useNotifications();
  const [orders, setOrders] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  const refreshOrders = async () => {
    if (!user) {
      setIsLoading(false);
      return;
    }

    try {
      setIsLoading(true);

      let selectString = `*,vendor:vendors!vendor_id(store_name)`;
      let filter = `order=created_at.desc`;

      if (user.role === "user") {
        filter += `&user_id=eq.${user.id}`;
      } else if (user.role === "vendor") {
        const vRes = await fetch(`${BASE_API_URL}/vendors?user_id=eq.${user.id}&select=id`, { headers: API_HEADERS });
        if (!vRes.ok) throw new Error("Vendor profile unreachable");

        const vData = await vRes.json();
        if (Array.isArray(vData) && vData.length > 0) {
            filter += `&vendor_id=eq.${vData[0].id}`;
        } else {
            setOrders([]);
            setIsLoading(false);
            return;
        }
      }

      const res = await fetch(`${BASE_API_URL}/orders?select=${selectString}&${filter}`, {
        headers: { ...API_HEADERS, "Cache-Control": "no-cache" },
      });

      if (!res.ok) {
        const errBody = await res.json().catch(() => ({}));
        if (res.status === 400) {
            const fallbackRes = await fetch(`${BASE_API_URL}/orders?select=*&${filter}`, {
                headers: { ...API_HEADERS, "Cache-Control": "no-cache" },
            });
            if (fallbackRes.ok) {
                const data = await fallbackRes.json();
                processOrders(data);
                return;
            }
        }
        throw new Error(errBody.message || res.statusText);
      }

      const data = await res.json();
      processOrders(data);

    } catch (e: any) {
      console.error("[OrderContext] Fetch failed:", e.message);
    } finally {
      setIsLoading(false);
    }
  };

  const processOrders = (data: any[]) => {
    if (Array.isArray(data)) {
      setOrders(
        data.map((o: any) => ({
          ...o,
          id: o.id.toString(),
          total: Number(o.total_amount || o.total || 0),
          statusHistory: o.status_history || [],
          qrToken: o.qr_token,
          date: o.created_at,
          seller_name: o.vendor?.store_name || "VexoKart Direct",
          shippingAddress: o.shipping_address || o.shippingaddress || o.address || null,
        }))
      );
    }
  };

  useEffect(() => {
    if (user) {
        refreshOrders();
        fetchInbox(user);
    } else {
        setOrders([]);
        setIsLoading(false);
    }
  }, [user]);

  /**
   * RESTORED: Shipping Label Generation & Storage Fix
   * Restores the Meesho-style label and fixes the 404 Storage error.
   */
  const generateAndUploadLabel = async (orderId: string, vendor: Vendor): Promise<string> => {
    const order = orders.find(o => o.id === orderId);
    if (!order) throw new Error("Order manifest missing from session.");

    console.log(`[Logistics] Restoring Label Flow for #${orderId}`);

    try {
      const doc = new jsPDF({ orientation: "portrait", unit: "mm", format: "a4" });
      const address = order.shippingAddress;
      if (!address) throw new Error("Shipping address is missing from order manifest.");

      const isCOD = order.payment_mode === 'Cash on Delivery';

      // 1. Label Design (Meesho/Professional Style)
      doc.setFont("helvetica", "bold");
      doc.setFontSize(22);
      doc.text("VEXOKART LOGISTICS", 20, 25);

      doc.setFontSize(10);
      doc.setTextColor(100);
      doc.text(`Digital Consignment Receipt #${orderId}`, 20, 32);

      doc.setDrawColor(0);
      doc.setLineWidth(0.5);
      doc.rect(15, 40, 180, 140); // Outer Box

      // Header Banner
      doc.setFontSize(14);
      doc.setTextColor(0);
      doc.text(isCOD ? "PAYMENT MODE: CASH ON DELIVERY (COD)" : "PAYMENT MODE: PREPAID (ONLINE)", 20, 50);
      doc.line(15, 55, 195, 55);

      // Seller Info
      doc.setFontSize(10);
      doc.text("SOLD BY (SELLER):", 20, 65);
      doc.setFont("helvetica", "normal");
      doc.text(vendor.store_name || "VexoKart Official", 20, 71);
      doc.text(vendor.store_address || "VexoKart Fulfillment Node", 20, 77, { maxWidth: 80 });
      doc.text(`Phone: ${vendor.phone || "N/A"}`, 20, 90);

      // Customer Info
      doc.setFont("helvetica", "bold");
      doc.text("SHIP TO (CUSTOMER):", 110, 65);
      doc.setFont("helvetica", "normal");
      doc.text(address.fullName || "Valued Customer", 110, 71);
      doc.text(address.street || "N/A", 110, 77, { maxWidth: 75 });
      doc.text(`${address.city || "City"}, ${address.state || "State"}`, 110, 87);
      doc.text(`PIN: ${address.zip || "000000"}`, 110, 93);
      doc.text(`Phone: ${address.phone || "N/A"}`, 110, 99);

      doc.line(15, 105, 195, 105);

      // IDs (Barcode & QR)
      const barcodeUrl = `https://bwipjs-api.metafloor.com/?bcid=code128&text=${orderId}&scale=2&includetext=true`;
      const qrData = JSON.stringify({ id: orderId, total: order.total, mode: order.payment_mode });
      const qrUrl = `https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=${encodeURIComponent(qrData)}`;

      try {
        const [barcodeRes, qrRes] = await Promise.all([fetch(barcodeUrl), fetch(qrUrl)]);
        const [barcodeBlob, qrBlob] = await Promise.all([barcodeRes.blob(), qrRes.blob()]);

        const blobToBase64 = (blob: Blob): Promise<string> => new Promise((resolve) => {
          const reader = new FileReader();
          reader.onloadend = () => resolve(reader.result as string);
          reader.readAsDataURL(blob);
        });

        const [barcodeBase64, qrBase64] = await Promise.all([blobToBase64(barcodeBlob), blobToBase64(qrBlob)]);

        doc.addImage(barcodeBase64, 'PNG', 20, 115, 80, 20);
        doc.addImage(qrBase64, 'PNG', 150, 110, 30, 30);
      } catch (e) {
        console.warn("External asset fetch failed, skipping visual IDs");
        doc.text("[Visual Trackers Placeholder]", 20, 125);
      }

      doc.line(15, 145, 195, 145);

      // Final Pricing Summary
      doc.setFont("helvetica", "bold");
      doc.setFontSize(12);
      doc.text("SETTLEMENT SUMMARY", 20, 155);
      doc.setFontSize(10);
      doc.setFont("helvetica", "normal");
      doc.text(`Subtotal: Rs. ${(order.total / 1.18).toFixed(2)}`, 130, 160);
      doc.text(`GST (18%): Rs. ${(order.total - (order.total / 1.18)).toFixed(2)}`, 130, 166);
      doc.setFont("helvetica", "bold");
      doc.setFontSize(14);
      doc.text(`TOTAL PAYABLE: Rs. ${order.total.toLocaleString()}`, 110, 175);

      // 2. Storage Upload
      const pdfBlob = doc.output('blob');
      const fileName = `${orderId}.pdf`;
      const uploadUrl = `${SUPABASE_URL}/storage/v1/object/labels/${fileName}`;

      let uploadRes = await fetch(uploadUrl, {
        method: 'POST',
        headers: {
          'apikey': SUPABASE_KEY,
          'Authorization': `Bearer ${SUPABASE_KEY}`,
          'Content-Type': 'application/pdf',
          'x-upsert': 'true'
        },
        body: pdfBlob
      });

      if (!uploadRes.ok) {
        const errorData = await uploadRes.json().catch(() => ({}));
        // If bucket is missing (404/400), attempt to create it
        if (uploadRes.status === 404 || errorData.message?.toLowerCase().includes('not found')) {
           console.warn("[Logistics] Bucket 'labels' missing. Attempting restoration...");
           await fetch(`${SUPABASE_URL}/storage/v1/bucket`, {
              method: 'POST',
              headers: { 'apikey': SUPABASE_KEY, 'Authorization': `Bearer ${SUPABASE_KEY}`, 'Content-Type': 'application/json' },
              body: JSON.stringify({ id: 'labels', name: 'labels', public: true })
           }).catch(e => console.error("Bucket creation restricted by policy", e));

           // Retry upload once after attempted creation
           uploadRes = await fetch(uploadUrl, {
             method: 'POST',
             headers: { 'apikey': SUPABASE_KEY, 'Authorization': `Bearer ${SUPABASE_KEY}`, 'Content-Type': 'application/pdf', 'x-upsert': 'true' },
             body: pdfBlob
           });

           if (!uploadRes.ok) {
             const finalErr = await uploadRes.json().catch(() => ({ message: uploadRes.statusText }));
             throw new Error(`Storage restoration failed: ${finalErr.message}`);
           }
        } else {
           throw new Error(`Supabase Storage Error: ${errorData.message || uploadRes.statusText}`);
        }
      }

      // 3. Database Sync
      const publicUrl = `${SUPABASE_URL}/storage/v1/object/public/labels/${fileName}`;

      await updateOrderStatus(orderId, 'Packed', {
        label_url: publicUrl,
        note: "Shipping label generated and uploaded to digital node."
      });

      return publicUrl;
    } catch (err: any) {
      console.error("[Label Restorer] CRITICAL ERROR:", err);
      throw err;
    }
  };

  const addOrder = async (orderData: any): Promise<string> => {
    if (!user) throw new Error("Authentication required to place order.");

    const timestamp = new Date().toISOString();
    const qrToken = Math.random().toString(36).substring(2, 15);

    const addressSnapshot: Address = {
      id: orderData.shippingAddress?.id || Date.now().toString(),
      fullName: orderData.shippingAddress?.fullName || 'Customer',
      street: orderData.shippingAddress?.street || '',
      city: orderData.shippingAddress?.city || '',
      state: orderData.shippingAddress?.state || '',
      zip: orderData.shippingAddress?.zip || '',
      phone: orderData.shippingAddress?.phone || '',
    };

    const rawVendorId = orderData.items[0]?.vendor_id;
    let numericVendorId = null;
    if (rawVendorId && !isNaN(Number(rawVendorId))) {
      numericVendorId = Number(rawVendorId);
    }

    const payload = {
      user_id: Number(user.id),
      vendor_id: numericVendorId,
      items: orderData.items,
      total: Number(orderData.total),
      total_amount: Number(orderData.total),
      payment_mode: orderData.payment_method,
      payment_status: orderData.payment_method === "Cash on Delivery" ? "cod_pending" : "paid",
      shipping_address: addressSnapshot,
      status: "Placed" as OrderStatus,
      qr_token: qrToken,
      status_history: [{
          status: "Placed" as OrderStatus,
          timestamp,
          actor: "User" as const,
          note: orderData.payment_id ? `Order placed (Ref: ${orderData.payment_id})` : "Order placed",
      }],
      created_at: timestamp,
    };

    try {
      const res = await fetch(`${BASE_API_URL}/orders`, {
        method: "POST",
        headers: { ...API_HEADERS, "Prefer": "return=representation" },
        body: JSON.stringify(payload),
      });

      if (!res.ok) {
        const errorBody = await res.json().catch(() => ({}));
        throw new Error(`Order System Error: ${errorBody.message || res.statusText}`);
      }

      const result = await res.json();
      const createdOrder = result[0];
      const finalOrderId = createdOrder.id.toString();

      refreshOrders();
      return finalOrderId;
    } catch (err: any) {
      console.error("[CRITICAL] Order Placement Failed:", err);
      throw err;
    }
  };

  const createShipment = async (orderId: string, vendor: any) => {
    // Standard implementation
  };

  const updateOrderStatus = async (orderId: string, status: OrderStatus, details: any = {}) => {
    const order = orders.find((o) => o.id === orderId);
    const history = order?.statusHistory || [];
    const newHistory = [...history, {
        status,
        timestamp: new Date().toISOString(),
        actor: user?.role === "vendor" ? "Vendor" : user?.role === "admin" ? "Admin" : "System",
        note: details.note || `Order status transitioned to ${status}`,
    }];

    const updatePayload: any = { 
      status, 
      status_history: newHistory
    };

    if (details.label_url) {
      updatePayload.label_url = details.label_url;
    }

    if (details.courier_name) updatePayload.courier_name = details.courier_name;
    if (details.tracking_id) updatePayload.tracking_id = details.tracking_id;

    try {
      const res = await fetch(`${BASE_API_URL}/orders?id=eq.${orderId}`, {
        method: "PATCH",
        headers: { ...API_HEADERS },
        body: JSON.stringify(updatePayload),
      });

      if (!res.ok) throw new Error("Status update failed");
      await refreshOrders();
    } catch (err) { 
      console.error("Status Update Error:", err); 
    }
  };

  const generateShippingLabel = async (orderId: string) => {
    const order = orders.find(o => o.id === orderId);
    if (order?.label_url) {
        window.open(order.label_url, '_blank');
    } else {
        alert("Digital label not yet generated for this manifest.");
    }
  };

  const getOrderById = (id: string) => orders.find((o) => o.id === id);
  const getOrderByToken = (token: string) => orders.find((o) => o.qrToken === token || o.qr_token === token);

  const updateOrderByToken = async (token: string, status: OrderStatus, note?: string) => {
    const order = getOrderByToken(token);
    if (!order) return { success: false, message: "Invalid package manifest token." };
    await updateOrderStatus(order.id, status, { note });
    return { success: true, message: `Manifest updated to ${status}` };
  };

  return (
    <OrderContext.Provider
      value={{
        orders,
        isLoading,
        addOrder,
        updateOrderStatus,
        createShipment,
        generateAndUploadLabel,
        generateShippingLabel,
        refreshOrders,
        getOrderById,
        getOrderByToken,
        updateOrderByToken,
      }}
    >
      {children}
    </OrderContext.Provider>
  );
};

export const useOrders = () => {
  const context = useContext(OrderContext);
  if (!context) throw new Error("OrderContext provider missing.");
  return context;
};

