  const order = localOrder || getOrderById(orderId || "");

  useEffect(() => {
    const fetchOrderDirectly = async () => {
        if (!orderId) return;

        // If not in context (common when opened in a new tab), fetch from API directly
        if (!order) {
            try {
                const res = await fetch(`${BASE_API_URL}/orders?id=eq.${orderId}&select=*,vendor:vendors!vendor_id(*)`, {
