import { jsPDF } from 'jspdf';
import { Order } from '../types';

/**
 * Generates a high-fidelity, black-and-white logistics manifest PDF locally.
 * This ensures the app remains functional even if the Supabase Edge Function is unreachable.
 */
export const generateLocalPDFBase64 = async (order: Order): Promise<string> => {
  const doc = new jsPDF({
    orientation: 'portrait',
    unit: 'mm',
    format: 'a4',
  });

  const address = order.shippingAddress || order.shipping_address;
  const isCOD = order.payment_mode === 'Cash on Delivery';
  const subtotal = order.total / 1.18;
  const gst = order.total - subtotal;

  // Header
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(22);
  doc.text('VEXOKART LOGISTICS', 20, 20);

  doc.setFontSize(8);
  doc.setFont('helvetica', 'normal');
  doc.text('AUTHORIZED DIGITAL FULFILLMENT NODE • V.5.0', 20, 25);

  // Payment Type Badge
  doc.setFillColor(0, 0, 0);
  doc.rect(150, 12, 40, 12, 'F');
  doc.setTextColor(255, 255, 255);
  doc.setFontSize(14);
  doc.setFont('helvetica', 'bold');
  doc.text(isCOD ? 'COD' : 'PREPAID', 170, 20, { align: 'center' });

  // Order ID
  doc.setTextColor(0, 0, 0);
  doc.setFontSize(10);
  doc.text(`MANIFEST #${order.id}`, 190, 28, { align: 'right' });

  // Divider
  doc.setLineWidth(0.5);
  doc.line(20, 32, 190, 32);

  // Address Grid
  doc.setFontSize(8);
  doc.setTextColor(100, 100, 100);
  doc.text('SOLD BY (SELLER NODE)', 20, 40);
  doc.text('SHIP TO (CONSIGNEE)', 110, 40);

  doc.setTextColor(0, 0, 0);
  doc.setFontSize(11);
  doc.setFont('helvetica', 'bold');
  doc.text(order.seller_name || 'VexoKart Official Store', 20, 46);
  doc.text(address?.fullName || 'Verified Buyer', 110, 46);

  doc.setFontSize(9);
  doc.setFont('helvetica', 'normal');
  doc.text(['Fulfillment Node-A1', 'VexoKart Logistics Park', 'Ph: 1800-VEXO-KART'], 20, 52);

  const customerAddr = [
    address?.street || '',
    `${address?.city || ''}, ${address?.state || ''}`,
    `PIN: ${address?.zip || ''}`,
    `Phone: ${address?.phone || ''}`
  ];
  doc.text(customerAddr, 110, 52);

  // Middle Divider
  doc.line(20, 75, 190, 75);

  // Tracking Visuals Placeholder
  doc.setFontSize(7);
  doc.setTextColor(150, 150, 150);
  doc.rect(20, 80, 120, 20);
  doc.text('INTERNAL_BARCODE_NODE_ID_' + order.id, 80, 92, { align: 'center' });

  doc.rect(155, 80, 25, 25);
  doc.text('QR_NODE', 167.5, 94, { align: 'center' });

  // Item Table
  doc.setTextColor(0, 0, 0);
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(9);
  doc.text('ITEM MANIFEST DESCRIPTION', 20, 115);
  doc.text('QTY', 150, 115, { align: 'center' });
  doc.text('PRICE', 180, 115, { align: 'right' });
  doc.line(20, 117, 190, 117);

  doc.setFont('helvetica', 'normal');
  let y = 125;
  order.items.forEach((item) => {
    doc.text(item.name.substring(0, 50), 20, y);
    doc.text(String(item.quantity), 150, y, { align: 'center' });
    doc.text(`INR ${item.price.toLocaleString()}`, 180, y, { align: 'right' });
    y += 8;
  });

  // Totals
  doc.line(130, y + 5, 190, y + 5);
  y += 12;
  doc.setFontSize(8);
  doc.text('SUBTOTAL', 130, y);
  doc.text(`INR ${subtotal.toFixed(2)}`, 180, y, { align: 'right' });

  y += 6;
  doc.text('GST (18%)', 130, y);
  doc.text(`INR ${gst.toFixed(2)}`, 180, y, { align: 'right' });

  y += 10;
  doc.setFontSize(14);
  doc.setFont('helvetica', 'bold');
  doc.text('TOTAL PAYABLE', 130, y);
  doc.text(`INR ${order.total.toLocaleString()}`, 180, y, { align: 'right' });

  // Footer
  doc.setFontSize(7);
  doc.setFont('helvetica', 'normal');
  doc.setTextColor(150, 150, 150);
  doc.text('ELECTRONIC CONSIGNMENT NOTE • GENERATED BY VEXOKART PROTOCOL V.5.0', 105, 280, { align: 'center' });

  const pdfOutput = doc.output('blob');
  return new Promise((resolve) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      const base64String = (reader.result as string).split(',')[1];
      resolve(base64String);
    };
    reader.readAsDataURL(pdfOutput);
  });
};

import React, {
  createContext,
  useState,
  useEffect,
  ReactNode,
  useContext,
} from "react";
import { Order, OrderStatus, Address, PaymentStatus, Vendor } from "../types.ts";
import { useAuth } from "./AuthContext.tsx";
import { useNotifications } from "./NotificationContext.tsx";
import { BASE_API_URL, API_HEADERS, EDGE_FUNCTION_URL } from "../constants.ts";

interface OrderContextType {
  orders: any[];
  isLoading: boolean;
  isLabelGenerating: boolean;
  activeLabelUrl: string | null;
  addOrder: (orderData: any) => Promise<string>;
  updateOrderStatus: (
    orderId: string,
    status: OrderStatus,
    details?: any
  ) => Promise<void>;
  createShipment: (orderId: string, vendorData: any) => Promise<void>;
  generateShippingLabel: (orderId: string) => Promise<void>;
  closeLabelPreview: () => void;
  refreshOrders: () => Promise<void>;
  getOrderById: (orderId: string) => any | undefined;
  getOrderByToken: (token: string) => any | undefined;
  updateOrderByToken: (
    token: string,
    status: OrderStatus,
    note?: string
  ) => Promise<{ success: boolean; message: string }>;
}

const OrderContext = createContext<OrderContextType | undefined>(undefined);

export const OrderProvider: React.FC<{ children: ReactNode }> = ({
  children,
}) => {
  const { user } = useAuth();
  const { fetchInbox } = useNotifications();
  const [orders, setOrders] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  // SECURE PREVIEW STATE
  const [isLabelGenerating, setIsLabelGenerating] = useState(false);
  const [activeLabelUrl, setActiveLabelUrl] = useState<string | null>(null);

  const refreshOrders = async () => {
    if (!user) {
      setIsLoading(false);
      return;
    }

    try {
      setIsLoading(true);
      let selectString = `*,vendor:vendors!vendor_id(*)`;
      let filter = `order=created_at.desc`;

      if (user.role === "user") {
        filter += `&user_id=eq.${user.id}`;
      } else if (user.role === "vendor") {
        const vRes = await fetch(`${BASE_API_URL}/vendors?user_id=eq.${user.id}&select=id`, { headers: API_HEADERS });
        if (!vRes.ok) throw new Error("Vendor profile unreachable");
        const vData = await vRes.json();
        if (Array.isArray(vData) && vData.length > 0) {
            filter += `&vendor_id=eq.${vData[0].id}`;
        } else {
            setOrders([]);
            setIsLoading(false);
            return;
        }
      }

      const res = await fetch(`${BASE_API_URL}/orders?select=${selectString}&${filter}`, {
        headers: { ...API_HEADERS, "Cache-Control": "no-cache" },
      });

      if (!res.ok) {
        const fallbackRes = await fetch(`${BASE_API_URL}/orders?select=*&${filter}`, {
            headers: { ...API_HEADERS, "Cache-Control": "no-cache" },
        });
        if (fallbackRes.ok) {
            const data = await fallbackRes.json();
            processOrders(data);
            return;
        }
        throw new Error("Order fetch failed");
      }

      const data = await res.json();
      processOrders(data);
    } catch (e: any) {
      console.error("[OrderContext] Fetch failed:", e.message);
    } finally {
      setIsLoading(false);
    }
  };

  const processOrders = (data: any[]) => {
    if (Array.isArray(data)) {
      setOrders(
        data.map((o: any) => ({
          ...o,
          id: o.id.toString(),
          total: Number(o.total_amount || o.total || 0),
          statusHistory: o.status_history || [],
          qrToken: o.qr_token,
          date: o.created_at,
          seller_name: o.vendor?.store_name || "VexoKart Direct",
          shippingAddress: o.shipping_address || o.shippingaddress || o.address || null,
        }))
      );
    }
  };

  useEffect(() => {
    if (user) {
        refreshOrders();
        fetchInbox(user);
    } else {
        setOrders([]);
        setIsLoading(false);
    }
  }, [user]);

  /**
   * SECURE IN-APP LABEL GENERATION
   * Robust implementation: Tries Edge Function first, falls back to local generation if connectivity fails.
   */
  const generateShippingLabel = async (orderId: string) => {
    if (isLabelGenerating) return;

    setIsLabelGenerating(true);
    let pdfBase64 = null;

    try {
        // Attempt to fetch from Edge Function
        try {
          const response = await fetch(`${EDGE_FUNCTION_URL}/generate-shipping-label`, {
              method: 'POST',
              headers: {
                  ...API_HEADERS,
                  'X-Client-Role': user?.role || 'unknown'
              },
              body: JSON.stringify({ orderId })
          });

          if (response.ok) {
              const result = await response.json();
              if (result.success && result.labelBase64) {
                  pdfBase64 = result.labelBase64;
              }
          }
        } catch (fetchErr) {
          console.warn("[Manifest Sync] Edge Node unreachable. Triggering local manifest protocol.", fetchErr);
        }

        // FAIL-SAFE: Generate locally if server fails (fixes 'Failed to fetch')
        if (!pdfBase64) {
            const order = orders.find(o => o.id === orderId);
            if (!order) throw new Error("Order manifest context missing from local store.");

            const { generateLocalPDFBase64 } = await import('../utils/pdfGenerator.ts');
            pdfBase64 = await generateLocalPDFBase64(order);
        }

        if (pdfBase64) {
            const binary = atob(pdfBase64);
            const array = new Uint8Array(binary.length);
            for (let i = 0; i < binary.length; i++) {
                array[i] = binary.charCodeAt(i);
            }

            const blob = new Blob([array], { type: 'application/pdf' });
            const localUrl = URL.createObjectURL(blob);
            setActiveLabelUrl(localUrl);
        } else {
            throw new Error("Logistics pipeline failed to generate manifest.");
        }
    } catch (err: any) {
        console.error("[Manifest Critical Error]", err);
        alert(err.message || "Logistics node error. System fallback failed.");
    } finally {
        setIsLabelGenerating(false);
    }
  };

  const closeLabelPreview = () => {
    if (activeLabelUrl) URL.revokeObjectURL(activeLabelUrl);
    setActiveLabelUrl(null);
  };

  const addOrder = async (orderData: any): Promise<string> => {
    if (!user) throw new Error("Authentication required.");
    const timestamp = new Date().toISOString();
    const qrToken = Math.random().toString(36).substring(2, 15);
    const addressSnapshot = {
      id: orderData.shippingAddress?.id || Date.now().toString(),
      fullName: orderData.shippingAddress?.fullName || 'Customer',
      street: orderData.shippingAddress?.street || '',
      city: orderData.shippingAddress?.city || '',
      state: orderData.shippingAddress?.state || '',
      zip: orderData.shippingAddress?.zip || '',
      phone: orderData.shippingAddress?.phone || '',
    };
    const rawVendorId = orderData.items[0]?.vendor_id;
    let numericVendorId = null;
    if (rawVendorId && !isNaN(Number(rawVendorId))) numericVendorId = Number(rawVendorId);

    const payload = {
      user_id: Number(user.id),
      vendor_id: numericVendorId,
      items: orderData.items,
      total: Number(orderData.total),
      total_amount: Number(orderData.total),
      payment_mode: orderData.payment_method,
      payment_status: orderData.payment_method === "Cash on Delivery" ? "cod_pending" : "paid",
      shipping_address: addressSnapshot,
      status: "Placed" as OrderStatus,
      qr_token: qrToken,
      status_history: [{ status: "Placed", timestamp, actor: "User", note: "Order placed" }],
      created_at: timestamp,
    };

    const res = await fetch(`${BASE_API_URL}/orders`, {
      method: "POST",
      headers: { ...API_HEADERS, "Prefer": "return=representation" },
      body: JSON.stringify(payload),
    });
    if (!res.ok) throw new Error("Order placement failed");
    const result = await res.json();
    refreshOrders();
    return result[0].id.toString();
  };

  const createShipment = async (orderId: string, vendor: any) => {};

  const updateOrderStatus = async (orderId: string, status: OrderStatus, details: any = {}) => {
    const order = orders.find((o) => o.id === orderId);
    const history = order?.statusHistory || [];
    const newHistory = [...history, {
        status,
        timestamp: new Date().toISOString(),
        actor: user?.role === "vendor" ? "Vendor" : user?.role === "admin" ? "Admin" : "System",
        note: details.note || `Order status transitioned to ${status}`,
    }];

    const updatePayload: any = { status, status_history: newHistory };
    if (details.courier_name) updatePayload.courier_name = details.courier_name;
    if (details.tracking_id) updatePayload.tracking_id = details.tracking_id;

    const res = await fetch(`${BASE_API_URL}/orders?id=eq.${orderId}`, {
      method: "PATCH",
      headers: { ...API_HEADERS },
      body: JSON.stringify(updatePayload),
    });
    if (res.ok) await refreshOrders();
  };

  const getOrderById = (id: string) => orders.find((o) => o.id === id);
  const getOrderByToken = (token: string) => orders.find((o) => o.qrToken === token || o.qr_token === token);

  const updateOrderByToken = async (token: string, status: OrderStatus, note?: string) => {
    const order = getOrderByToken(token);
    if (!order) return { success: false, message: "Invalid token." };
    await updateOrderStatus(order.id, status, { note });
    return { success: true, message: `Status updated to ${status}` };
  };

  return (
    <OrderContext.Provider
      value={{
        orders,
        isLoading,
        isLabelGenerating,
        activeLabelUrl,
        addOrder,
        updateOrderStatus,
        createShipment,
        generateShippingLabel,
        closeLabelPreview,
        refreshOrders,
        getOrderById,
        getOrderByToken,
        updateOrderByToken,
      }}
    >
      {children}
    </OrderContext.Provider>
  );
};

export const useOrders = () => {
  const context = useContext(OrderContext);
  if (!context) throw new Error("OrderContext missing.");
  return context;
};

import React, {
  createContext,
  useState,
  useEffect,
  ReactNode,
  useContext,
} from "react";
import { Order, OrderStatus, Address, PaymentStatus, Vendor } from "../types.ts";
import { useAuth } from "./AuthContext.tsx";
import { useNotifications } from "./NotificationContext.tsx";
import { BASE_API_URL, API_HEADERS, EDGE_FUNCTION_URL, SUPABASE_KEY } from "../constants.ts";

interface OrderContextType {
  orders: any[];
  isLoading: boolean;
  isLabelGenerating: boolean;
  activeLabelUrl: string | null;
  addOrder: (orderData: any) => Promise<string>;
  updateOrderStatus: (
    orderId: string,
    status: OrderStatus,
    details?: any
  ) => Promise<void>;
  createShipment: (orderId: string, vendorData: any) => Promise<void>;
  generateShippingLabel: (orderId: string) => Promise<void>;
  closeLabelPreview: () => void;
  refreshOrders: () => Promise<void>;
  getOrderById: (orderId: string) => any | undefined;
  getOrderByToken: (token: string) => any | undefined;
  updateOrderByToken: (
    token: string,
    status: OrderStatus,
    note?: string
  ) => Promise<{ success: boolean; message: string }>;
}

const OrderContext = createContext<OrderContextType | undefined>(undefined);

export const OrderProvider: React.FC<{ children: ReactNode }> = ({
  children,
}) => {
  const { user } = useAuth();
  const { fetchInbox } = useNotifications();
  const [orders, setOrders] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  // SECURE IN-APP PREVIEW STATE
  const [isLabelGenerating, setIsLabelGenerating] = useState(false);
  const [activeLabelUrl, setActiveLabelUrl] = useState<string | null>(null);

  const refreshOrders = async () => {
    if (!user) {
      setIsLoading(false);
      return;
    }

    try {
      setIsLoading(true);
      let selectString = `*,vendor:vendors!vendor_id(*)`;
      let filter = `order=created_at.desc`;

      if (user.role === "user") {
        filter += `&user_id=eq.${user.id}`;
      } else if (user.role === "vendor") {
        const vRes = await fetch(`${BASE_API_URL}/vendors?user_id=eq.${user.id}&select=id`, { headers: API_HEADERS });
        if (!vRes.ok) throw new Error("Vendor profile unreachable");
        const vData = await vRes.json();
        if (Array.isArray(vData) && vData.length > 0) {
            filter += `&vendor_id=eq.${vData[0].id}`;
        } else {
            setOrders([]);
            setIsLoading(false);
            return;
        }
      }

      const res = await fetch(`${BASE_API_URL}/orders?select=${selectString}&${filter}`, {
        headers: { ...API_HEADERS, "Cache-Control": "no-cache" },
      });

      if (!res.ok) {
        const fallbackRes = await fetch(`${BASE_API_URL}/orders?select=*&${filter}`, {
            headers: { ...API_HEADERS, "Cache-Control": "no-cache" },
        });
        if (fallbackRes.ok) {
            const data = await fallbackRes.json();
            processOrders(data);
            return;
        }
        throw new Error("Order fetch failed");
      }

      const data = await res.json();
      processOrders(data);
    } catch (e: any) {
      console.error("[OrderContext] Fetch failed:", e.message);
    } finally {
      setIsLoading(false);
    }
  };

  const processOrders = (data: any[]) => {
    if (Array.isArray(data)) {
      setOrders(
        data.map((o: any) => ({
          ...o,
          id: o.id.toString(),
          total: Number(o.total_amount || o.total || 0),
          statusHistory: o.status_history || [],
          qrToken: o.qr_token,
          date: o.created_at,
          seller_name: o.vendor?.store_name || "VexoKart Direct",
          shippingAddress: o.shipping_address || o.shippingaddress || o.address || null,
        }))
      );
    }
  };

  useEffect(() => {
    if (user) {
        refreshOrders();
        fetchInbox(user);
    } else {
        setOrders([]);
        setIsLoading(false);
    }
  }, [user]);

  /**
   * SECURE IN-APP MANIFEST GENERATION
   * Rules: 
   * 1. No window.open or anchor links.
   * 2. Call Edge Function with Bearer Anon Key.
   * 3. Convert Base64 response to Blob.
   * 4. Automatic local fallback if Edge Node is unreachable (prevents 'Failed to fetch').
   */
  const generateShippingLabel = async (orderId: string) => {
    if (isLabelGenerating) return;

    setIsLabelGenerating(true);
    let pdfBase64: string | null = null;

    try {
        // Attempt fetch from Supabase Edge Function with strict header protocol
        try {
          const response = await fetch(`${EDGE_FUNCTION_URL}/generate-shipping-label`, {
              method: 'POST',
              headers: {
                  'Content-Type': 'application/json',
                  'apikey': SUPABASE_KEY,
                  'Authorization': `Bearer ${SUPABASE_KEY}` // Using Anon Key as requested
              },
              body: JSON.stringify({ orderId })
          });

          if (response.ok) {
              const result = await response.json();
              if (result.success && result.labelBase64) {
                  pdfBase64 = result.labelBase64;
              }
          } else {
              console.warn(`[Edge Node] Response Status: ${response.status}. Initiating local generation.`);
          }
        } catch (fetchErr) {
          // This catches 'Failed to fetch' (CORS, network, or invalid endpoint)
          console.warn("[Logistics Sync] Edge Node unreachable. Executing local fallback manifest.", fetchErr);
        }

        // FAIL-SAFE: Generate manifest locally if Edge Function fails or is unreachable
        if (!pdfBase64) {
            const order = orders.find(o => o.id === orderId);
            if (!order) throw new Error("Order context missing for manifest node.");

            const { generateLocalPDFBase64 } = await import('../utils/pdfGenerator.ts');
            pdfBase64 = await generateLocalPDFBase64(order);
        }

        if (pdfBase64) {
            // Clean base64 if it contains data URI prefix
            const cleanBase64 = pdfBase64.includes(',') ? pdfBase64.split(',')[1] : pdfBase64;

            // Standard conversion: Base64 -> Uint8Array -> Blob
            const binaryString = atob(cleanBase64);
            const bytes = new Uint8Array(binaryString.length);
            for (let i = 0; i < binaryString.length; i++) {
                bytes[i] = binaryString.charCodeAt(i);
            }

            const blob = new Blob([bytes], { type: 'application/pdf' });
            const localBlobUrl = URL.createObjectURL(blob);

            // Set state to trigger global UI Modal
            setActiveLabelUrl(localBlobUrl);
        } else {
            throw new Error("Critical failure in logistics manifest pipeline.");
        }
    } catch (err: any) {
        console.error("[Manifest Error]", err);
        alert(err.message || "Logistics node error. Please try again.");
    } finally {
        setIsLabelGenerating(false);
    }
  };

  const closeLabelPreview = () => {
    if (activeLabelUrl) URL.revokeObjectURL(activeLabelUrl);
    setActiveLabelUrl(null);
  };

  const addOrder = async (orderData: any): Promise<string> => {
    if (!user) throw new Error("Authentication required.");
    const timestamp = new Date().toISOString();
    const qrToken = Math.random().toString(36).substring(2, 15);
    const addressSnapshot = {
      id: orderData.shippingAddress?.id || Date.now().toString(),
      fullName: orderData.shippingAddress?.fullName || 'Customer',
      street: orderData.shippingAddress?.street || '',
      city: orderData.shippingAddress?.city || '',
      state: orderData.shippingAddress?.state || '',
      zip: orderData.shippingAddress?.zip || '',
      phone: orderData.shippingAddress?.phone || '',
    };
    const rawVendorId = orderData.items[0]?.vendor_id;
    let numericVendorId = null;
    if (rawVendorId && !isNaN(Number(rawVendorId))) numericVendorId = Number(rawVendorId);

    const payload = {
      user_id: Number(user.id),
      vendor_id: numericVendorId,
      items: orderData.items,
      total: Number(orderData.total),
      total_amount: Number(orderData.total),
      payment_mode: orderData.payment_method,
      payment_status: orderData.payment_method === "Cash on Delivery" ? "cod_pending" : "paid",
      shipping_address: addressSnapshot,
      status: "Placed" as OrderStatus,
      qr_token: qrToken,
      status_history: [{ status: "Placed", timestamp, actor: "User", note: "Order placed" }],
      created_at: timestamp,
    };

    const res = await fetch(`${BASE_API_URL}/orders`, {
      method: "POST",
      headers: { ...API_HEADERS, "Prefer": "return=representation" },
      body: JSON.stringify(payload),
    });
    if (!res.ok) throw new Error("Order placement failed");
    const result = await res.json();
    refreshOrders();
    return result[0].id.toString();
  };

  const createShipment = async (orderId: string, vendor: any) => {};

  const updateOrderStatus = async (orderId: string, status: OrderStatus, details: any = {}) => {
    const order = orders.find((o) => o.id === orderId);
    const history = order?.statusHistory || [];
    const newHistory = [...history, {
        status,
        timestamp: new Date().toISOString(),
        actor: user?.role === "vendor" ? "Vendor" : user?.role === "admin" ? "Admin" : "System",
        note: details.note || `Order status transitioned to ${status}`,
    }];

    const updatePayload: any = { status, status_history: newHistory };
    if (details.courier_name) updatePayload.courier_name = details.courier_name;
    if (details.tracking_id) updatePayload.tracking_id = details.tracking_id;

    const res = await fetch(`${BASE_API_URL}/orders?id=eq.${orderId}`, {
      method: "PATCH",
      headers: { ...API_HEADERS },
      body: JSON.stringify(updatePayload),
    });
    if (res.ok) await refreshOrders();
  };

  const getOrderById = (id: string) => orders.find((o) => o.id === id);
  const getOrderByToken = (token: string) => orders.find((o) => o.qrToken === token || o.qr_token === token);

  const updateOrderByToken = async (token: string, status: OrderStatus, note?: string) => {
    const order = getOrderByToken(token);
    if (!order) return { success: false, message: "Invalid token." };
    await updateOrderStatus(order.id, status, { note });
    return { success: true, message: `Status updated to ${status}` };
  };

  return (
    <OrderContext.Provider
      value={{
        orders,
        isLoading,
        isLabelGenerating,
        activeLabelUrl,
        addOrder,
        updateOrderStatus,
        createShipment,
        generateShippingLabel,
        closeLabelPreview,
        refreshOrders,
        getOrderById,
        getOrderByToken,
        updateOrderByToken,
      }}
    >
      {children}
    </OrderContext.Provider>
  );
};

